local System = require("System.System")
local readonly = System.readonly
local Text_AwakerStory = readonly({
  AwakerStory_100415_Content = {
    Text = "A.F.3@2年2月12日\n在雕像工作室參觀時，將已經完成的雕像作品塗抹上顏料。色彩設計稱得上別出心裁，但是和原本雕像組的設計體系違背。\n事後答應免費承擔所有雕像作品的上色工作。或許以後的確有可以共同創作的機會。\n證明人：珊\n……\n\nA.F.3@2年4月9日\n企圖在鑰塚中挖掘屍體作為模特，未遂。被現場抓獲後，邀請巡查人員扮演屍體。\n證明人：奧吉爾\n……\n\nA.F.3@2年4月11日\n竊取廚房食材作為畫作參考對象。雖然食材被成功拯救，但香料醃製的時機與食材風味都被破壞殆盡，失去了價值。\n至於食材屬性與來源……就暫時不方便透露了。\n證明人：杜勒賽因\n……\n\nA.F.3@2年6月29日\n私自潛入校秘典書庫，將自己創作的巨幅畫作掛在牆面中央。午夜時分，受學校銀芯能量密度影響，異形生物從畫作中跑出，對部分未受保護的藏品造成破壞。\n事後主動申請進行維修工作，過程中破壞的藏品比怪物破壞得還要多。校方已緊急中止了他的維修行為。\n證明人：訶勒特\n……\n\nA.F.3@2年7月23日\n潛入黑池，企圖使用池水作為顏料。塔薇並沒有打擾他，但黑池本身的力量讓他遭受了不小的傷害。\n我還真有些期待，他會用黑池創作出一幅怎樣的圖景來？\n證明人：阿利斯泰爾\n……\n\n——《皮克曼檔案·違規記錄》"
  },
  AwakerStory_100415_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_100416_Content = {
    Text = "在收到那份來自葬骸城的邀請之前，皮克曼原以為這世上永遠不會有自己這樣的人的容身之地。\n在王邸餐桌上見到的那極致瘋狂的景象令他輾轉難眠。那雙能夠看到不同世界景象的眼睛，在這宴席上得到了真正的饜足。\n當他從夢境中醒來、葬骸城從他眼前消逝時，皮克曼的遺憾很快便成為了無盡的渴望——他渴望著再次去到那座夢中的城邦，渴望再次見到那無盡瘋狂的絕景。沿著這份渴望，他嘗試了一切瘋狂的舉動。最終，他躍入融蝕裂隙，用融蝕液作畫，將自己徹底暴露在那可怖的黑色之中。\n每個人都有自己需要完成的事。他有著能看到世界瘋狂真相的眼睛，他堅信自己生來就是為了藝術而燃燒的，這是他的使命。\n如他所願，融蝕為他帶來了癲狂與痛苦，也讓他再次見到了在葬骸城中所體驗到的景象，他眼中那倒錯的世界，在融蝕的侵蝕下變得更加狂野絢麗。在漫長的痛苦中，他拿起畫筆，日復一日、一刻不停地畫著。他是一個忠於職守的寫實派畫家，他必須要把這些只有他能看到的景象記錄下來。\n痛苦變得愈發強烈，當皮克曼已無法再握緊手裡的畫筆時，他明白自己的時間就要到了。完成最後那幅畫的最後一筆之後，他躺進自己早已準備好的棺木，等待死亡的來臨。\n融蝕帶來的疼痛與混亂讓皮克曼的大腦變得渾濁，在死亡冰冷的懷抱中，他安然地閉上了眼。但第二天，明亮的月光再次喚醒了他。融蝕的痕跡與痛苦奇蹟般地消退了。在長達數天的生長中，他的肢體變得修長而彎曲，他的犬齒與利爪變得堅硬而鋒利。他嗅到了來自墳墓與魂靈的味道，世界瘋狂混亂的景象在他的眼裡變得從未有過的清晰。\n他欣喜地望著自己半人半食屍鬼的軀體，巨大的幸福感湧上心頭。命運為他降下了詛咒，也為這詛咒彌補了他罕見的天分。葬骸城的經歷喚醒了他體內微薄的食屍鬼的血脈，在融蝕的催化下，他完成了自己的轉變。\n身邊的墓碑如同歡聚的人群，圍著他跳笨拙的舞蹈。巨大的血月睜開猩紅的眼，向他微笑。他的藝術並不屬於這個世界，如今，他已經知曉自己將要去往何方。\n皮克曼躺在屬於自己的那道棺槨之上，張開雙臂，加入這場孤獨的狂歡。\n他將要離開人類的城市，去往那個屬於他的應許之地。\n他知道，他所追求的一切，正在那裡等待著他。"
  },
  AwakerStory_100416_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_100417_Content = {
    Text = "半人半食屍鬼的繪者，擁有他人難以企及的天賦，創作出的食屍鬼畫作能模糊畫中世界與真實世界的邊界，讓觀看者真正地身臨其境。\n不過皮克曼從來不認可瘋癲的超現實主義畫家這個稱謂。在他的宣告裡，自始至終，他都是一個只會刻畫真實世界的寫實主義者。"
  },
  AwakerStory_100417_Title = {
    Text = "基礎資料"
  },
  AwakerStory_100417_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_100418_Content = {
    Text = "異類。怪胎。流淌著怪物血液的壞種。褻瀆藝術的瘋子……\n皮克曼的眼前鋪開一張畫布，謾罵聲與其他聲音一同在畫布上塗抹出豔麗的色彩。\n他躍入這個絢爛的世界，在瘋狂的色彩中徜徉。他殷切地盼求著，將別人領入自己的畫作，帶他們見證世界最真實的樣子。\n現實的尖刺無數次洞穿他的心臟，人與人之間的互相理解比打開兩個世界的邊界更加困難。\n從人類到食屍鬼，從人類城市到葬骸城，這條道路曲折漫長。他一次次被中傷，又一次次站起。他早已明白，不存在真實也不存在虛假。痛苦與瘋狂，就是世界的真相。而他的職責，就是將這一切忠實地描繪出來。\n描繪的意義，只在於描繪本身。\n他將全部的生命與激情獻予繪畫。他的期許鮮有回應，他的追逐從未停息。"
  },
  AwakerStory_100418_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_100419_Content = {
    Text = "美術學院繪畫系的課程繁冗庸常，其中大部分沒有在我的人生中留下絲毫痕跡，但我至今仍能回想起A.F.3@2年那節模仿繪畫課。\n馬修先生在藝術協會中極具名望，他的教室人滿為患。我們簇擁在馬蒂斯的《奢華、寧靜與愉悅》前，此時我偶然注意到，角落裡一個消瘦的年輕人正在速寫本上瘋狂地塗抹著。我湊到他面前，準備看看他的模仿畫作，卻看到一片墓群的雜亂石雕。\n「看吶！正在分娩的食屍鬼女王，正在籌備一場嬰兒的血宴……多麼瘋狂，多麼優雅！」\n他興奮地抬起頭來望著我，瞳孔在煤氣燈下呈現出奇異的血紅色，彷彿蒙著紅苔蘚的棺槨。我感到恐懼、暈眩，卻無論如何也無法挪開眼。在那雙眼睛裡，我看見了完全不屬於這個世界的景象。\n皮克曼，在我第一次見到他的時候我就知道，他和我們不一樣，他的人生註定是艱難而不凡的。\n熟識以後，我偶爾會去參觀他的畫室。我親眼見到他用腐朽的屍體做模特，用自己的鮮血做顏料。站在那些瘋狂的畫作面前，我彷彿能聽到畫布裡傳來的啃噬聲。\n藝術界無論是哪個派別，沒有人認可皮克曼的創作，所有的畫展與沙龍都將他拒之門外。他看起來毫不在意，仍然樂觀堅定地追求著他的藝術，但他的純粹讓他從來都無法藏起自己的失落與痛苦。他的天賦令人震撼也令人恐懼，沒有人能真正接受這一點，我也一樣。\n在離開前的最後那段時間，皮克曼陷入巨大的痛苦與興奮交織的狀態，我原本以為那是某種必然會發生的心理層面問題，直到某天，我親眼看到他那彎曲的四肢與利爪、親眼看到他眼中那瘋狂的世界。那是我無法抗衡的恐懼，我只能嘗試將它忘記。在我準備徹底結束與皮克曼的聯繫之前，他主動找到了我，向我作了告別。\n如今我站在現代藝術館光潔的展廳裡，看著那幅被丟棄在角落的皮克曼真跡時，依然能聽見畫布深處傳來指甲刮擦的聲響。《地下狂歡》，那是我第一次見到皮克曼時他所創作的畫，也是他留給我的告別禮物。皮克曼身上或許有一些不應接近的禁忌謎題，但我仍然把這幅畫留了下來。無論他身上發生了什麼我不應知道的事，至少有一點是肯定的——他是我見過最具天賦的藝術家。\n昨夜，我又夢見大一的繪畫課教室。年輕的皮克曼在房間的角落，衝我大聲地笑著。\n「食屍鬼？不，埃弗，從頭到尾，我畫的都是真相、是人類！」\n月光在他眼中分裂成無數慘紅的星點。那是深淵首次向我展露微笑。\n\n——節選自《畫家埃弗回憶錄》"
  },
  AwakerStory_100419_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11158_Content = {
    Text = "時間：A.F. 299年@1月@2日\n地點：實驗室UG-C03，@2@1，@4，倫蒂尼恩。\n參與人員：@1，@2，@4，@3\n實驗物件：W\n受試者資訊：\n軀體為成年人類女性，出生於A.F. 280年6月18日，原籍不明，於@2大學求學途中染病逝世，隨後為地外精神生命體@1佔據軀體且恢復生命，繼續原有生活。\n@1具有精神遷移及置換的能力，且可以直觀地觀察融蝕。儘管人類軀體無法觀察融蝕，@1種族的能力也讓受試者從精神層面感知到了融蝕的存在。因此，在受試者於2年零8個月前初次觀測到融蝕時，受試者便試圖進行精神遷移以避免受到進一步侵蝕。\n儘管@1保留了對融蝕的感知能力，但受試者無法擺脫其影響，精神體遷移失敗。經過多次嘗試後，受試者主動聯繫@3大學，希望@3將其製成喚醒體，直接促成了本次實驗。\n——節選自《實驗記錄：活體提取銀芯的可能性》"
  },
  AwakerStory_11158_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11159_Content = {
    Text = "銀鈴般的甜笑空洞迴響，嬌小的軀體於黯淡燭光中浮現。她是戴罪者的恐懼與渴望，是垂死者的甘霖與毒酒，帶來甜蜜的痛苦與浪漫的瘋狂。她那永不離手的皮鞭落在皮肉上的「啪啪」聲，正是於黑暗中奏響的邪惡樂章。"
  },
  AwakerStory_11159_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11159_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11160_Content = {
    Text = "與菲茵特團聚後，汀克特便在彌薩格大學安定了下來。在P-063號歌劇院@2事件中再次受傷的汀克特更加畏懼生人，因此變得深居簡出。與高亢嘹亮的歌喉不同，她日常交談的聲音甘美清澈，但聽過的人卻寥寥。\n有好事者試圖為汀克特在校園內的登台造勢，還從不知何處找出了汀克特早年在歌劇院演出的海報，張貼滿校園的各處宣傳角。\n汀克特不願意迎合這些願望，那些熱切的期望只會讓她想要遺忘的過往回憶再次翻騰。\n「結束這荒誕的悲劇吧。陪在你的身邊，我已經別無所求。如果可以的話，就讓我被這個世界遺忘也無所謂。」\n「不要，汀克特。我們未來相伴的日子還很長，這裡已經不是荒星，我也不再是你的拖累。你應當找到自己想做的事情，為自己而活。」"
  },
  AwakerStory_11160_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11161_Content = {
    Text = "彌薩格大學裡，「預科生必須要和蘿坦戰鬥才能成為調查員」的校園傳說愈演愈烈，讓學生們對黑衣女劍士的恐懼達到了極點。不少專精於理論研究的學生光看見黑色裙角都會被嚇出一身冷汗，生怕和「戰鬥狂」對上視線，命喪訓練場。\n主編漢娜·皮斯利與當事人進行了一場簡短的特約訪談，訪談中，蘿坦小姐作出了如下發言：\n「我可沒那麼多時間陪嬰兒玩過家家。」\n「軟腳蝦不配成為我的對手——你是其中之一嗎？還是說，你也擁有直面混沌的膽量？」\n\n——截至發稿日前，主編都沒有離開過學生宿舍。本期《M大校報》由實習編輯霍華德進行印刷與發行。"
  },
  AwakerStory_11161_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11162_Content = {
    Text = "A.F.315年@1月@2日\n茜爾維婭醫生建議我把自己的想法記在本子上，好鍛煉記憶力。大家都說醫生懂得很多，肯定能幫助我。所以拜託了，明天的我，可千萬不要忘記這個筆記本的用處啊！\n今天我完成了排氣管的製作及組裝，現在它既可以排氣，又不會干擾到輔助軟管的行動。這應該是最後一步了吧？起碼目前我沒有發現問題，但也不排除我忘了哪個地方的螺絲……沒錯，我一定忘了什麼，不是螺絲就是管道，或者是軸承潤滑？機油？老實說，我一直隱隱覺得幻影號有哪裡不對勁。它總是很……欠缺？是這個詞嗎？它少了一個很關鍵的東西，比引擎還關鍵。沒有它我無法啟程，無法踏上那通往未知的旅途，因為那是我們的@2\n我為什麼要說我們？我和誰？我是不是有過……我記得，好像，@2@4@3\n呃，我頭好疼。\n不過這個筆記感覺蠻有用的，這樣我明天就可以從這裡接著回想啦，或許真的能想起來也不一定呢？\n——諾締拉日記本中唯一的一篇日記。"
  },
  AwakerStory_11162_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11163_Content = {
    Text = "未受感召者是可憐的，因其無法理解不朽的真意。世俗的紛爭是無謂的，因其只是過程中的淺薄消遣。\n我曾直視，我曾品嘗，我早已明悟此身使命。\n但是，但是啊……命運是何等殘酷！您為什麼……沒有再次選擇您最忠誠的祭司？\n——一定是您在賜予我試煉，您在考驗我的信念。我在離故國最遙遠的地方，在沒有您的恩澤的時刻，我的信念經由萬年，從未改變。\n我未能成為那個迎接您重生的人，但我為您的重生做了一切準備。我會為您另尋一片永恆的國土……不甘與榮幸皆在我身，我只能獨自負擔這份責任……\n請原諒我醜陋的嫉恨。只要能再度得見您的威儀，只要能再度建起您的王國，我願去做任何事。"
  },
  AwakerStory_11163_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11164_Content = {
    Text = "滿頭珠翠，輕紗繾綣，內心被隱藏在極致的妍麗之下。\n總有人覺得泰旖絲是個愛慕虛榮的輕浮傢伙，但這也許也只是她所戴上的面具之一。\n「呀，小哥在寫些什麼呢？讓我也來幫忙吧——」"
  },
  AwakerStory_11164_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11164_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11165_Content = {
    Text = "用過的燒瓶要清洗如新，被實驗燒壞的桌子要打磨到反光，天平每三日就要重新校準。出於對科學、對世界奧秘的狂熱與尊重，她對身邊的人與事都保持著極高要求。\n當然，這要求也適用於她自己——畢竟，不是所有人都能平靜擁抱死亡，主動要求成為喚醒體的。"
  },
  AwakerStory_11165_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11165_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11166_Content = {
    Text = "A. F. 315年@1月@2日，08：13 a. m.\n審查會現場響應第三小隊及融蝕物品控制及管理（以下簡稱DISM）β7組成員抵達融蝕區域L-E-933（即南華克大街@2號，羅傑斯蠟像館原址），接手第一小隊與DISM α2組的任務，進行區域無害化工作。\n09：24 a. m.\nDISM成員詹姆斯在清除蠟像館地下區域時出現頭痛、噁心、暈眩等症狀。\n10：47 a. m.\n第三小隊成員羅蘭德，DISM成員扎克瑞、博爾頓逃離地下區域。三人匯報稱，地下區域的黑暗將他們吞入漂浮在一片星空之中，具有形體的顏色在空間中彼此交纏，絢麗的同時讓人渾身冰涼。接著這些顏色凝聚成無數老鼠，並飛速向他們襲來。\n博爾頓拒絕繼續作業，返回審查會倫蒂尼恩辦公室。第三小隊羅蘭德與DISM扎克瑞則陪同第三小隊隊長費舍再次進入地下區域進行相關檢查。\n13：03 p. m.\n經檢測搜尋，第三小隊隊長費舍於地下區域殘留的融蝕蠟中找到並回收銀芯L3202。已交由彌薩格大學進行後續處置。\n——「融蝕區域L-E-933無害化處理報告」"
  },
  AwakerStory_11166_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11167_Content = {
    Text = "24搬來不到一個月便發現家裡遭了小偷。\n先是乳酪，隨後是麵包、牛奶、番茄……家裡的食物總會悄無聲息地少那麼一點點。\n她耐心蹲守了好幾天，終於發現了罪魁禍首——一隻老鼠。它左搖右晃躲過了24為它設置的陷阱，抓起兩朵香菇就消失在了地窖門後。\n24掀開地窖門，順著潮濕發黴的階梯下來，發現這裡竟通向一個地下水道。\n老鼠舉著香菇竄進陰影中。24跟了過去，在黑暗中望見一雙明亮的眼睛，像小狼崽。她將碎布穿在身上，在接近零下的溫度裡蓋著舊報紙，全身抖得厲害。\n24的心被微微刺了一下。\n「蘑菇最好不要生吃，會生病的。」\n小孩依舊沉默。\n24上去煮了一鍋蘑菇湯，盛了一小碗擺在桌上，隨後便睡覺去了。她每天凌晨6點就要起來上工，幾乎沒什麼休息時間。\n等到第二天醒來，碗還放在原本的位置，但是湯被喝得乾乾淨淨。\n那以後，24時不時多做一點吃的，用以款待樓下的鄰居。對方也會偶爾回饋她一些小禮物，通常是一些不知道哪裡撿來的小首飾、玩具……\n\n新的默契，就此達成。"
  },
  AwakerStory_11167_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11167_UnlockDesc_1 = {
    Text = "通關主線普通第2章「以蠟像之名」"
  },
  AwakerStory_11168_Content = {
    Text = "我們的好朋友，神通廣大的漢娜·皮斯利，不知從何處挖到了希萊斯特的研究資料。託這位行事大膽的記者的福，原本是保密級別的資料和她們之間那段短小的訪談，現在鬧得人盡皆知了。\n\n漢娜在閱讀了保密資料後，向那位平時便缺乏情緒的希萊斯特，提出了一個問題。\n\n「大多數喚醒體都有未竟之願，這是他們與學校合作的基礎之一。但是在這份資料中，你的願望一欄是空白的。你沒有想要完成的事嗎？或者，你成為喚醒體的意義在哪呢？」\n\n「有的，我有的。」\n\n少女的表情沒有露出破綻，和往常一樣虛無，高潔。如果不是這聲短促的、焦急的回答，記者小姐幾乎要以為對方沒有聽見自己的問題。\n\n\n「我會找到願望的……大家是如此希望的，所以，我會找到的。」\n\n溫柔的聲音，恍如一場一觸即碎的夢幻。"
  },
  AwakerStory_11168_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11169_Content = {
    Text = "一言一行踐行忠貞，一舉一動貫徹美德。\n儘管「知禮守義，嚴於律己」已經深深刻在魂靈之上，但這名美德騎士，無疑還是孩童的樣貌。\n不過還請別擔心，即便代價是永遠的消亡，奧吉爾也會拼盡全力完成主君的指令。\n願那日永遠不要來臨。"
  },
  AwakerStory_11169_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11169_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11170_Content = {
    Text = "年幼的王沉睡於王座之上，於夢醒時分示下詔諭，權威遍及天下王土。\n夕日未落，王已然感到疲倦。他厭倦了自身的權能，也厭倦了超人的智慧，厭倦了信徒狂熱的崇拜和供奉，也厭倦了超越萬古的長夢。\n沒人知道他在漫長的睡眠中都夢到了什麼，但他們應當慶倖自己享有此等無知的幸福。"
  },
  AwakerStory_11170_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11170_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11171_Content = {
    Text = "「仁慈的父神曾經勸誡：你們要愛護天上的、地上的、水裡的、土裡的一切。因為萬物皆是我的子嗣。」\n「因此，我要說：將所有苦難加於我身吧，讓那些受生活所難、瘟疫所苦的得以解脫，讓那些病痛、那些瘋狂，全部同冰雪般融化。讓你們，我的姐妹弟兄，得到恆久的幸福。\n」將我燃燒吧，將我的骨磨滅，將我的肉毀去。只要你們能夠獲得慰藉，我亦沒有怨言。「\n——B. F. 1@1，5月30日，薩爾@1多·馬丁@2·伊@1亞斯，於@3審判所留"
  },
  AwakerStory_11171_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11172_Content = {
    Text = "菲茵特是一粒褪色的、難以破殼的種子。\n人們因她的殘缺而憐憫她，因她的虛弱而愛憐她。\n知道她是自願留在殼中之人，已然化作齏粉，成為星之塵埃。"
  },
  AwakerStory_11172_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11172_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11173_Content = {
    Text = "在@3@1事件後，萊克成了彌薩格大學的特邀顧問。\n萊克是個稱職的顧問。上至教授離奇失蹤或儀器莫名損壞，下至尋貓找狗之類的瑣事，萊克都能耐心且敏捷地交付令人滿意的結果。\n很快，萊克就因其獨特的外貌、體面優雅的舉止和助人為樂的好習慣，成為了風靡彌薩格萬千少男少女的偶像型角色。\n德克斯特教授曾這麼感歎：「風頭都被年輕人搶去了。」\n但在他漸漸融入校園後，大家發現，萊克出現在人前的時間日益減少。\n與此同時，彌薩格的某間廢棄地下室內，開始頻頻出現搖骰的響動聲。"
  },
  AwakerStory_11173_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11174_Content = {
    Text = "第一次見到她的人不會產生任何靠近或溝通的想法，生存的本能會拼命發出遠離的預警。\n那是一個徹底瘋狂的人，或者說一頭徹頭徹尾的野獸。\n如果能夠重新選擇，她或許會更願意當一頭野獸，也好過作為人經歷的一切。\n她從不信任任何人，當她猩紅的雙眼看向你時，那眼中的不是懷疑，而是冷漠與殺意。\n她早已不屑懷疑，所有人在她眼中都是同樣的卑劣。\n如果需要一條與她相處的忠告，那就是不要試圖馴服一頭真正的野獸，那不是任何溫順的存在，只要有一絲機會，她的利爪與獠牙就會貫穿你的喉嚨。\n儘快在她盯上你之前逃跑吧，並祈禱她的下一個獵物不是你。"
  },
  AwakerStory_11174_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11175_Content = {
    Text = "來跳舞吧！跳一支歡快的舞，跳一支瘋狂的舞！隨著她一起歡笑吧，將氣氛炒熱至最高點。\n到那時候，就該輪到主角登場了。\n在那聚光燈的交匯點，瘋狂的魔術師已經將手探入了她的長禮帽。至於她從那無盡虛空中掏出的，是五彩斑斕的飄帶，是展翅騰飛的白鴿，還是恐怖怪物的利爪……恐怕只有她自己才知道了。"
  },
  AwakerStory_11175_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11175_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11176_Content = {
    Text = "那是德克斯特教授從費弗爾海岸旅行歸來時，帶回的紀念品。\n費弗爾溫潤的海洋氣候舒適宜人，有著百年歷史的塞瓦達療養院就坐落在海濱，每年選擇在那裡享受假期的旅人不計其數。\n這只被水漬與海草纏繞的玻璃瓶中，裝著少許剔透的粉末。它既不是海難者留下的漂流瓶，亦不是當地土產的砂礫工藝品。德克斯特教授顯然已經注意到了，那只瓶子裡裝的是銀芯粉末，換句話說，是一個寄宿於其中的意志。\n他說那是從當地漁民手中買來的，漁民閃爍其詞地講述了最近遭遇的怪事。幾天前的清晨，漁民出海時，趕上了一陣怪異的魚潮。現在不是產卵或越冬的時節，魚群卻聚在一處久久不去。將沉甸甸的漁網拖上來，發現網裡撈到了一只奇怪的瓶子。漁民覺得稀奇，又隱隱感到不安，好像會被這奇怪的瓶子詛咒，獲得厄運一般。此後幾天，在這片海域便再也捕不到魚了。"
  },
  AwakerStory_11176_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11177_Content = {
    Text = "算術：零分。奧瑞塔甚至都拿了2分。\n英語：不及格。花了很長時間才理解「輪班」和「狗屎」之間的差別\n……\n歷史：不及格。聲稱卡里古拉是最傑出的羅馬皇帝，因為他修了很多競技場\n\n危險評級：C。與其他喚醒體相處時，呈現出一定程度攻擊性。威脅不大，無需特別關注\n備註：該生自理能力幾乎為零（又一個被奴隸制荼毒的傢伙），需要時刻關注，不能再讓她把雪花膏當作潔牙劑使用了。\n——節選自A.F.313年，《彌薩格年度學生檔案》"
  },
  AwakerStory_11177_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11178_Content = {
    Text = "@2年，阿卡古城。\n歷經千年的饑渴終於爆發，殺戮，飲血，殺戮，飲血——最終，他面前只剩一望無際的沙漠與無數乾涸的屍體，就連禿鷲都害怕靠近他。\n他跪在黃沙中，哈哈大笑：暢快！真@1暢快！\n接下來，就由他親自為這場殺戮盛宴，畫下完美的句號吧。\n戰士咬開自己的手腕，他吸乾了自己的鮮血，也一同倒在這片猩紅的血池中。"
  },
  AwakerStory_11178_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11179_Content = {
    Text = "「奧爾拉，從今天開始，你的所有詩我都會幫你好好珍藏起來的。以後，我就用我的花，來換你的詩吧！」\n「柯蕾特，你一定會回來救我的……對嗎？」"
  },
  AwakerStory_11179_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11180_Content = {
    Text = "昨日18時，位於彌薩格大學親王大樓地下的CB-101室遭到不知名人士的破壞。加固房門遭到嚴重破壞，室內外牆面均有黑色閃電狀焦痕分佈，現場一片狼藉。\n「瞬時的超強電流可以導致這樣的痕跡，」對牆面的焦痕，電氣工程專業的亞當姆斯博士這麼評價，「這需要極大的電壓。如果是普通儀器，它將十分巨大，很難掩人耳目。但如果是銀芯……一切皆有可能。」\n在銀芯常年處於喚醒系嚴加看管的情況下，很難想像有人能夠私自使用銀芯而不被察覺，也因此，更多的目光轉向了體內具備銀芯能量的喚醒體。\n「要我說啊，這事兒肯定是她幹的。」一名不願透露姓名的喚醒體系學生如此告訴記者。當被詢問具體是誰時，他顯得有些緊張，「就是『她』啊，被稱為『嘀嗒人』的那傢伙！你沒聽過她身體裡連續不斷的電流聲嗎？一說到電流我就想到她了，肯定是。」\n不少學生發表了類似的懷疑。但這位行動如發條木偶，面帶詭異微笑的喚醒體並非孤立無援，幾位調查員公開支持艾瑞卡，並呼籲所有人以事實為重，以證據為準，切勿因為個人偏見對他人造成傷害。\n對此，喚醒系代理負責人索科洛娃博士拒絕發表回應。事件仍在進一步調查中。\n——節選自《彌薩格日報》，《CB-101室爆炸事件初探》"
  },
  AwakerStory_11180_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11181_Content = {
    Text = "她總是倨傲地以「神之母」自稱，冷漠而充滿敵意地將每個人排除在自己的安全範圍之外。初次見面的人，很難將她與那個驕縱的小公主聯繫起來。\n「但她們本質上還是同一個人，」守密人卻總是固執地向每個人傳達，「只要你見過她一個人狼吞虎咽小蛋糕的模樣就知道了。」"
  },
  AwakerStory_11181_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11181_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11182_Content = {
    Text = "天才與瘋子只有一線之隔。作為彌薩格曾經最耀眼的天才，她的墮落也如同大廈傾倒，從那理性的廢墟中爬出的，只剩下一隻最瘋狂的惡鬼。\n她如常披好科學的外衣，將生命、人性、愛與毀滅倒進坩堝，炮製成了摧毀世界的毒藥。"
  },
  AwakerStory_11182_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11182_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11183_Content = {
    Text = "不要對水母的知性抱有什麼期待，奧瑞塔並不能理解自己經歷了什麼，唯一能肯定的，就是她曾在那個無人村落居住過。每每聊到過去的故事，她都會用不懂裝懂來轉移話題，因此奧瑞塔對融蝕現象、災厄異動等學科研究幾乎起不到助力。\n但作為喚醒體中難得性格無害的個體，奧瑞塔深受喚醒體系師生喜愛，主導了融蝕生物學研究的訶勒特也對她格外關心。\n順便一提，與水母群體意識融合的她獲得了分裂增殖的能力。即使增殖出的只是普通水母，奧瑞塔也會興奮地舉著「同伴」挨家挨戶炫耀——雖然分不清同伴個體的她並不清楚，自己每次捧出來展示的都是同一只水母。"
  },
  AwakerStory_11183_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11184_Content = {
    Text = "■檔案編號：AF315-C01\n■喚醒體代號：@2行者\n該喚醒體於A.F.315年@1月被首次觀測。\n在首次開展「人工密境」實驗時，受同源之物精神共鳴的影響，以我校@2級學生拉蒙娜·德克斯特精神領域為基礎展開的「人工密境」意外突破了維度界限。\n時任守密人在該「人工密境」中，首次確認了維度外世界的存在，同時也確認了@2的力量將對拉蒙娜·德克斯特造成怎樣的影響。\n此後，喚醒系科研所正式展開了針對「本源喚醒體」的研究。\n同時，對拉蒙娜·德克斯特力量控制課程的教案規劃也正在提上日程。"
  },
  AwakerStory_11184_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11185_Content = {
    Text = "身披黑紗，長袍之下掩藏著彌利亞姆瘦骨嶙峋的身軀。\n她靜默無聲，呈現出一副交織著虔誠與悲苦的面容，如同壁畫當中的聖母像那般，帶有無盡的神秘意義。\n她傾注全部身心，等待一個特殊的時刻。\n就快近了，那約定之日即將來臨……"
  },
  AwakerStory_11185_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11185_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11186_Content = {
    Text = "希萊斯特加入學校的第一分鐘，便被朵爾帶走並接受了全面評估。\n作為非大學流程召喚的喚醒體，希萊斯特的精神狀態出奇穩定。但與之相對的，無論是精神體強度，還是作為銀芯強度評判標準的諾斯指數，希萊斯特都遠遠沒有達到喚醒體的標準。\n然而，如同虛空中盛開的無形之花一般，她作為喚醒體降臨在了世界上。\n儘管在日常活動與外勤任務中均未表現出異常，但通過資料監控我們得知，希萊斯特的情況不容樂觀：她身上微弱的意志正在不斷流失。\n目前，喚醒系正在籌備一個小規模教團，希望以供給信仰的方式維持希萊斯特的存在，有意加入且精通水性者請聯繫茜爾維婭老師。"
  },
  AwakerStory_11186_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11187_Content = {
    Text = "一道疤痕橫亙在他的脖頸之上。他的族人從一道疤痕中獲得死亡，而他從一道疤痕中獲得了力量。\n被驅逐出領地的喪家之犬，舔舐著失敗與絕望的苦澀，被困於茫茫大海之時，他向神祈求了超越的力量。\n神的使徒回應了祈禱，斬斷了他的脖頸。\n神的使徒回應了祈禱，在斷頸上培植出了不朽的殘片。\n神的使徒回應了祈禱，將他領入了永生的殿堂。"
  },
  AwakerStory_11187_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11188_Content = {
    Text = "她有過令人豔羨的出生：被當作唯一繼承人撫養長大的孤女，何其幸運。\n她有過令人驚訝的天慧：一歲能言，二歲能辯，三歲時便開始了對世界的啟蒙。\n她有過令人讚歎的才能：過目不忘，握劍成招。以不可思議的稚齡，滿分通過了彌薩格大學嚴苛的預科課程。\n她有過值得互相依託後背、值得攜手奔赴暗黑與未知的同伴。\n<Italic:她有過……>"
  },
  AwakerStory_11188_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11189_Content = {
    Text = "朵爾的加入，是彌薩格大學在外界眼中唯一的高光時刻。\n學界無數人哀歎，哀歎天降奇才也無法逃脫世俗的桎梏——她居然為了財富，被一所名不見經傳的大學收編，沾染上了銅臭。\n在外界口誅筆伐她的自甘墮落時，朵爾在彌薩格獲得了比黃金更珍貴的東西。\n她得以越過物質科學的邊界，觸及現實領域的面紗，那面紗之下，藏著她願付出生命去追求的東西。\n研究「銀芯科技」的危險性，不亞於刀尖上跳舞，而朵爾成為了最認真、最勤勉、最優秀的舞者。\n當融蝕痕出現時，科學的舞者也並未停止舞動，而是抓緊有限的時間旋轉，或沉澱或結晶出屬於她的獨特舞步。\n直至融蝕現象重創肉身，蔓延至心智，侵蝕理性。\n即便如此，她離真理的中心還是太遠。\n於是，那顆生命之火已然黯淡，求知之光依舊奪目的明星留下了如此遺言：「在世界遺忘我之前，喚醒我。」"
  },
  AwakerStory_11189_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11190_Content = {
    Text = "主教閣下每次拜訪學校，都會受到師生們熱烈的歡迎。\n心智尚幼的喚醒體們會拉著他的手，要求他再講幾個洪積前的故事。學生們會主動靠近，詢問主教是否願意傾聽自己的困擾與煩惱。就連那些看上去冷硬強大的喚醒體，和見多識廣的教授們，也會在主教空閒下來時上前搭話：或是訴說自己的噩夢，或是探討靈魂的真諦。\n他總是如此耐心，總是不厭其煩。不論是誰都能在他那裡得到接納與溫暖。\n「當然，我的孩子，有什麼是我能為你做的嗎？」"
  },
  AwakerStory_11190_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11192_Content = {
    Text = "她對待所有人、所有喚醒體都十分友好，從未顯示出攻擊性傾向。\n大多數時候，她只會安靜地待在房間裡，眺望著窗外。我們在她的床頭，發現了幾本被反覆閱讀過的古典小說，還有數篇寫在便箋紙上的，字跡纖秀的隨筆詩。\n「和那個少女相比，我顯然是幸運的。」她面對著夕陽，對波光粼粼的校園池塘低語。\n她很少參與戶外活動，與其說是不願參與，不如說是不知該如何參與……那少女模樣的喚醒體，似乎缺乏很多生活常識。\n我們還數次目擊到她在與噴水池中的魚類們對話，用一種怪異的、如同吐出氣泡或溺水者嘶啞的低吼般的聲音。但她的面容平靜又祥和，彷彿在與親密的友人相互撫慰、交談。那一刻，我們都相信她已經獲得了真正的安寧。"
  },
  AwakerStory_11192_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11193_Content = {
    Text = "事到如今，再和我談「自己的生活」，或許有些太過為難了。\n我已經習慣了消散在高空之外，隱匿於星海之中。\n那些看客們注視的不是我，被當做音樂盒賞玩的不是我，漂泊於荒蕪星空的不是我。那是為生計出賣歌喉的工具，是為尋找菲茵特而流浪的行屍走肉。唯有相信他人的價值遠高於自我，才能相信這一切付出都屬值得。\n所以，事到如今，請不要讓我再注意到我。\n\n「但是，妹妹啊，別再沉湎於那些已經過去的過去了。\n睜開眼看看吧，你獨一無二的歌聲，可是已經響徹宇宙了哦。」"
  },
  AwakerStory_11193_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11195_Content = {
    Text = "艾爾瓦對她的義肢非常滿意。\n「那場戰鬥後，我就沒想過自己還能站起來。能有機會再度為正義而戰，是我的榮幸。」\n至於午夜時分從宿舍中傳來的低聲呻吟，在新的日輪躍出地平線後，就當作不曾存在吧。"
  },
  AwakerStory_11195_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11195_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11196_Content = {
    Text = "彌利亞姆在校內過著簡樸的苦行生活。獨處，靜思，默禱，清潔，勞作，周而復始，日復一日。\n他人的敬畏與戒備，議論與好奇，她都漠然處之。在遠離故國的校園中，她似乎找到了新的精神修行方式。\n事實上，她並不在意與人交談。只要你願意分出一點時間，聽她講述那位不朽神祇的偉大，講述存在於史前的遙遠文明與賢明幼王統治的永恆國度。每談及此，她的眼神中就會流露出聽者不曾得見的憐憫。\n值得注意的是，彌利亞姆對圖魯抱有著異常的執著與尊敬，儘管圖魯沒有對她表現出任何特殊的態度。\n如果有與彌利亞姆交涉的必要，拜託圖魯幫忙可能會使局面發生有利的轉變。"
  },
  AwakerStory_11196_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11197_Content = {
    Text = "被喚醒後第三個月，調查員們和守密人一起給諾締拉舉辦了一場派對。倒不是慶祝她來到這裡，而是慶祝她終於記得彌薩格大學的名字了。\n雖然她第二天又忘記了，但派對總可以再舉辦一次。誰知道呢，或許再過三個月她就能真正記住了。\n很難說諾締拉那金魚一般的記憶力是融蝕的後遺症，還是銀芯缺損的結果。不過短期記憶也不完全意味著壞事，對一個認真對待工作的機修工而言，忘記擰到哪顆螺絲意味著把所有螺絲再擰一遍，兩遍，三遍……因此，經由諾締拉雙手維修過的器械，往往有著比其他器械更牢固的結構，和更長的使用壽命。\n朵爾因此十分喜愛她，畢竟不是誰都有修一次頂十年的手藝的。"
  },
  AwakerStory_11197_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11198_Content = {
    Text = "朵爾曾經對她進行非常詳細的研究，但無論是軀幹還是四肢，無論是頭顱還是盆腔，都沒有發現任何支持她發聲的部件。她究竟是如何說話的——這成了彌薩格無數未解之謎中的一個。\n在大多數情況下，她能與人進行正常交流，但有的時候，那個神秘的發聲部件就像是具有自己的意識一樣，會說出一些讓人毛骨悚然，渾身發冷的話。"
  },
  AwakerStory_11198_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11198_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11199_Content = {
    Text = "漢娜：你還記得在你解體前發生了什麼嗎？\n艾瑞卡：自動人偶行為開始失控，意識出現斷層，且在斷層期間會將所有的一切全部摧毀一切的一切都將覆滅在電流和火焰之下\n漢娜：艾瑞卡？\n艾瑞卡：……\n漢娜：我不會那麼好運碰到「滴答人效應」了吧……艾瑞卡？\n艾瑞卡：頭部組件恢復運轉，為剛才的不便向你道歉。\n如我剛才所說，自動人偶注意到自身對人類的威脅性逐漸增強，且由於自動人偶當時仍將自己視作人類，因此十分痛苦。\n漢娜：你之前說的保護是指保護人類？\n艾瑞卡：自動人偶期望保護，沒錯。\n漢娜：那你剛才為什麼不告訴我呢？\n艾瑞卡：……\n漢娜：需要我換個問題嗎？\n艾瑞卡：不。現在的我已不受情緒所困，可以回答。\n察覺到自身危險性後，自動人偶嘗試在意識斷片前對軀體造成短路，降低軀體自行造成破壞的可能性。\n保護最終還是失敗，人類朋友死亡。\n自動人偶感到悲傷，後悔，絕望。\n自動人偶爆炸自毀，以確保自身不會造成更多的破壞，隨後銀芯被彌薩格大學回收，製作出了我，艾瑞卡，軀體編號EA307881。\n——摘抄自漢娜·皮斯利題為《0711，滴答人專訪》的錄音"
  },
  AwakerStory_11199_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11200_Content = {
    Text = "海水格外澄澈的漁村，在仲夏夜被裝點成銀河的海岸，洋溢出巡迴篷車的輕快笑聲——那些已經不存在的記憶會時不時閃回，又隨即被拋之腦後。\n只要身邊有同伴不斷湧現，就總能創造新的回憶，況且水母們也在呢——奧瑞塔便是如此認為的。\n畢竟在隨波逐流中繁衍、增殖，以數量堆積對抗強敵，是水母的天性與宿命。"
  },
  AwakerStory_11200_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11201_Content = {
    Text = "「要小心潘狄婭，她的危險性和外表完全不同。她是個惡魔。」\n這是無數調查員的血淚經歷凝結成的肺腑之言。\n潘狄婭總是製造甜蜜的陷阱，誘使其他科研人員或喚醒體與她締結主僕契約，然後肆意蹂躪與玩弄對方的情感與靈魂。\n與潘狄婭的談話無果而終，她堅稱自己只是與新的愛人製造、分享與播撒快樂的種子，那些契約均是出自雙方自願。畢竟，她也請那些奴隸品嘗了甜蜜的果實。\n不過，校內也存在潘狄婭的剋星。當索蕾爾經過潘狄婭的宿舍門口時，無論正在討論怎樣的話題，潘狄婭都會突然沉默收聲。有傳言說，潘狄婭曾在蠱惑索蕾爾時遭到了嚴重打擊，但事實真相如何，至今仍是未解之謎。"
  },
  AwakerStory_11201_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11202_Content = {
    Text = "A. F. 297年@1月@1日03：47分，亞格羅共和國@3州@1@2@1鎮東南方發生不明爆炸。衝擊波在當地引發了3.8級地震，震感明顯，波及到距@1@2@1鎮5公里外的村落。\n事件後@1@2@1鎮與其他區域失去了聯繫，周邊居民則無法回憶起該鎮的所在。基於此，審查會派遣成員前去調查，並於@1@2@1鎮邊緣檢測出融蝕物質。\n將小鎮封鎖後，由彌薩格大學調查員進行了融蝕體清除工作，並於疑似爆炸中心的強融蝕區域回收E-1929號銀芯。\nE-1929較為特殊，其諾斯指數長期處於不規則波動狀態，且會自主發出齒輪運轉一般的滴答聲，唯有在與強融蝕區回收的機械碎片連接時能維持短暫的穩定。基於這一特性，彌薩格大學喚醒體系以機械碎片包裹E-1929，在諾斯指數趨向穩定後迅速進行了喚醒。\n——「E-1929銀芯獲取及喚醒報告摘要」"
  },
  AwakerStory_11202_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11203_Content = {
    Text = "在歷史的怒火燒盡一切前，阿格里帕都是卡普阿最耀眼的明珠。\n她恣意妄為，皮鞭總是狠狠抽向沉默的角鬥士；她不喜被人直視，那會暴露她內心的軟弱。但若要論起調教奴隸，阿格里帕可是專業的，或許你會有興趣參觀她臥室裡二十條款式各異的皮鞭——特意為你準備的。"
  },
  AwakerStory_11203_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11203_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11204_Content = {
    Text = "柔軟的黑髮，飽滿的臉頰，如寶石般明亮的雙眼，紅潤的嘴唇——從小，珈倫就因為天生的美貌而備受優待，長大後，男人們每天送的禮物和鮮花更是能在她家門口堆成一個小山。因此，當王宮的管事宣布要將她帶入王宮，訓練成尊貴的王的侍女時，她並不意外。這難道不是應該的嗎？她天生就該被人豔羨，天生就該與眾不同，天生就該成為眾人的焦點。\n但王宮內最不缺的就是美貌，小城鎮的花朵再令人驚豔，在這裡都顯得尋常而又樸素。外貌再也不能給她換來特殊待遇，甚至連她心心念念的，在百年宴會上進入大殿服侍的機會，也被另一個女孩奪去。\n憑什麼？那個女孩有的東西她珈倫也有，憑什麼就不是她？\n然後她看到對方耳朵上掛著的銀製耳飾，恍然大悟。\n宴會當天，她將女孩溺死在湖中，戴上了那對銀白耳飾。她如願成為了侍女中最耀眼的那個，甚至被恩准在國王身邊服侍。或羨慕或嫉妒的目光讓她無比暢快——沒錯，沒錯，一切就該是這樣，這是她這輩子最幸福的一天。\n隨後，她在吞沒整座王城的綠色濃霧中迎來了自己生命的終結。"
  },
  AwakerStory_11204_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11205_Content = {
    Text = "夢境是記憶的投射，是日常生活的縮影，是人類本身的總集。\n從幼時起，拉蒙娜就時常做著同一個夢。\n置身溫暖而渾濁的水中，她與未知唇齒相依，空洞單調的鼓點在水中蕩起圈圈漣漪。\n夢醒後，心中某處總感覺空空落落，彷彿某個存在被從她的生命中奪走、抹除。\n但為了不讓父親露出擔憂的神情，為了不給本就忙碌的師長再添麻煩，拉蒙娜吞下幾乎跳出喉嚨的疑問，回到日常中去。"
  },
  AwakerStory_11205_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11206_Content = {
    Text = "她來到世間所經歷的一切彷彿都為了讓她痛苦，善良、包容、同情、信任……所有人性柔軟的部分都已從她的心中剔除，粘連著淋漓的血肉丟棄殆盡。\n她的字典中從未有原諒二字，能消解鮮血與仇恨的，唯有他人的鮮血與仇恨。\n以血還血，這是最公平的、無論戰士與奴隸都信奉的法則。\n隱忍千年的火山一夕爆發，一隻手從冥界伸出，爬上了人間的土地。\n那是一個復仇的惡靈，要讓鮮紅的河水流遍人間。"
  },
  AwakerStory_11206_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11207_Content = {
    Text = "「媽媽，媽媽，莉莉打針沒有哭！」\n「莉莉真勇敢！」\n「嗯，莉莉不痛，莉莉想到媽媽會回來陪莉莉，就覺得不痛了！」\n……\n「主人，給我命令。」\n「去手術臺上躺好，十五分鐘後開始手術。藥都按時吃了嗎？」\n「吃了，主人。」\n「切開這裡，不痛吧？」\n「……不痛，主人。」"
  },
  AwakerStory_11207_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11207_UnlockDesc_1 = {
    Text = "通關主線普通第4章「於無聲處」"
  },
  AwakerStory_11208_Content = {
    Text = "奧爾拉身上彷彿有一股奇異的魔力，嚮往著詩與美的師生們總是會不由自主地被她吸引，聚集在她的身側。\n奧爾拉並不喜歡發表自己的詩，但彌薩格的學生們還是想盡辦法看到了她的隻言片語。自她筆尖流淌出的詩句，每每在極短時間內風靡校園。\n晨露初起，有人在鐘樓下輕聲念誦她的詞句；黃昏時分，寧菲亞坐在彌大廣場的長椅上，翻閱她的集冊；夜幕降臨後，學生們彙聚在禮堂中排演她書寫的篇章。\n但即便接到盛情邀請，奧爾拉也很少對這些活動投以目光，更遑論親身參與了。那些言辭哀婉的語調，潸然淚下的場合，經常讓她感到無所適從。\n「我又傳播了新的哀傷嗎？」"
  },
  AwakerStory_11208_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11209_Content = {
    Text = "拉蒙娜首次出現在校園時，掀起了軒然大波。\n在喚醒體遍地走、怪人隨處可見的彌薩格大學，銀髮異瞳並不是什麼值得在意的特徵。使拉蒙娜成為談資的，是她「教授之女」的身份。\n所有人都堵在數學系辦公室前，希望一睹德克斯特大小姐的風采。人實在是太多，教授不得不求助蘿坦小姐，才讓眾人悻悻散去。\n等拉蒙娜長大了一些，教授也終於放心撒手讓她在校園裡亂跑時，那些被蘿坦趕走的學生才又找到了向她搭話的機會。\n「勳爵夫人是怎樣的人？抱歉，這個人物暫時還不存在。我是個孤兒，是父親好心收養了我。」\n為了擺脫糾纏，小小女孩從容地說出實情，在眾人陷入愧疚中時，施施然離開。"
  },
  AwakerStory_11209_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11210_Content = {
    Text = "那是……令人目眩的天光與熱浪，縱情聲色的極樂狂歡。\n歡呼聲如海浪般在耳畔嗡鳴，戰士在競技場上沐浴鮮血榮光。\n少女悻悻回家，她一如既往地揮舞皮鞭，無情抽向面前木訥的角鬥士。\n\n這裡才是她的戰場。\n\n沒有酣暢淋漓的對決，沒有鮮花與掌聲。高大的勇士們是最溫順的馴鹿，她所有的咒罵和怒火就像被吸入幽暗的空洞，連一絲風都不剩下了。"
  },
  AwakerStory_11210_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11211_Content = {
    Text = "與一望即知身量嬌小的姐姐不同，汀克特的畸形體現在其他方面。\n槲寄生也好，寄居蟹也好，汀克特彷彿某種脫離了其他個體就無法生存的精神體。\n在荒星時，她所做的一切都是為了治癒菲茵特的疾病，一切可能維繫姐姐生命的方式她都願意去嘗試，哪怕要付出常人難以忍受的代價。\n貴族們的嘲弄與羞辱她都毫不在意，永遠平靜溫和地與他們進行不平等的交易，甚至祈求他們的憐憫——那憐憫為她換來了逃離荒星的席位，而她在到手的瞬間毫不猶豫地拱手贈予了菲茵特。\n菲茵特卻在最後時刻將汀克特推上了逃離荒星的星流——期望妹妹能夠從此擺脫自己，在新的星球開啟自己的人生。\n然而荒星湮滅後，汀克特又為了尋找菲茵特而踏上了全無自我的漂流旅途，受他人驅使擺佈也不以為意。這樣的汀克特被@2教會發現，又輾轉落入了@3手中。\n汀克特不曾反抗。不如說，汀克特更希望有人來告訴自己怎麼做是最好的——即便那是謊言、是欺騙、是只能暫留片刻的幻夢，也比手足無措地僵立原地要好。\n至少，那說明菲茵特的未來還有希望。"
  },
  AwakerStory_11211_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11214_Content = {
    Text = "漢娜：你是從哪裡知道彌薩格大學能夠幫助你的？要知道，大眾對我們的認知可一直都是「偏僻的普通大學」，是拉蒙娜告訴你的嗎？\n溫柯爾：噢不不，不是，雖然確實是她將我領了進來，但我和拉蒙娜交往並不深。我的種族，@1，擁有跨時空間精神遷移的能力，所以我們知道很多東西……關於彌薩格的知識只是其中之一。\n漢娜：所以你是通過那些「知識」，知道穿過迷霧，直接敲開大門的方法的？\n溫柯爾：我承認，我不知道迷霧的存在。當時我就是一直走，走著走著就到了。說到迷霧，你知道門口那段路有多恐怖嗎？沒有路燈就算了，起霧之後連陽光都變弱了，那麼多黑影……\n漢娜：這也是你不喜歡離開辦公室的理由嗎，黑影恐懼？\n溫柯爾：黑影？不不不，你不明白，除了影子還有那麼多黑色，那麼多地方可能藏著……它。\n漢娜：它？\n溫柯爾：噓！小點聲！你會將它——不，它是沒有智能的，但是為什麼，為什麼就算我到了這裡也@2@3@1\n漢娜：溫柯爾小姐，你還好嗎？\n溫柯爾：@2@3@1……\n漢娜：溫柯爾小姐？\n溫柯爾：夠了，出去！我不想接受採訪了！你的影子錄音機筆記都是黑色的黑色黑色黑色出去出去出去！\n漢娜：溫柯爾小姐——\n——摘抄自漢娜·皮斯利題為《0810，溫柯爾專訪（失敗嘗試1）》的錄音"
  },
  AwakerStory_11214_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11215_Content = {
    Text = "《P-063號歌劇院@2事件》中，我們從焚毀歌劇院的後臺角落中發現了一隻金屬匣子，並回收了該枚銀芯。\n彌薩格大學現存的儀器無法鑒定匣子的材質，朵爾教授在查閱@2文獻後，結合其雕花工藝，分析匣子可能來自一個已於數百年前在爆炸中湮滅的荒星文明。\n該枚銀芯置於匣中時安靜而平常，但被取出時會發出陣陣嗡鳴聲。朵爾懷疑該金屬匣是某種信號遮罩器，能阻攔讓銀芯共振的特殊頻率信號。\n引發共振的銀芯型號也已探知。"
  },
  AwakerStory_11215_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11216_Content = {
    Text = "喚醒體編號：MA-C06\n危險等級：A\n特殊收容措施：MA-C06目前暫被安排在7號喚醒體觀察室內，配備昏暗的燈光。因害怕被@3奪取心智，MA-C06拒絕睡覺，室內只配備了一把椅子。\n由於持續良好的行為及友好態度，MA-C06已被批准允許使用溫室，允許探索校園部分區域，前提是至少有一名調查員陪護。\n——《喚醒體收容檔案·MA-C06》"
  },
  AwakerStory_11216_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11217_Content = {
    Text = "彌薩格使用從死者體內析出的銀芯，煉製成喚醒體。\n雕塑家協會從活人體內催生出銀芯，並煉製成喚醒體。\n這是兩種截然不同的理念，後者雖擁有極高的上限，卻顯然違背了倫理道德，因此成為了屢禁不止的禁忌研究。\n蠟像館事件後，24便被帶回了彌薩格。她長期輾轉校園觀察室及研究室內，出行皆需專人陪護。\n毫無疑問，這是個極度不可控的活人喚醒體。在後續觀察的小半年時間內，24體內又陸續分裂出了許多人格。\n她會忽然多出陌生的朋友、敵人，買了許多奇奇怪怪的東西，甚至在不知道的時候學會了說中文。\n她的人生永遠不缺「驚喜」。\n「24是由一系列孤立的點構成的離散函數。」朵爾評價道，「不要相信她說的每一句話。」"
  },
  AwakerStory_11217_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11218_Content = {
    Text = "「我才不是孤兒，」六歲的詹金說，「我媽媽只是去工作了，工作完了她會來接我的。」\n她不曾動搖，也不敢動搖。這個信念是她每晚從滿是黑色黏液的噩夢中驚醒時的護身咒語，是每當她試圖回憶母親的面孔，卻只能看到一片黑色陰影時的唯一安慰。\n她咬著牙在福利院的大門前站過了一個春夏秋冬。直到福利院解散的那天清晨，她才抹去沒人看得到的淚水，帶著老鼠朋友離開。\n「我是個孤兒，」十歲的詹金說，「我沒有爸媽，我只有布朗。」\n她這麼告訴自己，也告訴自己肩上的老鼠。事實也確實如此，人們或許會提防突然靠近的孩子——東區流浪兒在整個倫蒂尼恩都算得上有名——卻沒人會對竄過腳邊的老鼠抱有太多疑心。默契配合之下，女孩偶爾也能吃一餐飽飯，在下水道裡做上一個關於壁爐和點心的美夢。\n但寒冷的冬日從不憐憫任何人，它給她帶來疾病與高熱，帶來在她身側駐足的死神。女孩奄奄一息，只有老鼠在周圍急切地打轉，期望用叫聲換來一點關注，任何人的關注。\n一個年輕的女人停下腳步，將女孩包裹在溫暖的懷中。\n「我才不是孤兒，」十三歲的詹金說，「我有姐姐梅森，還有好朋友布朗！」\n女孩抱著老鼠站在破舊的房屋前，臉上滿是開朗的笑容。"
  },
  AwakerStory_11218_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11219_Content = {
    Text = "佔據拉蒙娜身體時，「拉蒙娜」不曾行走於校園之中。\n蘿坦的豪放大氣、奧吉爾的靦腆忠誠、威廉的冷靜自持、朵爾的嚴苛認真……沒有人比她更將這些瞬間銘記於心。\n但她始終謹記著：這些美好之物，已經不再屬於她。\n現在的她，需要全神貫注守護另一個命定之人……這也是為了守護另一個岌岌可危的世界，為了守護另一個天真的自己。"
  },
  AwakerStory_11219_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11220_Content = {
    Text = "詹金過於靈巧的雙手，一度讓人擔心她會成為彌薩格大學新晉的《日報》常客——不是作為被採訪對象，而是作為數起盜竊案的主謀。\n雖然她最終還是成為了《彌薩格日報》的常客，但那不是因為習慣難改——只要有足夠的小蛋糕，就算是街頭生存大師也樂意放下過去的手段，和自己的老鼠搭檔一起好好享受難得的退休生活。\n她頻頻上報的原因只有一個：《日報》的好主編給的實在是太多了。\n噓——小點聲，你永遠不知道她在哪個角落，準備用聽到的資訊去和漢娜換取更多的糖果和蛋糕。"
  },
  AwakerStory_11220_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11221_Content = {
    Text = "科學與知識的新星，在一個普通的工人家庭冉冉升起。\n朵爾童年的大多數時間，都充斥著汽缸鼓動和齒輪運轉的聲音。\n但對機械的熱愛，並不足以支撐少女爬上崎嶇嚴峻的科學之山。\n將她引上求知之路的，是一場瘟疫。\n未知的瘋狂肆虐城市，醫院人滿為患，停屍房不堪重負，人人自危。\n「整座城市的墓地都不夠用，把奶奶挖出來和把媽媽燒掉，你總得選一個。」\n於是，朵爾目送母親消失在了火焰中。\n不同於其他被火葬者，那捧曾被她稱為「母親」的碎骨與灰燼中，流動著一團閃耀的銀質。\n「我想知道，我是否還能再見到她。」\n「我想知道，那裡面是否有她善良的靈魂。」\n「我想知道，那銀質是否是生命的本源，是否是靈魂的本質。」\n「我想知道，世間萬物是否存在共同的起點。」\n在得到答案前，朵爾不會向融蝕現象低頭。"
  },
  AwakerStory_11221_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11222_Content = {
    Text = "她縹緲的身影叫人想起振翅欲飛的鷗鳥，白裙被獵獵海風揚起的時候，觀者總能描繪出一幅飛向烏托邦的飛鳥之圖。\n不知道那端坐於桅杆橫木之上的少女，是否也曾想像過自己的遨遊之姿呢？"
  },
  AwakerStory_11222_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11222_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11223_Content = {
    Text = "紅寶石耳環，藍寶石項鍊，用石榴石和孔雀石編織而成的漂亮髮飾……它們是多麼的耀眼，多麼的美麗，多麼的魅力無窮。它們所到之處，人們趨之若鶩。\n這些珠寶掛墜不是什麼「裝飾用品」，不，它們才是世界的主角。佩戴了綠松石項鍊的貴族小姐們被詩人編進曲子傳唱；耳上掛著祖母綠寶石的年邁夫人們也被當做高貴的象徵。就連那些和她一樣出身低賤的女孩，也能憑藉手腕上的一條廉價手鍊，獲得「珍珠女孩」的愛稱，吸引無數人目光。\n哪怕是乾枯的樹枝，腐臭的屍骨，只要掛上一串美麗的珠寶，就能變成所有人追求的對象。\n只要她也能戴上那些項鍊耳環，那些手鍊頭飾，一定也能成為所有人的焦點吧。"
  },
  AwakerStory_11223_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11224_Content = {
    Text = "如簧巧舌是花苞散發的蜜香，王臣是簇擁著搖曳花蕊的蜂蝶。\n欲望澆灌出的荊棘，已於不知覺間將花窗緊緊纏繞。\n即便人格為世人詬病，雙手被冠冕劃得鮮血淋漓，她也不會放棄已被擁入懷中的權力。\n畢竟，這才是薔薇綻放所需的真正養分。"
  },
  AwakerStory_11224_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11224_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11225_Content = {
    Text = "她在那位夫人的關愛與教導下長成了善良而溫柔的樣子，如同一位真正的貴族小姐，然而只因一次對奴隸無心的幫助，她就被「父母」無情地拋棄了。\n斯巴達人從未接受她，而所有同族卻也對她恨之入骨。\n她一瞬成為了所有人眼裡的背叛者，失去了自我存在的位置。\n牢獄之中每個人身上都散發著濃重的惡意，彷彿某種能夠傳染的惡疾，明明他們之間從未相識。\n暗無天日的折磨彷彿永恆，她神經質地恐懼任何人靠近，每天無法入眠，只有偶爾昏迷時能安然閉上雙眼，然而睜眼之後便又墜入無盡的噩夢。\n她究竟做錯了什麼？所有的事是如何走到這一地步的？\n她的怨恨茫然無處安放，無法理清命運的邏輯。\n是因為她有罪嗎？\n但如果她有罪，那麼所有的人的罪便十倍加之。\n那仇恨日積月累變成怨憤，無盡的憤怒日日夜夜燃燒著她的血液，終於有一天燒毀了那困住她的牢籠。\n纏繞她多年的鎖鏈如今纏繞在一個個嘶喊的脖頸上，多年來鎖鏈早已和她的身體融為一體，那實在是趁手極了，她握著沾滿血色的鎖鏈，去追索一個個骯髒的靈魂。\n紅色，紅色，溫熱的紅色，腥臭的紅色。\n看吧，她就知道，沒有一個人的靈魂是潔白的。"
  },
  AwakerStory_11225_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11226_Content = {
    Text = "她什麼都知道。\n她知道鐘樓會在緊急時刻鳴響，知道波江座流星雨會在十年後到來，知道自己體內流淌著不一樣的力量。\n她什麼都不知道。\n她不知道食堂咖哩配方中的秘製香料，不知道如何計算星球湮滅後的半徑，不知道自己的未來會被拉扯向何方。\n她難以割捨身邊的一切，又難以抵抗直覺為她指引的道路。\n在通往真相與真理的旅途中，拉蒙娜需要與堅定之人同行，為她守住回歸日常之路。"
  },
  AwakerStory_11226_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11227_Content = {
    Text = "如果沒有甦醒過來就好了，沉淪於深淵之人，本就不該睜眼直視耀眼的日輪。\n她應該是麻木的實驗素材，是已被這世界埋葬之人，不該擁有疼痛的感知、被愛的渴望。\n母親的留戀不舍製造了她一生的悲劇，而莉莉則仍陷於「是否應當服從於世界安排」的迷茫。\n或許某一天，她會從反抗命運的某人身上得到答案。"
  },
  AwakerStory_11227_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11227_UnlockDesc_1 = {
    Text = "通關主線普通第4章「於無聲處」"
  },
  AwakerStory_11228_Content = {
    Text = "我好像陷入了某種超自然事件，在此記錄我的所有發現……\n我們本來正在對埃夫羅塔斯進行最後的考古收尾，一覺醒來後其他考古隊成員都消失了，而這座城鎮彷彿一夜回溯了千年。\n早已坍塌的古建築拔地而起，還原了這座城鎮真實的樣貌，包括城鎮中化為白骨的無數居民。\n興奮、震驚與恐懼同時攥住了我的大腦，哪怕已經見過無數屍骨，我仍然因眼前的景象不停顫慄，如果任何一個人經歷我現在所經歷的，他只會比我更加驚恐。\n這座城鎮裡的所有人貌似都是被同一個人兇殘地屠殺的，無數白骨橫在街頭、倒在房中。城鎮的大門不知為何牢牢緊閉，門邊擠滿了試圖逃出卻依然被殘忍殺死的屍骨，如同一座白骨壘作的小丘。\n我沒有找到一個例外的死者，男人，女人，老人，小孩……無數的人都被某種巨大的鈍器砸碎身軀或是頭顱，面對著風乾的白骨，我恍惚間甚至能看到滿城流淌著鮮血的樣子。\n這裡到底發生了什麼？\n……\n我茫然地四處搜尋，但沒有任何線索，直到我進入了城鎮的監獄。\n這裡的景象尤為慘烈，兇手懷著巨大的憤怒摧毀了整個監獄，牆壁上有枯褐而扭曲的字跡，像是有人臨死前以血寫下控訴，我仔細辨認，那似乎是惡靈兩個字。\n惡靈？這是指進行屠殺的兇手，還是說這座城鎮真的經歷過某種超自然事件？\n的確，以一個人的力量屠殺全城太過匪夷所思，恐怕只有真正的惡鬼才能殘忍地收割如此多的生命。\n走出監獄後，這座城鎮似乎發生了某種微妙的變化，我的鼻子總能聞到一股若隱若現的血腥味。\n就在我試圖尋找出路時，一陣突兀的鎖鏈聲忽然在城鎮中迴響，彷彿有人在拖拽著什麼沉重的東西前進。\n惡靈！是惡靈……惡靈找上我了！我拼命地跑，可無論跑到哪裡，那恐怖的鎖鏈拖拽聲始終跟隨著我。\n我跑不動了，躲在某個民居的桌子下，我鎖起了房門，但那鎖鏈的聲音仍然追著我。我聽見它來了，它離這裡越來越近……\n我多希望這些不過是我的一場夢，只要醒來一切都會消失，等等……那聲音好像消失了，惡靈或許已經離開了？\n……\n研究人員備註：正常的筆跡到此結束，只剩下最後扭曲的三個字，經過鑒定這三個字大約是：\n門開了\n——節選自埃夫羅塔斯考古團已故考古人員的日記"
  },
  AwakerStory_11228_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11229_Content = {
    Text = "就算在角鬥士們徹底燒毀了訓練場，將她父母的頭顱掛上高牆時，阿格里帕都難以置信——這些卑賤、溫順的奴隸怎麼會有這樣的膽量？\n在羅馬，人被分為兩種：奴役別人的，被別人奴役的。\n阿格里帕是幸運的。她是卡普阿最大的角鬥士訓練場老闆的女兒。她橫行肆虐、不可一世，沒有什麼是她不敢做、不能做的。\n可是現在，她像一隻倉皇的兔子，瑟縮在地下室的角落，外面的狂歡在她看來和地獄無異。\n奴隸起義。多麼陌生的詞彙。阿格里帕只有十五歲，這個世界還有太多她不理解的東西。\n她在陰影中看到一雙泛著紅光的眼睛。那是尤烏哈希，訓練場最大的搖錢樹，因太過危險常年被鎖在地下。\n兩人素來不合，沒人知道他們當晚的交談內容。火焰舔舐的血腥之夜結束後，阿格里帕被發現死在陰暗的地底，身旁空無一人。她不是被奴隸殺死的——有人吸乾了她的鮮血，連一滴都不剩下。\n當然，她的頭顱最後也被砍了下來，就掛在她父母旁邊，一起迎風招展，面朝羅馬的方向。"
  },
  AwakerStory_11229_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11230_Content = {
    Text = "漢娜：在你看來，還是自動人偶時的你和現在的你，有什麼區別嗎？\n艾瑞卡：那時的我保留了「情緒」。\n漢娜：具體是怎麼樣的情緒呢，如果你願意分享的話？\n艾瑞卡：抱歉，我不明白你的問題。\n漢娜：呃，就是，如果你覺得這個問題比較私密，可以不回答。\n艾瑞卡：我無法感知「願意與否」，非常抱歉。\n漢娜：那……請告訴我你當時的情緒？\n艾瑞卡：血肉的我經歷了爆炸而生還：高興、欣喜。\n發現自己的精神轉移並保存至機械人偶上：緊張，興奮。\n發現意識逐漸不受控制，並產生強烈的破壞慾：緊張，恐懼，保護。\n漢娜：保護？\n艾瑞卡：非常抱歉，詳細資訊已丟失。\n漢娜：那麼換個問題，這也是本報讀者都希望知道的，為什麼你現在沒有情感了呢？發生了什麼？\n艾瑞卡：因不明原因無法通過精神鏈接恢復理智，大學採取必要措施，以銀芯輔助器械對所有情感進行壓制，降低攻擊性與危險性，保留智能，保留可用性。\n——節選自《彌薩格日報》，《喚醒體教職工專訪：嘀嗒人》"
  },
  AwakerStory_11230_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11231_Content = {
    Text = "在康沃爾郡南部海岸進行考察的過程中，我發現了一處不存在於任何地圖中的廢棄小村。經過勘察，我們確認了這是一處因融蝕現象爆發而被「抹去存在」的村落。\n在村落中，我們收集到了大量的異常海洋生物樣本，包括：呈現食肉特性的硨磲、具有耐熱能力的冰海天使，其中最違反常理的應為遍布各處的「兩棲水母」。\n在一處已經成為水母巢穴的舊屋中，我們回收到了呈流體態的銀芯，重量約為11.85德拉姆。將這份銀芯帶離現場時，考察隊員遭受了異化水母的襲擊，幸運的是，這些異常的兩棲水母所有腺體都已腐爛，不再具有神經毒性。\n——《A.F.308年第三次生物系田野考察記錄》"
  },
  AwakerStory_11231_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11232_Content = {
    Text = "恐懼光、恐懼視線、恐懼愛、恐懼擁抱。\n渴望光、渴望注視、渴望愛、渴望擁抱。\n如果自己不會給他人帶去傷害就好了，如果自己不會給他人添麻煩就好了，如果自己像提尤格一樣是個聰明的孩子，如果自己像詹金一樣是個勇敢的孩子，如果自己像……\n那麼，就可以不被烈日灼痛，就可以不被他人嫌惡了吧？\n懷著不切實際擔憂的玩偶，自陰影之中，向陽光的交界處膽怯地伸出白皙得幾近透明的小手。"
  },
  AwakerStory_11232_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11233_Content = {
    Text = "她在綠炎的簇擁下起舞，幽幽火光映出了舞者稚嫩而虔誠的臉龐。伴著謝內迴旋的舞步，蒼翠火焰點燃了所有宵小之徒的魂靈，燒卻舞台上所有污穢。"
  },
  AwakerStory_11233_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11233_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11234_Content = {
    Text = "三月\n歡迎來到大西洲巡迴水族館！我是本次的解說員奧瑞塔，登上水母篷車時請小心腳下哦！\n水箱裡展示了來自熱帶海域的珍稀水母，鏘鏘！請看——\n四月\n這、這是怎麼回事……大家去哪裡了……館長！館長！水母們，奧瑞塔的水母們都消失了！\n水族館從來沒有水母展品？可我明明記得……\n五月\n因為展品太少，沒有客人所以無法經營下去……嗚……大家再見……\n如果，如果還能巡迴展出的話，一定要再來找奧瑞塔哦！\n六月\n奧瑞塔好累……生病了嗎……\n呀……是水母們！抱歉，奧瑞塔沒辦法為大家撒矽藻了。\n等奧瑞塔好起來，大家再一起游泳吧……"
  },
  AwakerStory_11234_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11235_Content = {
    Text = "跟隨極樂鳥前行的第三十一天，索納尼爾號駛進一片起霧的海域。\n希萊斯特坐在桅杆的高處，眺望著下方的人們。那裡傳來魯特琴甜美的旋律，與祈禱航行順利的歌聲。\n\n她不知曉這次航行的目的地，也不清楚這趟旅程能夠帶來多少財富與名譽。她不在意祈禱者是否虔誠，亦不在意在海上悄然流傳的，關於她不夠靈驗的惡名。既然她被要求給予航船庇佑，那麼她就將沉默地履行著使命。\n\n當歌聲停止，霧靄散去，出現在水手面前的卻是一片怒濤洶湧的風暴之海。閃電撕開天幕，黑色污雨傾盆而下，激流將脆弱的船身捲起，投入那駭人的深淵之中。\n\n「神已經拋棄我們了！」絕望的親眷們吶喊著，咆哮著，將她關入暗無天日的地牢。\n失職的庇佑者，已經無人深究她為何無法履行使命，而希萊斯特亦只餘下最後一個微小的疑惑。\n\n……那艘船為什麼會沉呢？\n\n曾將她束縛桅杆之上的鐵鏈濺起水花，她向深海墜去……\n如同被折斷雙翼的白鳥。"
  },
  AwakerStory_11235_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11236_Content = {
    Text = "他是名副其實的巨人。強健的肉體，昭示著他那令人畏怖的力量。他使用著一柄無人能夠舉起的巨刃，戰爭與血祭的滋養，令它的表面如同飽塗油脂的皮毛那般光亮。巨刃的獠牙曾斬下過無數敵人、同族的頭顱，亦斬下過他自己的。"
  },
  AwakerStory_11236_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11236_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11237_Content = {
    Text = "倫蒂尼恩聖堂區異常事件報告（機密）\n\nA.F. 315年@2月@3日，倫蒂尼恩聖堂區異常事件中，聖堂區主教薩爾瓦多為救治彌薩格守密人及在場的倫蒂尼恩市民，使用了「賜福」的力量，由此暴露了其喚醒體的身份。\n過程中，由於鏈接者精神力不足，為避免影響鏈接者，薩爾瓦多主教選擇自我消耗以支撐「賜福」，直到守密人與奧吉爾喚醒體將異常現象核心——儀式鏡——擊碎。隨後，守密人接手了薩爾瓦多主教的鏈接，「賜福」治療了在場所有群眾，避免了人員傷亡。\n據查，薩爾瓦多主教的原鏈接者為前聖堂區主教，現倫蒂尼恩大主教@4。\nA.F. 300，大主教在接觸聖灰後意外喚醒薩爾瓦多。隨後5年間，薩爾瓦多以助理神父身份在聖堂區活動，並在■■■■■升遷後接替其成為聖堂區主教。\n事件後，守密人同意為薩爾瓦多主教的喚醒體身份進行保密，因而此資訊並未同步至密斯底亞協定審查會。除了彌薩格大學核心人員，目前無人知道其喚醒體身份。"
  },
  AwakerStory_11237_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11238_Content = {
    Text = "那年11月的下雪天，24生病了。\n經過連續一週的高強度工作，她發了很嚴重的燒，在家裡躺了好幾天。\n朦朧中她似乎聽到小老鼠在耳畔哀哀地叫著。過了不知多久，有人站到了她身邊。\n她認得那雙眼睛——是下水道裡的那個孩子。她滿身泥濘，將手中髒兮兮的藥丸遞給24。\n「給你的，吃吧。」小孩生硬地說道，聲音很好聽——原來她是個女孩子。\n24望著她手肘和臉上的傷口，沒有問這些藥是從哪裡來的。她緊緊握著女孩的手。\n女孩不自在地哼了幾聲，像哄小孩一樣酷酷地說：「我不走。你好了我再走。」\n好了也別走。\n24在心裡回了一句。\n初冬的倫蒂尼恩下了整整一週的雪。雪停的那天24很高興，因為她不僅退了燒，還收穫了一個妹妹。"
  },
  AwakerStory_11238_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11238_UnlockDesc_1 = {
    Text = "通關主線普通第2章「以蠟像之名」"
  },
  AwakerStory_11239_Content = {
    Text = "「犯下罪愆之人啊，這裡是慾壑之淵，地獄之底。黑犬在這裡咆哮，惡臭在這裡瀰散，喪鐘在這裡鳴響。你們因放縱的慾望與殘忍的行徑匯聚於此，等待你們的自然是苦難與死亡。」\n潘狄婭曾供職於新門監獄，那裡是整個倫蒂尼恩最壓抑、最陰森、最不見天日的污穢角落。曾經滿手血腥的重刑犯戴上鐐銬與枷鎖，被剝奪尊嚴，在迷宮般的牢房區域中向她跪地求饒，親吻她的皮靴，謙卑地自稱她的奴僕。\n每當有新的絞刑執行，她就會喚來新的死刑犯，請他們欣賞自己的末路。當被執行者於麻繩中扭動著死去時，她喜歡坐在高處，觀賞窮凶極惡之徒因恐懼與絕望的折磨而瑟瑟發抖。\n但也有「地獄之貓」曾經觀察到，潘狄婭無數次來到新門監獄的鐵門旁，踮著腳尖朝倫蒂尼恩城外張望，彷彿在等待某位來自遠方的訪客。\n「其實我也不過是，永遠離不開這黑暗潮濕的悲慘地牢的，那些囚徒中的一份子罷了。」"
  },
  AwakerStory_11239_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11240_Content = {
    Text = "A.F.3@1年7月3日，應南森尼爾·福布斯·格林基金會的邀請，彌薩格大學參與了針對「幽靈船」索納尼爾號的調查。\n登上這艘於十年前被宣佈沉沒的三桅帆船後，出勤調查員芬戈爾·約翰森隨即失去了通訊信號。\nA.F.3@1年7月10日，學校再次與他取得聯繫時，約翰森調查員已身處300海里外的雷歐高地北岸。約翰森調查員稱，登船後他馬上就失去了時間與空間的概念，並且無論如何都無法想起在索納尼爾號上發生的一切。\n時至今日，約翰森調查員也只能依稀記起一個名詞：永恆樂土。\n基於幽靈船本身的無害性，彌薩格大學於今日（A.F.3@1年12月24日）決定中止調查。\n——《檔案：索納尼爾號船難調查》"
  },
  AwakerStory_11240_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11241_Content = {
    Text = "街頭生活對她來說並非難事。\n餓了就去找工，沒有工，那就憑藉自己的雙手討生活。她與布朗的配合如此默契，以至於不需要他人幫助就可以過上有吃有喝的生活。\n「我們不需要任何人，」她和老鼠搭檔發誓，「我們只需要彼此。」\n但每逢飄雪的夜晚，她仍會忍不住看向那些亮起昏黃燈光的窗戶，看向裡面那些在貧瘠的晚餐旁擁抱彼此，互相祝福的人。\n她確實不需要隱蔽的屋頂，不需要奢侈的高床軟枕，她確實已經擁有值得信賴的夥伴，但她還是好奇，長久地擁有一個家會是怎樣的一種感覺呢？\n這個問題在梅森將她收養之後，獲得了解答。"
  },
  AwakerStory_11241_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11242_Content = {
    Text = "「拉蒙娜」對於現身一事表現得非常剋制。正如她所說的一樣，只有守密人呼喚她時，她才會借拉蒙娜的身體現世。\n她總是來去匆匆，除了戰鬥外，她似乎不想再與我們的世界產生更多交集。\n是恐懼那些糾纏她的夢魘嗎？還是害怕自己貪戀這些她已失去的……我們無從知曉。"
  },
  AwakerStory_11242_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11243_Content = {
    Text = "A. F. 1@2年@1月@1日10：31，警方接到報案，@1@1莊園內發現多處血跡。分局警探貝爾福德立即前往，展開調查，並在血跡中發現成分不明的青綠色黏液。\n13：44，貝爾福德警探遞交報告，密斯底亞協議審查會當即接管了案件。\n14：25，審查會第七回應隊抵達莊園，控制相關人員並封鎖了現場。根據現場情況，隊長推測莊園內存在至少5名受害者，且莊園內出現了多處不同程度的融蝕。\n18：00，彌薩格大學調查員抵達現場，確認融蝕現象存在，攜帶喚醒體進入莊園進行清掃及調查。\n23：11，莊園清掃完畢。調查員在莊園地下室和書房的密室中發現大量神秘學文件及儀式材料，並找到一名不完全喚醒體。喚醒體自稱「女僕珈倫」，是@3公爵的首席侍女。被發現時喚醒體穿著女僕制服，戴著許多風格不同的首飾，在非常賣力地打掃地下室。該喚醒體擁有人類外形，青綠色皮膚，四肢末端呈半透明黏膠狀，疑似不完全或錯誤召喚的產物。其身上分泌的黏液與殘肢上發現的物質在質地和顏色上完全吻合。\n調查員對其進行詢問，女僕珈倫對@1事實供認不諱，並表示一切都是為了獲得主人的關注。在得知@3公爵將被逮捕後，她喃喃地說了一句：「那我的新主人在哪裡呢？」隨後解體為凝膠，留下銀芯。\n01：37，審查會第七回應隊隊長提審相關人員，並依「協議」拘留@1@1莊園主人@3公爵。\n03：09，調查員返回彌薩格大學，並將K-033號銀芯登錄入庫。\n——「@1@1莊園事件記錄」"
  },
  AwakerStory_11243_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11244_Content = {
    Text = "A.F.3@2年，亞格羅共和國沿海城鎮出現融蝕現象。本次融蝕現象以港口為中心呈螺旋狀擴散，波及方圓數百米的地區，造成@1人死亡。\n據調查，融蝕現象最早在港口漁船出現。該船於A.F.3@2年@1月@1@1日出海作業，捕撈到一條擁有銀色螺旋紋路的類鱈魚生物。\n該生物軀體柔軟，被利器切割後整體破裂，流出夾雜了貝殼和其他殘渣的流體物質。漁船抵達港口後，漁獲上已經出現貝殼類增生，但並未引起注意，直到一名漁民將自己視作螺殼，嘗試扭曲身體導致重傷入院，事件才得以上報。\n事後，彌薩格相關人員於@4罐頭廠尋得融蝕源頭，將其清除後取得O-36銀芯。\n——《喚醒體系銀芯獲取報告：O-36》"
  },
  AwakerStory_11244_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11245_Content = {
    Text = "詹金貼在心理諮詢室的門縫前，豎起耳朵偷聽。\n茜爾維婭的聲音溫和而親切，艾繼絲的則如蚊子嚶嚀一般，斷斷續續難以辨析。\n「艾繼絲，你要學會拒絕。」\n「可是我……添麻煩……想……報答……」\n「艾繼絲沒有給任何人添麻煩。你看，守密人允許你在學校裡自由活動，對你不加任何拘束，不就是信任你的表現嗎？」\n「和我約好了，別再隨便答應其他人的無理請求。尤其是卡拉布，你替她關禁閉和掃除，才會給守密人添麻煩哦？」\n「詹金，你怎麼進來了？」\n「詹、詹金！是、是我自己答應卡拉布的！你、你別衝動！」"
  },
  AwakerStory_11245_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11245_UnlockDesc_1 = {
    Text = "通關主線普通第1章「東區秘事」"
  },
  AwakerStory_11246_Content = {
    Text = "溫柯爾有過一個屬於自己的名字。\n那個名字曾浸滿父母的愛意，\n曾被好友反復地書寫，納入回憶，\n和生日一起在日曆上標記。\n\n溫柯爾有過一張屬於自己的面龐。\n那副模樣曾在父母的注視下成長，\n曾在好友的陪伴下露出歡喜，露出悲傷，\n曾和回憶一起定格在照片上。\n\n溫柯爾有過一個屬於自己的家，\n與卡達斯相距甚遠，毫不相像。\n最終同父母的存在一起消亡。\n被黑色的@2吞噬，然後徹底消亡。\n\n溫柯爾有一個深重的恐懼。\n它漆黑、可怖、吞噬一切、不講道理。\n它將所有一切融解侵蝕，消磨殆盡，\n一旦沾染，存在本身都會化作灰燼。\n\n溫柯爾只剩下一個曾經屬於自己的名字。\n人類的軀體無法念誦，甚至無法模仿，\n她只能在極度疲勞的時候閉上眼，\n祈求一個能夠聽到熟悉的呼喚的夢鄉。"
  },
  AwakerStory_11246_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11247_Content = {
    Text = "她誕生於人類史記載之前，已然無處考證的舊日文明。\n在那裡，來自群星的子民建有輝煌的國度與不朽之神的廟宇。她在信仰中長大，從小虔心敬神，立志成為神明使徒。\n然而，神明的感召豈是如此易得，她渴求著奇蹟與靈幻，卻一次也不曾得見。\n直到圖魯即位為王，勤勉如她亦終於升上大祭司之位——那是她永生難忘的一刻，極度的恍惚與喜悅充盈著她的靈魂，令她的精神為之震顫。\n她終於得見奇蹟，她終於領悟真意：這位幼王便是她所渴求的，不朽者在人間的化身。\n數年之後，一場覆滅文明的大洪水降臨。她從圖魯口中聽取了關於不朽的最後一個預言，然後返回神殿祈禱直到最後一刻。\n而後幾度滄海桑田，新的人類重新在陸地上繁衍生息，史前之事再也無人知曉。\n自此，彌利亞姆的試煉才剛剛開始。"
  },
  AwakerStory_11247_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11248_Content = {
    Text = "生存既是本能，也是一個無法拋卻的負擔。在連記憶都無法留存的死亡面前，只有她是他們存在過的證明——她的父母，她的好友，她家鄉的一切。\n所以她逃了，逃向尚未被黑色浸染的世界，逃向這顆覆蓋了海洋的星球，在一個死去的人類少女身上獲得了新生。\n但黑色的死神最不缺乏耐心。\n人類的雙眼無法看見融蝕，但她知道意識邊緣的寒冷意味著什麼，腦海中的黑暗代表著什麼——被人類稱為融蝕的死亡追了上來，在她不知道的時候，將她的精神和軀體釘在了一起。\n她一次又一次地嘗試逃離，一次又一次地失敗，最終她筋疲力盡，精神也被撕扯到極限，只能拖著身體向唯一可能給予她救贖的地方走去。\n不論如何，她都希望能活下去。"
  },
  AwakerStory_11248_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11249_Content = {
    Text = "萊克被他的警探好友稱為「好運偵探」。\n顧名思義，他是個好運的人：只要下注，就能贏回十倍本金；只要靠蒙，就能選對答案。\n好運偵探不是非得當偵探，只是誤打誤撞偵破了多起疑案，就被人簇擁著走上了這條道路。\n他破案不靠推理，靠運氣。只要在案發現場巡視一週，就能撞上犯人；只要走在路上，就會撿到關鍵證據。\n在這樣的好運中，他度過了順風順水的二十五年。\n從來不為昨日煩惱，從來不為明日發愁。"
  },
  AwakerStory_11249_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11249_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11251_Content = {
    Text = "A.F.3@2年4月1日，銀芯儲存與管理室，彌薩格大學喚醒體系，倫蒂尼恩\nG411號銀芯與G410號銀芯一同，由德克斯特勳爵於「水仙夫人」處購得。個體長1.85釐米，最寬處0.4釐米，整體形狀接近斜方六面體。無論從哪個角度和方位觀測，G411都會以觀測者的視覺中心為中心，向周圍擴散出明黃色的菱形波紋。長時間注視會使觀測者精神渙散，情感回饋減弱，甚至導致木頭人綜合徵（可能症狀有：完全的情感缺失、欲望缺失，及因食欲缺失而導致的營養不良乃至死亡等），需要及時進行心理和情感干預。\n儘管其負面效果與大部分銀芯相比較為溫和，但仍建議密封保存，取出後避免直視，以減少因受G411影響而產生情感障礙的可能。\n\n——摘自《彌薩格大學銀芯儲存記錄》"
  },
  AwakerStory_11251_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11252_Content = {
    Text = "她的記憶從進入牢獄的那天起，就已經充滿了血色。\n過往平淡與溫馨的回憶如同虛假的夢境，早已模糊而開裂，化為鋒利的碎片一片片嵌入她的血肉。\n她記不清那曾經溫柔的懷抱、關切的面龐，留在心中的只有永恆的仇恨與質問。\n疼痛，屈辱，背叛……一切痛苦到底因為什麼？\n她日日質問，直到自由來臨之時，始終無人回答。\n那麼就讓她自己來尋找答案，從那些哀嚎尖叫的胸膛中，親自質問一顆顆骯髒的心臟。"
  },
  AwakerStory_11252_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11252_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11253_Content = {
    Text = "本應湮沒於歷史長河的小小靈魂，依託於母親的願望，和@1@2@1設立法陣的充盈靈氣，與沉眠艾爾沃斯冰下的巨型生物結合，復生為少女的怪物「莉莉」。\n由於喚醒的不完全，喚醒初期的莉莉沒有知覺，只是一具服從命令的戰鬥人偶。\n雕塑家協會成員弗朗西斯·奧斯伍德曾以莉莉為素體，進行過長達@2年的非法實驗。從弗朗西斯的日記中可知，那時的莉莉狀態極不穩定，時常失控造成小範圍破壞，導致弗朗西斯不得不頻繁變換住所。\n隨著靈知製劑的攝入和銀芯的種植，莉莉於未經記錄的某日恢復了感知力和部分記憶。後幾經周折，弗朗西斯接手了瀕臨倒閉的拉伊療養院，並將其改造為了試驗場。\n在L-776號拉伊小鎮「地獄犬」事件中，其母弗朗西斯·奧斯伍德被囚於自身打造的異常維度中，失去聯絡。"
  },
  AwakerStory_11253_UnlockDesc = {
    Text = "同調率等級達到10"
  },
  AwakerStory_11253_UnlockDesc_1 = {
    Text = "通關主線普通第4章「於無聲處」"
  },
  AwakerStory_11254_Content = {
    Text = "人類將於本世紀登陸極地的傳言愈演愈烈，在此情況下，彌薩格大學與密斯底亞協定審查會達成合作，組成了聯合調查隊。\n聯合調查隊於A.F.3@1年12月深入艾爾沃斯冰原，目的是在世俗探險隊登陸前，回收可能存在的神秘學產物。\n……\nA.F.3@1年12月10日，約翰森調查員失足落入冰洞，意外發現冰原下存在著一處空洞。海拔太低了，融冰將在三日內淹沒空洞，我們需要在氣溫繼續攀升前完成探索。\nA.F.3@1年12月12日，有理由相信，世界上存在一個長期使用空洞作為祭坑的教團。在空洞底部，我們發現了不計其數的類人生物骨骼。是的，類人生物，其顱骨上連接了部分鰭狀軟骨。\n……\nA.F.3@1年12月13日，該死，該死該死該死！在骨山最上方，調查員發現了近期死亡的人類遺骸！！！\n教團可能尚未退出極地，基於審查會那愚蠢的「堅持」，此行沒有允許喚醒體調查員同行，我們必須趕緊離開！\n——《關於封鎖威爾德海航線的動議書·其一》"
  },
  AwakerStory_11254_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11255_Content = {
    Text = "旺達聰明、富有、漂亮，正如她所說的，她活著便是為了尋歡作樂。她將男人變成她的奴隸，又將月光般冰冷的雙腳踏在奴隸的背上。頭戴桂冠的維納斯，她是邪惡與夢幻的化身，在這一片黑暗陰影中，唯有她修長的身影閃閃發光。"
  },
  AwakerStory_11255_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11255_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11256_Content = {
    Text = "在試圖查詢莉莉·奧斯伍德的記錄時，艾瑞卡發出了81條錯誤警報。身為曾被世界遺忘之人，莉莉的出生檔案、診療記錄都已化為一捧黑色淤泥。\n但我們仍能通過特殊儀器觀測到她的銀芯形狀：纖細蜷曲，形似數縷交纏的髮絲——更準確地說，像是孩童的胎毛。\n特別需要注意的是，莉莉對鏈接者總是表達出特殊的依戀，比起自稱「同伴」、「主人」，以「母親」自居，或許能更快拉近與她的關係吧。"
  },
  AwakerStory_11256_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11257_Content = {
    Text = "拉蒙娜十歲開始，就成為了大學訓練場的常客。敢以人類之身接受黑衣劍士指導的她，成為了諸多調查員欽佩的對象。\n在正式接受預科課程後，憑著過目不忘的本領、滿分的試卷、優雅而致命的劍技，拉蒙娜在彌薩格的地位水漲船高，自律和優秀成了她的代名詞。\n但令很多人不解的是，明明如此優秀，拉蒙娜卻始終沒有獲得獨立執行任務的資格。提前入學的她甚至接受了足足五年預科課程，目送了一批又一批調查員投身神秘學世界。\n她到底在等待什麼呢？到底被賦予了怎樣的使命呢？\n這個問題在新一任守密人入學後，得到了解答。"
  },
  AwakerStory_11257_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11258_Content = {
    Text = "制服要用蒸汽熨燙，被子要用手工清洗，夏天時壁爐必須乾乾淨淨，冬天時則要無時無刻不生著火堆。木地板要光可鑑人，書架要一塵不染，紅茶要永遠保持溫度適宜，方便隨時享用。\n為了她那高貴的、特別的、獨一無二的新主人，那個給予她又一次生命的守密人，她可以做到一切。她可是世界上最好的女僕，當然要能夠完美完成每一項工作，雕琢每一個細節。\n主人的誇讚總是讓她無比高興，但不夠，還不夠。要怎麼做才能獲得主人更多的關注呢？要怎麼做才能讓自己更加引人注目呢？\n「一定是缺少了耳環、項鏈、手鏈、戒指和頭飾！」她將掃把往地上一杵，自言自語道，「只要有閃亮亮的珠寶裝飾，珈倫一定能變得更加可愛，大家也就會更喜歡看著珈倫啦！」"
  },
  AwakerStory_11258_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11259_Content = {
    Text = "A.F.3@2年初，名為西岱的城市在進行翻新時，於一處毀於火災的花園中發現了異狀：灰燼如藤蔓般爬在花房被焚毀的牆面上，藤蔓上綻放的灰燼玫瑰中閃爍著金屬一樣的色澤。\n循著藤蔓的引領，彌薩格大學的調查員拾取了這枚銀芯。在觸碰到那銀色粉末的瞬間，她的指尖被灼傷成焦黑色，沒有任何痛感，兩頰卻莫名滾下了兩行淚珠。\n哀泣來得毫無理由，轉眼間也消散於灰燼中。"
  },
  AwakerStory_11259_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11260_Content = {
    Text = "當登山家抵達艾爾沃斯的尖峰。\n當競技者捧起世界第一的獎盃。\n當虔誠者於睡夢中聆聽得天啟。\n當勝利來得太過輕易，隨之而來的滿足感就會成為平平無奇的慣性。\n舉目四望，竟全無對手，全無樂趣。\n表面上，萊克渴望激情澎湃的博弈，渴望ALL-IN後跳出喉嚨口的心臟，渴望腎上腺素迸發的時刻。\n「不必說那些，了解你的人只有我。你渴望的只是失敗罷了。\n就讓我賞賜你，最甜美的失敗吧。」"
  },
  AwakerStory_11260_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11261_Content = {
    Text = "希洛是一把銳利冰冷的刀。\n與她一同執行過任務的喚醒體都說，希洛是個很好用的武器，她足夠強大，總是能完成任務，只要得到了擊殺指令，不管面對的是多麼強大的敵人，她也必定會突入重圍，取走敵方的頭顱。\n但僅此而已。\n她或許會保護同行之人，但那不過是對指令的遵從，而不是對隊友的關心。她不信任他們，他們自然也無法將自己的後背交給她。\n他們不知道的是，對她而言，朝向己方的鋒刃是卑劣的，是下作的，是應當被懲處唾棄的。\n她深知背叛的可惡，因而絕不會對同伴刀劍相向。"
  },
  AwakerStory_11261_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11262_Content = {
    Text = "不完全喚醒的後遺症，加之變更連結者造成的心理刺激，讓莉莉的性格與心智出現了一定程度的退化，她在大學內的沉默有目共睹。\n除了跟在守密人及喚醒體蘿坦身邊外，莉莉鮮少獨自出現在校園中。她不會出現在教室，也不會加入少年喚醒體們的遊戲。不出戰時，她只是在宿舍中安靜地等待著指令。\n莉莉的房間窗口正對著校園後的鑰塚，夕陽西下時，她會站在窗邊，出神地眺望被昏黃色光線籠罩的鑰塚。\n銀鑰狀的墓碑在低垂夕陽的照射下拉出纖長的投影，佇立在窗前的莉莉和那些墓碑一樣沉默。"
  },
  AwakerStory_11262_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11263_Content = {
    Text = "這是花與詩的城市，在此地，一首繾綣的情詩等價於一束新折的玫瑰，也能交換來三口之家一週的口糧。一篇佳作的橫空出世，也代表著一名天才詩人將聲名鵲起。\n那人曾是個成日與肥料枯枝相伴的花匠，她享受著雅逸詩句為她帶來的奉承與追捧，不再料理園藝事務，甚至將溫室上鎖，不允許任何人再進入花房。\n他人問起，她也只答溫室中藏著「靈感」。\n她們出身微末，是貴族忠僕的孩子。康斯坦聯邦成立，舊貴族被清算，她們也隨之失去了安身之所。\n那是陪伴小姐長大的女侍，卻早早展現了對文字的天賦——可僕役怎能讀詩呢？\n周圍的環境時刻發生著劇變，詩歌的天分尚無法為少女帶來生存的能力。一切的一切都讓少女更加難以適從，更加憂鬱悲傷。\n直到花匠向她伸出了手——那雙被荊棘割破的手，贈予了她一座花園。在這個渺小的王國裡，她們度過了人生最快樂的一段時光。\n平靜的生活，從花匠收到的一首詩開始改變。\n好友的才華是如此動人，她想讓更多人看見這首贈友詩。\n靦腆憂鬱的好友不願署名，花匠便在落款處簽下了自己的姓名——「如果發表了，署名也方便他們寄賞錢。」\n花匠的變化也是從第一筆稿費開始的。\n她不明白，為什麼自己突然就從保護者變成了累贅。\n她不明白，為什麼好友能夠輕鬆收穫所有的愛與讚譽，而自己的辛勞努力，在天賦面前不堪一擊。\n被慾望與妒忌沖昏了頭腦，她開始利用好友的信任騙取她的作品。欺瞞的行為無法回頭，種子從一開始就埋在花匠心中，隨著天才詩人名號的傳播開始發芽，在一次街頭採訪中長出了花苞——狂熱擁躉們用詩句中那些隱秘繾綣的情愫向花匠提問，根本無法讀懂詩文的花匠急得滿頭大汗，倉促離場。深夜回到花房，面對好友關切的神情，恐慌的花朵在此刻盛放。\n一場震驚西岱的大火後，天才詩人宣佈封筆，帶著她短時間內贏來的財富與盛名消失不見。"
  },
  AwakerStory_11263_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11264_Content = {
    Text = "過去三年，蒙格三角海域發生了大量船隻遇險事故，並伴有數起整船失蹤事件。\n一名水手作證稱，在參與事故救援時，他曾於遇險船隻的甲板上目擊到一名「頭部發光的女人」。\n外勤調查員聞訊趕往蒙格三角海域，但船隻一度失去音訊。當增援隊伍找到船隻時，該先遣船已經失去動力，正隨洋流漂向蒙格三角中心。所有船員高度缺水，極度虛弱，並自述產生了強烈的幻覺。\n在對船員進行醫療檢查時，從艾佛斯調查員的隨身物品中發現了銀芯，但調查員本人始終否認船隻與喚醒體發生過接觸。\n該銀芯後被喚醒體系封存，編號6291-S-S-01，計劃於A.F.315年作為預科調查員喚醒教學使用。"
  },
  AwakerStory_11264_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11265_Content = {
    Text = "被喚醒後，我們終於得知墨菲從前在教團過著怎樣的生活。\n撐著一把陽傘，外出前要花大量時間整理自己的儀容。下午茶要在午後四時，配上牛奶紅茶以及草莓果醬司康。保持整潔，優雅，這正是淑女的宿命，她無論身在何處，都堅持過著淑女的生活。\n（檔案員批註：我覺得，她用手直接抓羊脂牛肉布丁的樣子可稱不上淑女……）\n儘管現在已經沒有供她呼來喝去的僕從，她仍按照自己希望的方式生活著，這的確是一件值得欣慰的事。\n受到那個事件的影響，她很少與喚醒體彌利亞姆和戈利亞接觸，甚至會故意視而不見。在與喚醒體圖魯相遇時，她也表露出了十分複雜的神情。\n若是提起過去，她會變得脾氣很壞。也許，她還需要一點時間來平復心情。"
  },
  AwakerStory_11265_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11266_Content = {
    Text = "不必對他的黑色眼罩心存畏懼，交叉的黑暗不會遮蔽他的憐憫。目盲的軀體已然消亡，救贖的意願卻會永存，在他面前，一切都應被愛，一切都將被愛。\n父神的言永刻於石板，借這受祝的骨血，他將予以你們「賜福」。"
  },
  AwakerStory_11266_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11266_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11267_Content = {
    Text = "他總是陰沉著臉，獨自在湖畔遊蕩。漸漸地，學生們把湖畔稱為「陰鬱半魚人的領地」。於是他便像個領主般，每日莊重地前來巡視。當他縱身躍入湖底，翻騰的氣泡溫柔地擁抱著他；在水中，岸上的嘲諷似乎也聽不大清了。"
  },
  AwakerStory_11267_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11267_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11268_Content = {
    Text = "真神最虔誠的信徒，國王最忠實的臣民，用信仰之光照亮朝聖之路。\n永恆之國的傾塌沉沒，於法洛思而言就像城樓失去了地基，藤蔓失去了土壤。對永恆之國的信仰支撐著她在世間浮遊，但久尋不見的哀苦與無盡的孤獨最終壓垮了可憐的旅人。\n法洛思深深潛入她熱愛又憎惡的大海，掀起滔天巨浪，海水翻騰猶如記憶中的祭禮焰火般絢爛，讓她感到了絲絲慰藉。\n在被英雄斬下頭顱時，那如炬目光看向的，應也是她無法割捨的永恆之國吧。"
  },
  AwakerStory_11268_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11269_Content = {
    Text = "她似乎總在圍著那台名為「幻影號」的摩托車打轉：擰一下這裡的螺絲，調整一下那裡的管道……這是一個沒有盡頭的工程，儘管很多人都認為她已經將維修做到了最好，她還是日復一日地埋首其中。\n究其原因，則是那沒有來頭的「還缺點什麼」的感覺。"
  },
  AwakerStory_11269_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11269_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11270_Content = {
    Text = "「4：30 沿著伊希斯河晨跑6英里。中途與路過的老奶奶發生口角，並踹飛一條貴賓犬。\n……\n12：00 享用午餐。蜂蜜煎餅、橄欖開胃菜搭配……五份烤羔羊肉？難以置信。\n13：00 前往鱒魚格鬥俱樂部。戰績：10勝0負，最快記錄3秒鐘——對手因過於害怕而主動棄權。\n19：00 與守密人一同前往科文特劇院觀賞「牧人王」，因高聲發表危險政治言論被掃地出門。\n22：00 被發現徘徊在聖瑪麗安醫院附近，合理推測是想伺機竊取醫院血包。\n以上觀察結束，鑒定危險等級：SSS。」\n——節選自「漢娜的喚醒體觀察筆記」"
  },
  AwakerStory_11270_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11271_Content = {
    Text = "菲茵特看見了躲在實驗室偷偷落淚的學生。\n這不是她最喜歡的，卻是最喜歡她的一個學生。\n女學生從來不介意菲茵特的抗拒和疏離，不害怕菲茵特不受控的能力。\n會用生活費買下所有甜食，只因為擔心她能量不夠；會穿上笨重的防護服，隻為給她梳理睡亂的長髮。\n……要回報她，菲茵特是這麼想的。\n因此，菲茵特做了些力所能及的事。\n——如果只是擔心考試不合格而哭泣的話，那麼威脅其他人放棄成績就好了吧？"
  },
  AwakerStory_11271_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11272_Content = {
    Text = "彌薩格喚醒並收容著許多喚醒體，但沒有人比泰旖絲更獨特。\n她幫助女學生挑選約會的妝容，她幫助失意之人重拾希望，她幫助精神崩潰的調查員走出陰霾。\n像戀人，又像姐妹，更像母親。她總能構建出名為「愛」的泥沼，悄悄使人深陷，叫人不知不覺間變得想要為她付出一切——\n在第三次阻止學生飲下泰旖絲提供的神秘液體後，喚醒體管理處頒布了針對她的限制令。\n「未經守密人陪同，嚴禁泰旖絲靠近所有學生。」"
  },
  AwakerStory_11272_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11273_Content = {
    Text = "所有意義如沙般消散，世界虛假的幕布在她眼中褪去，一切回歸最原始的黑暗。\n在這漆黑舞臺最後的演出上，科學的舞者依然全力起舞。\n她不再在意被融蝕緩慢吞噬，因那劇碼的結尾早在一開始就已經寫好。\n一如往昔，她會將天才的力量毫無保留地奉獻給世界，以最接近真理的方式。\n如果你稍微追問，她會堅稱自己仍保有對人類與世界的愛，她要結束人間一切的痛苦，將人們帶回真正的、最初的家園。"
  },
  AwakerStory_11273_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11274_Content = {
    Text = "A.F.3@1年 @1月。\n亞格羅共和國東部海岸的魔鬼礁，當地漁民報告打撈到「一具形態古怪的屍體」——體型矮小佝僂，眼球突出，皮膚部分硬化，指間長蹼，最怪異的是脖子兩側對稱的紅色印痕。如果不是因為他身上穿著學生制服，也許很難被當作「人類屍體」。\n調查員趕到時，那古怪屍體已被驚懼的漁民當作不祥之物燒毀，只留下一個當時在學生間頗為流行的手提箱。箱子裡沒放任何換洗衣物，只有一些字跡模糊的手稿，一個指南針，以及一張中年婦女的照片。"
  },
  AwakerStory_11274_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11275_Content = {
    Text = "女孩穿著樸素的衣裙，皮膚還因為剛才粗暴的洗刷而隱隱作痛。她不明白自己為什麼會被士兵們帶到這裡來，貴族老爺的家不是奴隸可以隨意進出的地方，而她還遠遠不到來這裡伺候的年紀。\n穿著雪白長袍的夫人端坐在椅子上，女孩低垂著頭，因為畏懼和緊張而不住顫抖。\n「我果然沒看錯……」夫人說，「很像，真的很像。」\n像？是說她像什麼人嗎？\n「很好，太好了。」夫人開心地拍了拍手，「就是你了。從今天開始我就是你媽媽，記住了嗎？」\n媽媽？可是她已經有媽媽了。媽媽在家裡，在她被帶走時大聲地哭。\n她的媽媽怎麼辦？\n疑惑與不解在女孩腦海中縈繞，她想詢問答案，卻也明白，主人的意思就是奴隸的命令，違背命令的奴隸則會被嚴厲懲罰。\n「記住了，夫人。」\n「真是個乖孩子。我想想……就叫你希洛吧，喜歡這個名字嗎，希洛？一定很喜歡吧。來，穿上這個裙子給媽媽看看。」"
  },
  AwakerStory_11275_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11276_Content = {
    Text = "戈利亞專橫、狂妄，但他的強大毋庸置疑。從艾瑞卡小姐的戰鬥記錄中不難看出，那蠻橫的力量足以支撐他獨自突破險境。我認為，之所以戈利亞不在乎搭檔的能力強弱，是因為在他的世界中，沒有人比他更強。\n然而戈利亞在面對彌利亞姆時，總會不自覺流露出些許畏懼。很難想像，究竟是怎樣的存在，才會讓這名強橫的首領、暴虐的舊王產生敬畏之情。\n另外，他對墨菲小姐表現出了不同尋常的關注。有時候，他會在學校迷障周邊徘徊，似乎在等待墨菲完成任務歸來；有時候，他會悄悄地觀察墨菲有沒有在任務中受傷。\n皮斯利小姐也注意到了這件事，她曾半開玩笑地對我說：「嘿，你覺不覺得他在嘗試當一個普通的父親？」\n——《一名實習研究員的觀察記錄》"
  },
  AwakerStory_11276_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11277_Content = {
    Text = "溫柯爾的辦公室被稱為彌薩格大學的北極星。那裡永遠燈火通明，任何可能存在陰影的角落都被各式各樣的照明用具點亮——從提燈到煤油燈，從鎢絲燈泡到蠟燭。\n對黑暗的恐懼甚至讓她排斥睡眠，因此她總會端坐在最大的那盞燈下，在散落滿地的草稿紙上書寫著無人能懂的符號，不分日夜。"
  },
  AwakerStory_11277_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11277_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11278_Content = {
    Text = "凱刻斯討厭人類，當他還是個孩子時，他就討厭他們。\n他曾救起一個落水的小女孩，反而被其他孩子誣賴為害人精；他躲他們躲得遠遠的，又被追著喊「臭臭的蛙人」。\n\n那十數年來的陰鬱日子裡，能讓他有幾分期盼的，唯有奧恩叔叔的來信。他淵博的知識中包含無窮無盡的鬼怪故事，讓小小的凱刻斯癡迷不已。可好景不長，沒過幾年奧恩叔叔竟失蹤了。\n直到16歲那年凱刻斯回到祖父家拜訪，偶然翻到奧恩的手稿。他終於知曉了身體上扭曲紋路中隱含的高貴意義。\n呵，人類，終究是低劣的下等生物罷了。\n從此，他不再悲觀，而是潛心等待，等待命運降臨的那天。"
  },
  AwakerStory_11278_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11279_Content = {
    Text = "少年一度被稱為「死亡騎士」的事，校內已經沒有多少人記得了。\n只在午夜時分，那日的光景會變成惡魘，潛入少年的夢境。\n入侵校園的融蝕體，倒塌的鐘樓，奄奄一息的「守密人」。\n「別哭，奧吉爾，這不是你的錯……」\n入侵家園的鐵騎，傾頹的行宮，從公主指間流下的黑血。\n「別為了我犧牲，奧吉爾，你做的已經夠多了……」\n記憶的砂礫裹挾痛苦，沖刷著少年的魂靈。"
  },
  AwakerStory_11279_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11280_Content = {
    Text = "有的喚醒體會在醒來後表現出對新軀殼、新生活的不適應、而有的則迅速接受了現狀、較為主動地開始了第二次生命。\n圖魯不屬於任何一種、從未有人像他這樣露骨地表現出對當前世界的興致缺缺。\n他的素質極為優秀、也許他對當下世界的形勢與危機也早有洞悉、但他寧願把大把的時間用於睡眠。\n儘管並非出自本人的願望、他在學校的人類與喚醒體之間也頗有名氣。研究員們觀察著他的一舉一動、時不時發上幾篇論文；考古學系、天文學系經常發來各種名目的學術研討邀請、大部分都會指名請他參加。\n圖魯在喚醒體之間也有相當大的影響力：墨菲一看見他就悶悶不樂、戈利亞似乎總想與他暗中較勁、彌利亞姆則將他的每一句話奉為聖旨。\n對於這些、他從未表現出什麼特殊的態度、沒有期待、也沒有要求。\n有時、他會隨心所欲地回應部分請求、有時則不會。"
  },
  AwakerStory_11280_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11281_Content = {
    Text = "直到成為喚醒體的現在，索蕾爾也無法忘記那些對她曲意逢迎的貴族，無法忘記那一張又一張寫滿諂媚的臉。\n那些笑臉是何等令人作嘔啊，油滑、市儈、無處不透露著對她的渴望與算計，她卻不得不為這樣的面容編織溫柔的網。\n她要編織最縝密的網，深入到每個陰暗角落，籠絡每一個人，掌握所有把柄。\n她也必須像逐漸升溫的水，讓那些人沉溺其中，想要摘下假面時才發現已經無法逃離。\n但反應過來時，無法逃離的人卻成為了她。\n不能逃離，不能鬆懈，不能放棄。\n索蕾爾已經沒有了回頭的權利，除了立於所有人之上，她沒有第二條路可走。"
  },
  AwakerStory_11281_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11282_Content = {
    Text = "\n「我要戴上像葡萄酒一樣黑的紫水晶。」\n「我要穿上鴕鳥毛做成的華貴長裙。」\n「我要成為宴會上唯一的光。」\n侍女忽閃著琥珀色的雙眼，她還有好多美好的願望，卻再也無法將它們說出聲。凝固的身軀面前，是一望無際的綠色火焰，在漆黑的夜裡無聲綻放。"
  },
  AwakerStory_11282_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11282_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11283_Content = {
    Text = "她計算著出劍的速度，計算著躲避攻擊的角度。\n她計算著出逃方案的可行性，計算著世界能夠邁向未來的機率。\n直到最後，她都沒有放棄演算。\n正如她從未放棄行走在這條無人之境上。"
  },
  AwakerStory_11283_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11283_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11284_Content = {
    Text = "來自西岱的藝術家並不在意人類，她只追求某種絕對意義上的純粹之美，將轉瞬即逝的刹那銘刻為永恆。\n靈感之泉奔湧而出，刻刀從未停歇。每完成一個作品，珊瑚色的陰霾便蠶食軀體一分，痛苦與喜悅並生，而雕砌者亦不在意自己。"
  },
  AwakerStory_11284_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11284_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11285_Content = {
    Text = "@3修建於第二薩姆尼特時期，以精美的第三龐貝和勒姆瓦希化風格裝飾，這是羅馬時期富裕商人階層的典型住宅。擁有兩個中庭，四個triclinia以及@1@1\n……都在那場著名的奴隸起義中被付之一炬……據同時期的逸聞記載，廢墟的地底封印著巨大的蒼白蜘蛛，當地人稱其為「迷宮之神」，並堅信踏入蜘蛛領地的人類將在無數通道和入口中迷失方向，最終成為其子嗣的宿主。\n有趣的恐怖故事，但不會阻攔我們@2@1\n——節選自《@2廢墟考古札記》\n\n……情況很糟糕，古德曼爵士。莫雷蒂一行人現已失蹤多日，我們都明白這和「迷宮之神」的傳說沒有一點關係，但它確實令人不安。眼下我們決定提早結束考察，返回杜倫。\n另外，考古隊在廢墟裡發現一簇銀色芯狀物，或許和您之前提及的@1有關……\n——節選自克拉克森·約翰遜《致古德曼的一封信》"
  },
  AwakerStory_11285_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11286_Content = {
    Text = "A.F.2@2年11月，貝倫地區發生大地震。\n次日，兩名教授受命動身前往震區，尋找震後失去聯絡的彌薩格調查員小隊。\n該小隊失聯前活躍於陸間海沿岸，主要任務為勘探、發掘歷史遺跡，尋找與「融蝕現象」相關的可能線索。\n11月8日，在據傳最後目擊到小隊成員的地點，@2教授發現了一處未被史料記載的行宮遺址，回收了一把彌薩格制式銀鑰，編號為I-@2，但並未找到小隊成員。\n11月9日，於遺址中出土了兩份銀芯，後帶回倫蒂尼恩，因其歷史價值而被封存，另擇日喚醒。"
  },
  AwakerStory_11286_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11287_Content = {
    Text = "旺達來到彌薩格的第一天，便因「肆意踩踏他人」遭到了嚴厲指控。\n據某不願透露姓名的學生表示，他只是偶然路過圖書館，與旺達不小心有了一次眼神交匯，隨後便被掀翻在地，@2被套上@3（該生拒絕透露更多細節）。\n傷害過程從發生到結束不超過五分鐘，情節惡劣，令人髮指。\n彌薩格紀律委員會（以下簡稱MDC）對該情況表示高度重視與深切同情，現已成立專案小組，後續將持續對旺達進行思想和行為上的徹底改造，以助其盡快融入校園生活。"
  },
  AwakerStory_11287_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11288_Content = {
    Text = "「@1月@1日，大學墓地再次遭到破壞。截至目前，這已是本月發生的第三次惡性掘墓事件。\n協會成員經過長達數周的跟蹤調查，已初步鎖定喚醒體珊為嫌疑人。\n相信參觀過這位雕砌者工作間的人，都會震撼於那些形態各異、詭譎褻瀆的海洋主題雕塑，並對其素材來源產生質疑：我們在這裡發現了可憐的娜塔莎下葬時戴的貝殼珠串，以及與墓碑相同材質的亞伯丁花崗岩。與熱衷闡釋創作理念的皮克曼不同，珊更加捉摸不定——她雖面帶微笑，卻完全無視了我們的質疑。\n不要觸碰她的刻刀，也不要和她單獨待在工作間裡——德克斯特教授曾這樣警告我們，但為了揭開掘墓事件的真相，激進的手段是必要的。\n現在是@1月@1日0點45分，推理愛好者協會成員@2已潛入珊的工作間，祝我好@3」\n——節選自《推理愛好者協會，調查記錄S-618》"
  },
  AwakerStory_11288_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11289_Content = {
    Text = "蘿坦身上貼了太多太多標籤，沒人知道該用怎樣的態度來與這名黑衣劍士相處。\n太過謙卑，她會以無趣之名敲碎你的膝蓋；太過傲慢，她會用巨劍斬斷你的無禮；太過強硬，她會用戰鬥軟化你的靈魂。\n但也許，這正是星球初生之子的傲慢：作為曾經的守護者，她理應享有傲慢的權利。"
  },
  AwakerStory_11289_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11289_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11290_Content = {
    Text = "每當夜幕降臨，諾締拉便會和母親一起鑽進庫房，拿起各種工具，用攢下來的零件拼湊一輛名為幻影號的獨輪摩托。\n「為什麼不直接買一輛呢？」年幼的她抬起頭，向拿著工具的母親提問，「那樣我們立刻就可以出去冒險了。」\n母親握著她的手，一邊教她如何又快又好地焊接金屬，一邊說：\n「機械和人一樣，每個都有不同的脾氣和性格。只有真正理解我們的，才能與我們一起度過更長的時光。」\n「像朋友一樣嗎？」\n「除了機械是我們製造的這點以外——是的，像朋友一樣。」\n巨大的輪轂必須結實，搭載的引擎必須耐用，因為她們一旦出發，就不會輕易回頭。她們要一起走遍世界，一起完成一場盛大的冒險。\n疾病帶走了她的母親，留下了滿是工具，卻又空空蕩蕩的機修鋪。諾締拉抱著未完成的幻影號，下定決心要與這個冰冷的朋友一起完成她和母親的夢想。\n直到最後一次出航。"
  },
  AwakerStory_11290_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11291_Content = {
    Text = "洪積3@2年夏季，伊裡安島上流傳開了海怪的傳說。\n有漁民聲稱，在近海目擊了一隻大約五層樓高的頭足綱動物。它通體深紅，觸手上有著黑色的同心環。\n聽到這則怪物流言時，我正和約翰森前輩在對棉蘭地區發生的疑似融蝕現象進行查證。第二天，前輩就準備好了前往伊裡安島的船隻，我在阿米蘭特洋中央寫下了這篇報告。\n航行第三天，海面上出現了大片魚類浮屍：鯖魚、比目魚、海豚，我發誓在屍群中看見了一頭懷孕的抹香鯨！儘管老水手都說，過量繁殖導致的海水缺氧是魚類死亡的元兇，但我總覺得我們遺漏了些什麼……\n航行第八天，我的暈船現象越來越嚴重，強烈的反胃讓我幾乎無法進食。儘管我們已經接近伊裡安島了，但約翰森強烈要求我們返航@3……我不理解，但我選擇相信這名前輩。\n——貝爾·哥倫布《洪積3@2年夏季實習報告》"
  },
  AwakerStory_11291_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11292_Content = {
    Text = "誕妄·墨菲曾經經歷過一次死亡。\n在並非欣然地踏入名為「神降」的門扉之後，她目睹了「神明」於她的胸膛誕臨。\n多可笑啊，那是一團無意識、無知覺的醜陋團塊，她卻不得不為之付出了鮮活燦爛的人生。\n更諷刺的是，倒錯的命運始終不依不饒。神明降生於世的時刻，她在忍受著劇烈的疼痛中接納了並非心甘情願的犧牲。經歷漫長的、宛若沉睡的時光後，墨菲驚愕地睜開雙眼，發現眼前的景象與臨終前別無二致。\n\n「墨菲」死去，「誕妄·墨菲」甦醒。\n\n她的鏈接者，是一團由她親自誕下的，耳不能聞、口不能言的蠕動血塊。\n神明誕下王女，王女重孕神明，而神明再次喚醒了她的遺骸，病態的命運緊緊糾纏著她，永無天日，不可斷絕。\n她虔誠的母親欣喜若狂，蹈海者伏地祝禱，她的尊榮得以延續，甚至比往日更盛。\n但那個「墨菲」終究是永遠地消失了。曾經憑藉一腔愚蠢的天真，妄圖對不公命運發起叛逆的少女，擁抱著一度厭棄的虛榮冠冕，踏上了永遠無法抵達彼岸的遊輪。"
  },
  AwakerStory_11292_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11293_Content = {
    Text = "我喜歡海。費弗爾的海。普魯士藍色的海。吹來濕潤的暖風的海。從療養院的窗櫺間看過去像油畫一樣的海。載著歸帆的海。像母親一樣孕育著無數生命的海。\n如今，我終於回到了平靜的大海里，回到了未曾誕生之前，回到了被母親的羊水包裹的胎內。洋流拾起那些不幸的碎片，在白骨與珊瑚間拼湊成我。深海的遊魚們穿遊而過，傾聽著那些關於命運苦難的歎息。\n母親啊，如果能夠再一次被誕生於世，我就能變得更幸福一些嗎？"
  },
  AwakerStory_11293_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11294_Content = {
    Text = "埃夫羅塔斯考古團隊受怪病所擾已有十天之久，目前情況仍未好轉。\n怪病來得毫無徵兆，但勢頭兇猛。患者一般會出現嚴重幻覺，伴隨肢體感覺缺失、感官缺失等症狀，並隨著時間發展惡化，最終導致半身乃至全身癱瘓。雖然目前看來，疾病的傳染範圍局限於埃夫羅塔斯河西岸的考古現場，患者也多為考古現場的工作人員及駐場學者，但當局不能排除其向四周擴散的可能性。\n一名曾在考古現場工作過的工人向記者透露，怪病在十五天前已經出現苗頭——正是在埃夫羅塔斯鐐銬出土的那天。有關注相關考古新聞的讀者想必會對這副保存完好、沒有一絲銹蝕痕跡，卻確確實實來自於古早文明的鐐銬有印象。它已在昨日抵達雷歐王國，由彌薩格大學接手後續研究。而怪病與鐐銬之間的聯繫，則更具有神秘主義色彩。\n「自從把它挖出來，營地裡就變得不對勁了。」那位工人向記者指出，「很多人做怪夢，夢到一個被鎖鏈鎖在牢籠裡的女孩，還有人半夜……這就是詛咒，是鐐銬的詛咒！不可能有其他解釋。」\n截至報導日，相關部門已經接管該區域，並嚴禁任何人員進出。埃夫羅塔斯考古行動現已徹底停擺。\n——《古老的詛咒？怪病席捲埃夫羅塔斯考古團隊》"
  },
  AwakerStory_11294_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11295_Content = {
    Text = "喚醒了萊克的銀芯出土於勒姆瓦希知名奇觀三角巨塔的內部，呈流線完美的子彈型，大小與形制和SAA轉輪手槍用子彈一致，嵌在一具青年男性遺骨的顱骨內。\n觸摸這枚銀芯時，眼前會出現精美絕倫卻又宏大瑰麗的三角巨塔的景象，身體不由自主地蜷縮匍匐。假使觸摸者竭力反抗並仰視前方，會見到逆光中面目朦朧的戴冠男人身影，然後瞬間意識中斷，銀芯自然脫手。\n「三角巨塔的尖頂尚未被磨蝕，應當是建成不久後的景象。」——實驗員B·R·朗曼\n「我能聽到來自黑暗靈魂的駭人低語。」——實驗員K·沃特斯\n「我要控訴彌薩格安排我們進行的非人實驗。反復觸摸這枚銀芯帶來的副作用足以令人徹底喪失肉體控制能力。總之，我堅決拒絕再次觸摸它。」——實驗員L·洛佩茲"
  },
  AwakerStory_11295_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11296_Content = {
    Text = "A.F.18@1年@1月，@2步兵團，勒姆瓦希王國，亞歷山大港\n亞歷山大港局勢逐漸平穩，步兵團的第三營、第四營，連同三個連的火槍手已經借道運河，前往@4進行下一步作戰，現僅有第一營及一連火槍手駐守亞歷山大。\n一個小隊在巡邏時遭遇了反叛軍，已迅速解決。他們帶回來了一個有趣的小玩意，看上去像一塊銀子，卻比銀子更加沉重。我將它收在保險箱裡了，指揮官會喜歡這個禮物的。\n……\n駐紮第13天，不同連隊皆有士兵出現行為異常，具體行動包括但不限於襲擊戰友、襲擊長官、毀壞物資補給、毀壞軍事裝備等。這些人員，連同先前那些作亂的瘋子，都已經在我的親自監管下進行關押。\n他們雙目赤紅，唾沫橫飛，比起士兵，更像是某種可悲的動物。這裡有某種瘋狂正在氾濫，我擔心它會發展成瘟疫。\n……\n駐紮第30天。\n截至今日，共有370名士兵出現了瘋狂行為，其中有331名在表現出嚴重的歇斯底里20天後出現肢體麻木，四肢癱瘓現象。他們的攻擊性依舊很強，已有2名軍醫在試圖診治病患時遭到撕咬。\n瘋病仍在繼續蔓延。我已將情況上報，希望他們盡快採取行動。\n……\n審查會接管亞歷山大駐軍已經10天了，人們仍在陷入瘋狂，我的弟兄們在一個接一個地陷入瘋狂。我不明白，為什麼只有我們受到這該死的瘟疫折磨？為什麼當地人沒事？那些總找我們麻煩的反叛軍沒事？\n我的頭越來越疼了，軍醫們卻無能為力——他們比我都要早地墮入瘋狂之中，已經成為那些癱在地上撕咬的怪物之一了。\n我擔心我也將步入瘋狂。\n那幫傢伙說我們得等彌薩格大學的人來。去他的，我們為了國家出生入死，我們不該被這樣對待。\n……\n我知道了，我終於知道了。那是個怨靈，寄宿在那塊銀子裡，要向所有侵占這片土地的人復仇。那個缺了一條腿的女人要我們走，她要我們都走，將這裡的一切還給原本的主人。是的，是的，就應該是這樣，就應該如此，我們從來不該來這裡，從來不該開始這場戰爭，我@1@3@4@2@1@2@3\n——節選自《@2步兵團第一營代理指揮官日誌》"
  },
  AwakerStory_11296_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11297_Content = {
    Text = "她並非飲血而生，曾幾何時，她也沐浴著曇花般熱烈而短暫的溫情。背叛與牢獄之災澆灌出了反叛的烈焰，復仇的火光燒遍麥西亞，在綿綿恨意的熏染中，她的內心已經不再向任何人敞開……"
  },
  AwakerStory_11297_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11297_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11298_Content = {
    Text = "因該前身為「缸中之腦」的本源喚醒體有過掙脫S355拘束器的歷史，當前已由訶勒特院長執行轉移，安置至新型特殊融蝕限制器中。\n該限制器位於黑池深處，在保證限制器周圍30米半徑不存在任何其他儀器與物品的情況下，由黑池監測小組安排至少每60分鐘一班的巡視監控。\n在監測中發現，該喚醒體始終保持意識清醒，幾乎從未有過睡眠活動。該喚醒體曾試圖對巡視成員講述其之前進行的違規銀芯改造實驗，一位小組成員因與其進行短暫交流而陷入瘋狂。\n目前所有巡視小組由三人構成，嚴禁與該喚醒體產生任何接觸或談話，並在巡視時全程佩戴隔音耳罩。\n……\n該喚醒體的保密限制級別已達到喚醒體收管最高等級，任何知情人員不得向彌薩格內外透露該喚醒體有關消息，如無院長批准並親自護送，禁止任何人前往探視。\n——節選自《彌薩格黑池監測小組報告記錄》"
  },
  AwakerStory_11298_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11299_Content = {
    Text = "祂是實際存在著的。\n祂是神明投下的目光，是神明向宇宙舒展的枝條。\n祂享受歷史的壯闊，渴求著文明的繁榮。\n祂想要跨越枯萎，想要超越死亡。\n她想要低沉的吟誦、沙土與鹹味的風，想要銀色的樹葉和摩蘇爾的月光。\n妖婦、魔女、女巫……世人的眼光不過是身外之物。\n只要哪怕一滴血能夠逃脫黑色侵襲，祂們就能再次將永世擁入懷中。"
  },
  AwakerStory_11299_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11300_Content = {
    Text = "玫瑰的尖刺戳破詩篇的紙頁，留下透明的血痕。酒精的氣味揮散縈繞，無色的火舌四處蔓延。\n在那烈火當中，奧爾拉手捧著最後的詩章，為隱匿於花房的天才詩人的末路寫下無聲註解。"
  },
  AwakerStory_11300_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11300_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11301_Content = {
    Text = "她的少女時期是在軍營中度過的。\n如同所有在軍營中長大的孩子一樣，她對軍團的榮光深信不疑，並將它視作自己的生命。她的世界很簡單：指揮官認可的就是正確的，指揮官禁止的就是錯誤的。\n「揮劍朝向敵人吧，我們將予以這片土地真正的自由；砍向來犯的軍隊吧，不要對他們抱有同情，現在的犧牲，都是為了未來的安定與繁榮。」\n她在這樣的口號下訓練，在這樣的口號下踏上戰場。一次拼死的救援後，她獲得了一條傷腿，和一個戰爭英雄的稱號。從此她戴著勳章退居二線，轉而成為新兵教官，全然不知這條傷腿將會向她揭示怎樣的一個世界。\n殘肢受到羞辱，艾爾瓦憤而退伍。走上街頭的她這才真正發現，指揮官光輝的演講是何等謊言——解放不過是侵略的幌子，異國的人們飽受折磨。\n這不是她的理想國，這不是沒有鮮血和淚水的光輝未來。\n她因此向著曾經的同僚舉起贖罪的刀刃，併發誓為真正的公正而戰。"
  },
  AwakerStory_11301_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11302_Content = {
    Text = "「歡迎來到達芙黛爾的交換商店，我們提供以物易物和收購頭顱的服務，價格絕對公道，童叟無欺。」\n灰霧繚繞中，女人輕輕撣了撣古樸的木質煙斗，晃動的帽檐下，時隱時現的唇梢勾勒出充滿曖昧的笑意。"
  },
  AwakerStory_11302_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11302_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11303_Content = {
    Text = "大家很快接受了一個事實：有詹金的地方就有布朗，有布朗的地方就有詹金。而一旦布朗單獨行動了，別懷疑，那背後一定有詹金的影子。\n「什麼叫我偷的？我可是有不在場證明的！」\n女孩拿著被布朗「取」走的東西如是說。"
  },
  AwakerStory_11303_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11303_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11304_Content = {
    Text = "A.F.180年，在北半球大乾旱的影響下，卡拉蘇河出現斷流。\n當地居民從河床淤泥中挖掘出一具怪物骨架，因卡拉蘇河在當地文化中有「混水」之意，該骨架被命名為「混沌之骨」。\n經海洋生物學者鑒定，這是一具大翅鯨骨架，長約32英尺，通體被一種銀色物質覆蓋。次年，該骨架於伊希斯拍賣會上以1.3億雷歐坊的價格拍出。\n交易行拒絕透露買受人真實身分，但小道消息稱，這具骨架被運往了倫蒂尼恩市郊一所私立大學。"
  },
  AwakerStory_11304_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11305_Content = {
    Text = "目中無人的驕縱只不過是一重虛張聲勢的盔甲。在那精緻的洋裙之下，包裹著一顆無人知曉的叛逆之心。\n身居被神聖敘事虛構的美好牢籠之中，墨菲比任何人都知曉人的偽善，神的偽善：教眾看著她的眼神，不過是畏懼和憐憫，「養育者」對她的關愛，不過是對祭品的照料。使命的終點不會是榮耀，而是自己的死亡——她已然知曉結局，又豈會沉溺於教義所描摹的遙遠王國。\n造神的計劃，舊王的復甦，太多不切實際的眾望被寄託於她——卻從未有人關心過，她自己是否願意為了不確定的未來接受必死的命運。\n金絲雀不願永遠困於籠中，於是振翅撲向佈滿荊棘的籬牆。決意賭上性命掙脫命運束縛的她，接下來要自己決定翱翔的方向。\n「我叫墨菲……可別想指揮本小姐！什麼事該做，什麼事不該做，我自己心中有數。」"
  },
  AwakerStory_11305_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11305_UnlockDesc_1 = {
    Text = "通關主線普通第5章「風暴之眼」"
  },
  AwakerStory_11306_Content = {
    Text = "在孤寂之中迎來了滅亡的海洋精靈，於陸地上獲得了奇蹟般的延續。\n無論是生來樂天，還是為了逃避苦痛而選擇遺忘，直率的純真都散發著無窮吸引力，讓人不由自主加入她的陣營——這或許是她擴大「同伴隊伍」的小小計謀也說不定。"
  },
  AwakerStory_11306_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11306_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11307_Content = {
    Text = "作為誕生於混沌中的生命，她是純粹的混沌力量，是不羈的自由靈魂，亦是未被定義的秩序。\n需要挑戰、需要戰鬥，只有難以遏制的破壞欲得到釋放，她才能完成創造者對她的唯一囑託。\n——為了守望星球直至末日，她渴望一場酣暢的戰鬥太久了。"
  },
  AwakerStory_11307_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11308_Content = {
    Text = "我有擁有願望的資格嗎？\n如果有的話，可以讓我成為妹妹的一部分嗎？\n讓她變得完整，讓我們變得完整。\n這樣一來，我能毫無顧忌地表達「愛」，她也能心無旁騖地擁抱「愛」。\n親愛的汀克特呀……這是我身為先出生的孩子，應該為你做的吧。"
  },
  AwakerStory_11308_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11309_Content = {
    Text = "「不留情面的評語」、「低分的試卷」、「不合格的研究報告」\n在朵爾數十年的執教生涯裡，從她手中取得結業證書的學生屈指可數。大多數學生都被其過於嚴苛的態度逼退，轉投其他教授門下。久而久之，朵爾教授的惡名便在學生間流傳開來。\n但也有學生相信，她只是在用這個標準來挑選「門徒」。只有意志最堅毅的人，才配握住打開真理之門的鑰匙，跟隨她一同揭開世界真實的面紗。\n在如此信念的支撐下，即便從朵爾手下畢業的可能性微乎其微，希望被朵爾帶教的申請書仍絡繹不絕地飛入辦公室。\n有時，被臨時叫來審閱申請書的拉蒙娜不禁會想，學生們若是如此相信，也挺不錯的。\n在拉蒙娜看來，她只是在以喚醒體之身的標準來要求人類學生，僅此而已。"
  },
  AwakerStory_11309_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11310_Content = {
    Text = "達芙黛爾在彌薩格大學的行蹤堪稱神出鬼沒，畢竟，她掌握著在維度中自由穿梭的禁忌知識，來去自如，不受地下黑池銀芯樞紐的限制。\n她總是出售一些來路可疑的神秘儀器或材料，有時也會協助其他喚醒體短暫逃離彌薩格大學的控制。\n後來，通過談判，她在校園一隅、醫務室旁的舊房間中開設了自己的「解憂百貨」分店。\n當然，所有售賣的貨品都必須得到彌薩格大學的登記與審查。"
  },
  AwakerStory_11310_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11311_Content = {
    Text = "記錄者：埃里希·馮·維爾納\n時間：19@1年11月7日\n坐標：68°14′S, 67°10′W\n\n由於航向上異常漂浮的大量抹香鯨屍體，我們被迫登陸這片被詛咒的冰原島嶼。在南岸峽灣的冰瀑下方，探險隊發現一具約五十英尺長的頭足類遺骸。其屍身呈深靛藍色，體表密布磷光幽藍的同心圓環，環紋邊緣分泌出薄層黏液。我們取樣提純後，黏液中析出令人不安的大量藍色晶體。\n該遺骸腕足吸盤直徑逾兩英尺，吸盤內壁雕刻著近似不明文字的紋路。主神經索呈半透明凝膠態，在零下三十度環境中仍保持微弱搏動（詳見附圖D-7）。隨行生物學家哈里斯博士試圖採集神經索組織樣本，但在手術刀接觸瞬間，整具屍骸突然粉碎化。肉眼可見的靛藍色塵埃懸浮於整片實驗室內。\n\n歸航途中，哈里斯博士出現持續性譫妄。他反覆在艙室牆壁繪製螺旋與多面體組合的幾何圖形，並嘶吼著「牠們在南極冰蓋下產卵」。第二日清晨，巡查的船員發現他溺斃於壓載水艙，屍檢顯示其肺泡內充斥靛藍色微生物（與章魚屍塵同源）。船長下令焚燒所有接觸過樣本的衣物。\n但願無人再接觸到這潛藏於冰層下的噩夢。\n\n——《南極科考日誌·第37號附錄》"
  },
  AwakerStory_11311_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11312_Content = {
    Text = "我們怎麼會忘記英雄尤烏哈希？他曾是最傑出的男兒。戰士跪倒在日落黃沙裡，溫熱的鮮血將他全身澆灌。禿鷲盤旋高空，為他唱起輓歌：\n無人會用淚水尊敬你，無人會用哭泣埋葬你，只因在生前你已名揚羅馬。"
  },
  AwakerStory_11312_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11312_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11313_Content = {
    Text = "A.F.@2年@1月\n親愛的卡文迪許勳爵：\n\n請原諒，我冒昧請求弗雷管家為我取來了紙筆，強撐著最後一絲理智與體面寫下這封信。自從我身患惡疾，再也沒能見到母親、波比還有您，這份思念足以令我發瘋。\n被關在地下室已經……353天了？我不知道，也許是326天。\n這裡很冷，到處是腐爛的味道。我的傷口流淌著黑色的黏液，又被老鼠啃得不成樣子。但沒關係，痛苦是好的，它讓人保持清醒。\n「邪惡的吸血鬼」、「使家族蒙羞」……將我隔離無疑是明智的決斷。我的靈魂早已被魔鬼控制，寫下這封信的時候，我剛吸乾一位死去流浪漢的血。弗雷管家說，是您命人從街上找來的。雖然味道有些變質，但我還是很高興，原來您是在意我的。\n此外……能否提供一條毛毯？我現在沒有任何能蔽體的衣物，倫蒂尼恩的冬天實在是太冷了。\n直到現在，我也十分懷念，幼時我們一起在韋廷宅邸度假的時光。\n\n您真誠的妹妹\n蕾婭\n——節選自《肯辛頓吸血鬼事件·案卷綜述：證物C-601》"
  },
  AwakerStory_11313_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11314_Content = {
    Text = "A.F.31@1年12月中旬，警方接到了@2花園第二劇場管理者的報案。報案人稱，劇場一週內發生了四次小範圍失火，「芭蕾幽靈」的流言在租用劇場的舞團成員中甚囂塵上。\n為了保證芭蕾舞劇《天鵝挽歌》首次公演的順利舉行，警方與西區消防局展開了聯合調查。\n公演前日，彌薩格大學最終接管了調查。調查員們注意到，多處起火點背後都有靈知殘留的痕跡。最終，@3調查員在第二劇場地下廢墟中發現了一名喚醒體。\n該喚醒體並非無理智個體，她自稱「莉茲」。經過溝通，喚醒體莉茲最終承認了自己的縱火罪行。《天鵝挽歌》首場公演結束後，@3調查員將喚醒體莉茲帶回彌薩格大學，進行了正式收編。\n\n根據歷史記錄，A.F.29@1年@2花園第二劇場大火燃起時，劇場正在上演芭蕾舞劇。當日喪生火海的，除了台下一眾勳貴外，還有一位名為「伊麗莎白·薩勒」的年輕芭蕾首席。"
  },
  AwakerStory_11314_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11315_Content = {
    Text = "一步，再一步地，我緩緩向水中走去。療養院的護士小姐從未允許我走到過這樣遙遠的地方。但願一個很快就會無力支付療養費用的病人的脫逃，不至於令她受到太多責備。\n夕陽的餘暉映照在海上。浪潮迎面而來，輕柔地托起我的裙擺。海水的溫度，溫暖得像是母親的擁抱。\n身體從未像此刻這般輕盈，我的胸腔裡有一座枯竭的火山，如今那裡只剩下海風拂過。\n「回家吧。」\n我聽見大海用我父母的聲音，呼喚著我。他們為了籌錢給我治病，去了海的另一邊。如果我沒有生就這樣一副不幸的身體，他們也不必這樣勞苦了吧。假如我能在一個月夜，悄無聲息地消失在大海裡……我曾經無數次這樣想，但是想到父母傷心的面容，只能作罷。\n可是有一天，一個月夜，父母乘坐的船隻悄無聲息地消失在了大海裡。\n「回家吧。」\n我用盡全身力氣加快了腳步。大海總是平靜地接納所有苦難的靈魂，而對我來說，父母所在的地方就是永遠的容身之所。\n當四面八方的黑夜降臨時，我平生第一次能夠自由地呼吸了。"
  },
  AwakerStory_11315_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11316_Content = {
    Text = "超人的智慧給身體帶來了過大的負擔，他每日要昏睡十五小時以上，清醒時也總是困倦不已。\n在睡夢之中，他有時能感受到諸神的憤懣；有時能夢到交錯的時空；有時甚至能步入深處，直面神明……\n他從未向神明祈求過啟示與預言，然而不管怎樣逃避，預言總會應驗。\n他從未要求任何供奉，被崇拜、被敬畏都是他人擅自為之，他對一切全無興趣。\n重生也不過是打擾了他的一場萬古長夢。\n不必呼告，不必祈求。"
  },
  AwakerStory_11316_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11317_Content = {
    Text = "……\n實驗日期：A.F.@1年@2月\n實驗目的：觀察記錄融蝕患者嫁接組織器官後產生的變異反應\n實驗步驟：@3@4\n選取實驗體死去的哥哥進行嫁接實驗，以觀察直系親屬間的排異反應。這個可憐蟲在躲避員警抓捕時被數槍打死@3實驗很成功，傷口變紅並增生出觸手……血液宛若紅寶石一般噴湧而出。\n@3@3\n實驗者展現出驚人的忍耐力，她拒絕注射嗎啡。\n實驗後渴血欲增強，性情……難以形容，總之不是我擅長應付的類型。\n——節選自赫伯特《融蝕實驗記錄·第四組@1號》"
  },
  AwakerStory_11317_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11318_Content = {
    Text = "不要靠近、不要觸碰、不要直視、不要憐惜，世間或許本就存在只適宜獨居於黑暗之中的生靈。\n縱然這並非她的本意，但若你因她孱弱的身形、怯懦的語調、稚氣的服飾，而愛憐地直視她的雙眼，便會墮入永恆的凝固與寂靜之中。"
  },
  AwakerStory_11318_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11318_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11319_Content = {
    Text = "加入舞團的第四十五天，我作為首席演員站在了舞台上。\n熾熱的光線打在裙邊，細碎的鑽石折射出眩人的美。那光芒讓我無法自如視物，但從雷動的掌聲中，我知道我的表現比寶石更為奪目。\n在不停地回旋中，世上所有塵埃都將被純淨的舞蹈蕩滌，向全世界送去舞蹈之美、藝術之美，這是我身為舞者的願望和使命——\n\n但是，那些藏在舞台下陰暗角落裡的人們，是怎麼回事？\n\n莉賽特，那個行事灑脫磊落的女孩，她怎會與那位臭名昭著的老爺竊竊私語？\n安傑利卡，那個總是睥睨其他舞者的天才，她為何會對那名花名在外的公子提起裙擺？\n\n如此不堪……如此的污濁！神明啊，我的繆斯，請告訴我，我要怎麼做，才能從黑暗中守護我的舞台，要何等的光明才能驅散這污穢——"
  },
  AwakerStory_11319_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11320_Content = {
    Text = "從幼年時起，卡茜亞就展現出了極高的模仿天賦。\n無論多麼精妙的舞蹈，只要讓她看一遍就能重複出來；無論多麼複雜的魔術，只要教一次她就能熟練掌握。聲音、表情、甚至是笑容和氣質，卡茜亞都能做到完美復刻，甚至以假亂真。如果她有一個不同的出身，或者不同的職業，或許能憑藉這個天賦獲得一個不一樣的人生。\n可惜，她只是一個在名不見經傳的馬戲團中長大的孩子。馬戲團的人只想著用她的天賦斂財，而馬戲團外的人——他們只管購買快樂，並不想付出同情。\n沒有人關心卡茜亞的快樂，幸運的是，卡茜亞也並不在乎。每當她看著歡笑的觀眾，看著爭吵的團員，看著對照片默默流淚哭泣的女占卜師，都只感到一種剝離的好奇：他們為什麼要在舞臺下做出這些表情？為什麼要在沒有人看到的時候堅持表演？為什麼要說那是他們「情感的流露」？\n什麼是快樂？什麼是悲傷？割開她喉管的「資助人」所說的，瀕臨死亡的絕望和恐懼，又是什麼感覺？\n作為人類的她找不到問題的答案，但作為魔法的孩子，作為可以從他人身上收集「情感」的生物的她，或許終於可以獲得從未擁有過的體驗。\n於是，她創辦了魔法嘉年華，並將它帶往世界各地。\n人們前來購買快樂，付出的代價卻是所有的欲望。\n「來吧，來吧，來到我的嘉年華！只需要交出一點快樂，一點哀傷，就能看到本世紀最精彩的表演！」"
  },
  AwakerStory_11320_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11321_Content = {
    Text = "最初，只是一杯替代了紅酒的葡萄蘇打水而已。\n在無人注意的角落，索蕾爾做出楚楚可憐的模樣，與兩三學生共飲。\n然後，是一場小小的下午茶。\n在學生食堂，索蕾爾對學生推來的馬卡龍多加推辭，流露出幾分不舍與真心。\n最後，是一場瑰麗沙龍的舉辦，是一朵薔薇的盛開。\n休息室被花朵與珠寶裝點，豔麗的薔薇與稚嫩的學生推杯換盞，賓主盡歡。\n新任守密人目睹了這一切，並暗自祈禱她的下一步千萬不要是「成為彌薩格大學校長」。"
  },
  AwakerStory_11321_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11322_Content = {
    Text = "灰色黏稠的原質之海中一片空無，那些穿越維度的旅行者講述的概念也停留在抽象的描述與想像。\n它想要用自己的雙眼去確認那些人類的「神往之處」，想要親眼目睹人間斑斕的壯闊奇景，想要親身體會悲歡離合的個中滋味。\n但在那之上，它更想要一個特定的人，足以珍視、足以交付信賴的人。\n公正的交易意味著平等，意味著切割，意味著錢貨兩訖，意味著不多付出一分也不少攫取半分。但它渴望不一樣的事物，渴望一種無償的信賴，以消弭隔閡，以突破試探，以融解堅冰。\n它得而復失，但終將失而復得。"
  },
  AwakerStory_11322_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11323_Content = {
    Text = "無數個難眠夜晚裡，身患融蝕的雕砌者傾聽著海浪聲，陷入迷亂的夢境：\n當她的親族帶著戰火降臨，她砌起螺湮雄偉的高牆。\n當天父和眾眷陷入沉睡，她將史詩雕成不朽的聖像。\n她的知覺鈍化，軀體僵硬，幾乎快要握不住刻刀。\n珊瑚般的白色陰霾已蔓延到小臂，她凝視著顫抖的雙手，倏然一笑。生命之火終會熄滅，而身軀將化為永恆。\n她如願被沉入海底。珊瑚破碎，黑色的融蝕漿絲絲縷縷匯入海洋——她終於見到了那座遺失久遠的螺湮古城，並與之徹底融為一體。"
  },
  AwakerStory_11323_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11324_Content = {
    Text = "「一味行淫，隨情縱慾，當受永火的刑罰，作為鑑戒……」\n連續23天，修士都站在她的城門外，嘴裡誦念著乏味的經文。\n旺達命人將他綁了進來。\n修士說：「何必為困苦憂慮。主的靈在哪裡，哪裡就得以自由。」\n她脫掉他的衣服。\n修士說：「何必為衣裳憂慮。野地裡的百合花既不紡線，也不低頭。」\n她砍斷他的四肢。\n修士說：「何必為流血憂慮。凡有血肉者，無一不死。」\n旺達笑了：「吾不但要讓你流血，吾還要將你變成吾的奴，生生世世。」\n「為何？」修士抬起頭，「你不應當憐憫你的同伴，像我憐憫你麼。」\n旺達端詳著修士。他的眼睛很藍，像是晴空的顏色。\n她挖掉他的眼睛。\n因不堪忍受酷刑，修士最終死去了。當地教區忌憚她的財權，竟無人敢指責她。\n臨死前修士說：「@2近了，你應當……」\n許多年過去，旺達早已忘了修士的臉和姓名，只記得他的眼。即將被@2吞噬的那個夜晚，旺達又想到了那句未完的話。\n「@2近了，你應當……」\n她在模糊的意識中揣測修士的後文，卻一無所獲。"
  },
  AwakerStory_11324_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11325_Content = {
    Text = "「你是肩負著光榮使命的存在，是祂重現於世的希望。」\n「做個好孩子，聽話……待祂再度醒來，所有人都能夠生活在不朽的永恆國度。」\n連出生也無法公開於世的隱秘之女，因某些理由成為了蹈海主祭的珍寶。無人在意的可憐嬰孩搖身一變，成為了命運與神秘文明相連的聖女。\n那位苦行聖母親手將她撫養長大，供奉與崇拜從小便圍繞在她身邊，只要是她想要的東西，總會有人雙手奉上。\n如果融蝕現象不曾出現，「神明」的容器不曾衰弱，那她未來只會接過主祭的衣缽，按部就班地立於教徒之上。\n然而，她所獲得的一切，都在某日向她索取了沉重的代價——她從未希冀過的命運，早已為她安排了無法反抗的結局。\n成為神祇之母，誕下預言之子——所謂聖女光榮的犧牲，不過是要她欣然地獻出肉身與性命。\n第二顆心臟在她胸膛裡開始跳動的那日，她的靈魂就成了奔騰的洪流，註定要消失在時間中。"
  },
  AwakerStory_11325_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11325_UnlockDesc_1 = {
    Text = "通關主線普通第5章「風暴之眼」"
  },
  AwakerStory_11326_Content = {
    Text = "洪積282年6月，根據密斯底亞協定審查會遞交的調查申請，我們派出一支調查隊前往了新雷歐地區。\n自一年前隕石墜落事件後，該地區的異常死亡率就居高不下。\n此外，調查員還在墜落現場發現了數種變異植物。經儀器測定，這些植物含有疑似由隕石帶來的高量輻射。\n然而在隕石坑內並不存在任何地外礦物。村民證言，在隕石墜落的第三天，一批白袍科學家就切割並帶走了隕石。\n（備註：疑似民間科學組織，身份存疑。）\n經審查會與當地政府協調，居民已全部搬離，此地被官方宣布為生活禁區。\n據彌薩格大學物理實驗室測算，該地區的生活禁令需要維持至少80年。"
  },
  AwakerStory_11326_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11327_Content = {
    Text = "在挑選對手這件事上，蘿坦自有一套標準。\n學院派戰士大多讀書讀壞了腦子，想的全是紙上把式，令人厭煩。\n軍隊中的佼佼者又往往受繁文縟節、道德禮教束縛，倍感無趣。\n只有那些天賜才華、戰鬥本能與生俱來的奇才，才能得她青眼。\n與星球同壽的巨獸按捺著戰鬥的慾望，近乎虔誠地等待著認定的對手成長至巔峰——那是多麼具有天資的一個少年啊。他號令來自深海的力量，強悍的靈甚至能與界外神明連接，假以時日，他一定能成長為令人垂涎的強者。\n但，許是漫長的時間折損了她的判斷力，這一次，混沌之靈看走了眼。諸多種種，蘿坦不願再向任何人提起。\n我們只知道，從那以後，她對任何「不求上進」、「不思進取」之人嗤之以鼻。"
  },
  AwakerStory_11327_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11328_Content = {
    Text = "銀芯編號：B-005\n出土時間：A.F.1@1年@3月\n出土地點：弗蘭德低地鄉間，某不知名古羅馬陵墓廢墟\n詳情記述：銀芯持有者名為路德維希·普林，因一起招魂事件被當地宗教裁判所判處火刑。普林聲稱在第九次神聖東征的戰場上獲得此銀芯，隨後前往布拉班特附近，與「來自外星的僕人」、「隱形的夥伴」一起，為召喚「偉大的不可名狀者」舉辦血腥祭祀。\n記錄人：華德·菲利普斯\n——《喚醒體銀芯獲取報告：B-005》"
  },
  AwakerStory_11328_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11329_Content = {
    Text = "在孤獨中，一個人要像一支隊伍。24的腦袋有些擁擠——她們在黑暗中私語、竊笑，不斷撕扯24的內心，渴望將她吞吃入腹。自街角下水道散發的惡臭、工區漫天紛飛的棉絮、過期的黑麵包……過往早已逝去，無人記得東區的平凡女工，她終於褪去疲憊的肉身，卻踏入新的泥潭。"
  },
  AwakerStory_11329_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11329_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11330_Content = {
    Text = "這對姐妹中，有一人是不該出生的存在。\n在無法被觀測的天琴座荒星上，菲茵特與汀克特在惡言中度過了半生。\n但究竟誰是那個不被承認的存在呢？\n姐姐菲茵特強大卻無法自控，所掠取的生命力總像河流般逝去，只能靠舔舐殘留的露珠勉強度日。\n妹妹汀克特美麗卻難於自立，如浮萍般倔強卻無處扎根的生命，只得圍繞著姐姐迴旋。\n也許，她們彼此都認為自己是不該存在的那人，只是菲茵特更早做出了決斷——以自我了斷做威脅，她將妹妹強行推上了離開的旅程。\n「離開吧，汀克特。不要讓我絆住你。」\n「你要在星間歌唱，成為最受矚目的色彩。」"
  },
  AwakerStory_11330_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11331_Content = {
    Text = "大多數時間都靜靜佔據著角落一隅的空間，如同真正的燈塔，在迷航時會出言將大家拉回正軌、給予指引。\n只有在與其他深海來客同處一室時，燈火才能照出她瘋狂與偏執的影子。\n安靜知性的外表之下，法洛思出人意料地對遠洋航行頗具心得。儘管誘拐、獻祭海員的嫌疑尚未洗脫，目前仍處於守密人的監管狀態下，但法洛思還是幫助校方修訂了不少航海相關資料。\n——根據校方合作船舶的水手反饋，法洛思的修訂意見雖然有效，但經常會有意無意將航向引往蒙格三角海域。\n校方在獲悉此事後，禁止了法洛思接觸一切海洋相關資料。"
  },
  AwakerStory_11331_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11332_Content = {
    Text = "卡里古拉的御用煉金術師馬庫斯·安提斯以大量活人為代價，煉就的「魔像」。\n由於煉成儀式的不完善，每日須飲下大量人血。為卡里古拉殺死政敵，並助其加冕為羅馬皇帝。\n暴君卡里古拉即位不到四年便被謀殺。他也被憤怒而恐懼的暴民鎖在其被搗毀祭壇的地下，不得不忍受飢渴近千年。\n漫長歲月中，他靠吸食老鼠的鮮血苟活，承襲自血脈深處的飢渴令他發瘋。\n不夠，遠遠不夠……\n@2時期，一位黎凡特巫師找到了他，許諾助其脫困，前提是在戰場上殺死勒姆瓦希人。\n還有這等好事？\n他輕鬆完成了任務，不過，有個小小的插曲：因太過興奮，他一不小心殺死了戰場上所有的人，並喝乾了他們的血——包括巫師和他自己的。"
  },
  AwakerStory_11332_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11333_Content = {
    Text = "喚醒材料G752a號銀芯，出土於倫蒂尼恩新門監獄遺址的腐臭淤泥堆中。@2調查員在髒暗的牢房走道中不慎踩到破碎的頭骨滑倒，因而湊巧發現了它。\n喚醒結果偏離預期，黑色融蝕漿中湧現的並非什麼兇惡的死刑犯，或壯碩的劊子手，而是一名身材嬌小、笑容狡黠的少女。"
  },
  AwakerStory_11333_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11334_Content = {
    Text = "@2這個名字被多次書寫在歷史中。\n祭司、母親、王妃、女王、女巫……這個名字被冠上了太多不同頭銜，以至於史學家至今都難以確認，到底哪個身分才能代表我們如今所認識的喚醒體。\n泰旖絲本人並不吝於與我們分享她的過去——那全都是她，又不完全是她。\n「出身高貴是她。」\n泰旖絲永遠是神殿中最閃耀的女孩，身為大祭司的孩子，她像天鵝般優雅，如月光般溫潤。\n「於樹前跪拜是她。」\n泰旖絲是「樹」上最為鮮亮的葉片，虔誠讓她受到了「樹」的恩惠。\n「被抽走全身血液的是她。」\n災難降臨，大廈傾頹之時，古老而愚昧的文明選擇了最優秀的她。\n「脈管中流淌著樹汁的是她。」\n被萬民敬仰之「樹」，擁有自己的選擇。枝條扎根於體內，給予了信徒幾乎永恆的壽命。\n「但，想要覆滅文明的不是她。」\n泰旖絲想要的，從來都不是世界的滅亡。\n「可泰旖絲小姐，您想要的是什麼呢？」\n「誒呀——不是說好了嗎？當我們之間結出果實時，你就知道答案了。」"
  },
  AwakerStory_11334_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11335_Content = {
    Text = "艾爾瓦不是沒有懷疑過自己的正義，但那恍惚的日夜帶給她的是透徹的覺悟。\n虛幻之物是切實存在的。\n最初的起點從來未曾變改，她為之奮戰的正義，不是某個化為侵略者的組織，不是某個高喊口號的個人，而是堂堂正正地存在於自己的信念之中。\n\n所有的生命，所有的純真，所有的夢想、抱負、美好的嚮往，在炮火面前都能輕易地化作灰燼。\n在戰爭中失去的，永遠不會再回來，它如同地獄惡鬼，蠶食一切美好。\n因此，那些為一己私慾挑起戰爭之人，也必須品嘗灰飛煙滅的滋味。會有真正的英雄，胸懷大義，無私地為所有人的光明未來而戰。\n這就是所謂正義的價值。\n……\n\n錯了，那就糾正。\n要讓那些犧牲值得，要讓這截斷的雙腿與殘肢的幻痛值得。\n若有不幸摧毀的，就再用這嶄新的義肢討回來。\n那些渺小脆弱的東西，永遠也不會失去它們的光芒。\n一切都是為了那真正沒有鮮血，沒有淚水的烏托邦。"
  },
  AwakerStory_11335_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11336_Content = {
    Text = "必須留心，她那冷靜、知性的話語具有著令人失神的魅力。不要好奇異形的頭顱之下是否有另一副容貌，只需了解她對於這副類人的身體抱有長久的不滿。\n她的燈火曾誘引著飛蛾，也曾將迷途者置於死地，而如今那其中似乎正透露出迷途者的茫然。"
  },
  AwakerStory_11336_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11336_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11337_Content = {
    Text = "席捲世界的洪水帶走了文明的積澱，卻也沖刷了歷史的塵埃。\n災難過後，人們從摩蘇爾舊址遺跡中窺見了幾絲被遺忘的歷史。\n「樹」矗立在兩河交匯之處，流下鮮紅的樹液，順水而下澆灌文明。\n「樹」永世不滅，萬古長青。\n古代史學界最後認定，「樹」並不存在實體，祂是一種對古代文明的隱喻，是一種精神象徵。\n在無人得見的角落，種子在世界的每一處扎根。"
  },
  AwakerStory_11337_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11338_Content = {
    Text = "「主人啊，鞭笞我吧。」\n她理應乾涸的眼中燃燒著欲念之火，融化的蠟油如淚滴般滑落。\n饑渴、痛苦、詛咒、污穢，她所索求的一切折辱、她所施予的一切享樂，終於在此刻降臨於自身。"
  },
  AwakerStory_11338_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11339_Content = {
    Text = "她是群星間的歌者，是熠熠生輝的星塵。\n她是金絲籠中的困鳥，是被隨意丟棄的留聲機。\n當荒星在坍塌的宇宙湮滅，她被迫獲得生之希望，成為了無主深空中，眷戀故土的流浪者、永恆歌唱的尋覓者。\n「姐姐……雖然我們中，我才是能自由行走的那一個，但一直以來，都是你在支持我啊。」"
  },
  AwakerStory_11339_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11339_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11340_Content = {
    Text = "這團意志投射出的身體，停留在過早夭折的少女模樣。腐敗的衣襬，蒼白的肌膚，彌漫著往世陰翳的雙眸，無言地訴說著某種被病痛與苦難纏繞的過去。"
  },
  AwakerStory_11340_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11340_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11341_Content = {
    Text = "自@2事件後，凱刻斯與我們握手言和，成為了喚醒體系的編外人員，他了解的@1知識僅有一鱗半爪，卻極樂意展示和分享。\n他在圖魯、彌利亞姆、戈利亞等人面前充滿謙卑，卻對其他種族——尤其是人類——投以陰鬱不善的目光。閱讀過檔案的研究員們理解他的偏執，然而部分脾氣暴躁的喚醒體卻不能容忍。這種劍拔弩張的氛圍通常都需要由茜爾維婭出面開解和消弭，凱刻斯與茜爾維婭間也逐漸建立了信任關係。\n在茜爾維婭的開導下，凱刻斯又覺醒了「高等種族的包容心」，對他人的挑釁迴避不言。\n「那孩子經常會充滿溫情地回憶他的人類母親。都說母親是孩子認知世界的標杆，本質上他對人類的敵意是後天形成的。所以，只是缺乏一些引導和關心而已啦。」茜爾維婭在心理輔導記錄中寫道。"
  },
  AwakerStory_11341_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11342_Content = {
    Text = "喚醒體資料管理人幾度將她的檔案轉入學生管理處，但又屢次被她親手送回，埋沒書山卷海之下。\n「放這裡就可以了，終究有一天要送過來的。」\n她的語氣一如既往平靜，眼神卻閃爍不定。\n\n這平靜之下，藏著怎樣磅礴的情緒呢？"
  },
  AwakerStory_11342_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11342_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11343_Content = {
    Text = "「如果你是第一次執行調查任務，那麼就去找小奧吉爾同行吧！」\n面對新人調查員的不安情緒，有經驗的前輩們總會給出這樣的建議。奧吉爾在師生間受歡迎的程度，由此可見一斑。\n雖然他老古董似的性子偶爾也會鬧出些小插曲，但相互扶持，互為支撐，奧吉爾總能與調查員達成最和諧的節奏。近些年，讓奧吉爾陪同新人調查員執行第一次任務，更是成為了校內所有人的共識。諸如「奧吉爾會為女調查員準備披風」、「奧吉爾看見大腿會臉紅」的笑談，也在學生間流傳開來。\n「死亡騎士」的稱號也逐漸被人遺忘，被信任與溫暖淹沒，只餘一根微小的棘刺紮在少年心中。"
  },
  AwakerStory_11343_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11344_Content = {
    Text = "十二年前的一個清晨，倫蒂尼恩東區。濟貧院門口出現一個被圍巾重重包裹的女嬰。這在人人自危的東區本不算稀罕事，但讓年少的莎拉感到憤怒的是，寒冬料峭，殘忍的遺棄者將女嬰口鼻也裹在了圍巾之下，加之這名女嬰不哭也不鬧，若非那雙澄澈明淨的眼睛在拍擊下眨巴了幾下，莎拉幾乎以為她已經死了。\n正當莎拉以為自己要成為又一個乖孩子的「姐姐」時，時任院長將這孩子以一雷歐坊的價格，送給了東區市場的裁縫。\n「我們養不起那孩子，成為裁縫家的女兒，她雖然會吃點苦頭，但至少能學一門手藝。」\n出生不過兩個月的孩子，談什麼「手藝」呢？\n莎拉感受著空蕩蕩的胃，沒有反駁院長的決定。"
  },
  AwakerStory_11344_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11345_Content = {
    Text = "A.F.2@1年，西岱藝術沙龍展。\n「我要帶她回家！」襲擊者一面用錘擊打著雕塑家奧古斯特的絕筆《無名珊瑚之女》，一面高聲叫喊。他很快被圍觀的群眾制止，人們驚訝地發現，這位神情恍惚的老者正是隱退已久的奧古斯特本人。\n一時間，有關《無名珊瑚之女》的揣測與議論紛至沓來。\n人們說，它的原型正是奧古斯特手下一位叫珊的女徒弟，奧古斯特最優秀的作品都出自珊之手，他是可恥的剽竊者。\n人們說，珊出身顯赫，父親是著名的作家，還有一位外交官弟弟。她為了學習雕塑，不惜與家裡斷絕關係，只身前往巴黎，至死都過著貧困潦倒的生活。\n人們說，珊患上了一種怪病，她的身上流淌著黑色的黏液，每雕刻一分，身體的一部分就會變成珊瑚，《無名珊瑚之女》其實是她珊瑚化的模樣，根本不是什麼雕塑作品。\n人們還說……\n師徒，知己，瘋病。當人潮散去，展廳只剩被言語雕砌的珊瑚之女。她沐浴在月光下，眨了眨眼，等待著，等待著——回家的那一刻。"
  },
  AwakerStory_11345_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11346_Content = {
    Text = "在那場可怕的瘟疫來臨之際，旺達下令將城堡的大門用鐵焊死，過上了徹底與世隔絕、尋歡作樂的生活。\n這裡有插科打諢的小丑，也有即席吟誦的詩人。有演奏的樂師，也有美食和酒漿。\n所有的歡樂與平安都在城堡內，城堡外則是被@2的黑暗世界。\n就在牆外徹底成為一片死地之時，旺達為她的數百名追隨者舉行了一場異常豪華的假面舞會。\n這是一次持續了三天三夜、靡麗而放蕩的狂歡。當第三天午夜的鐘聲敲響，賓客們有的徹底發瘋，有的化為一灘黑色的黏液。旺達的臉如陶瓷般開裂，從面具的縫隙中流淌出黑色的@2。\n受到驚嚇的追隨者依偎在旺達身邊瑟瑟發抖，她卻很平靜。\n她一揮長鞭，命令@2徹底瘋掉的人，餘下人繼續飲酒奏樂，不得停歇。\n光怪陸離的舞會在第四天清晨結束，華麗的大廳內滿是黑色的@2漿與紅色的鮮血。\n沒人知道這裡曾發生過什麼。"
  },
  AwakerStory_11346_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11347_Content = {
    Text = "據《石之災厄事件記錄Ⅲ》記載，守密人自倫蒂尼恩濟貧院帶回這枚銀芯。和銀芯一同帶回的還有一隻小小的、遍佈補丁的布熊玩偶。\n這枚銀芯重約2.1克，纖細光潔，形似淚滴。與銀芯產生直接接觸的實驗員會陷入凝滯狀態，保持觸碰銀芯的姿勢，直至被其他人喚醒。為防止誤觸，研究員朵爾將該枚銀芯保存於封閉玻璃圓球內，替換了布熊玩偶的眼睛。\n「它看上去，好像每天都在落淚。」"
  },
  AwakerStory_11347_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11347_UnlockDesc_1 = {
    Text = "通關主線普通第1章「東區秘事」"
  },
  AwakerStory_11348_Content = {
    Text = "鐵銹味在空氣中蔓延。\n那是……「食物」的味道。\n少女緩緩睜開眼。長期被注射大劑量鎮靜劑，她的大腦一片混沌。面前躺著一隻被咬斷了喉頸的比格犬，似乎叫……斑比？波比？\n少女剛陷入回憶，腹部又傳來劇痛——她被「食物」襲擊了。此刻，被綁來的流浪漢正顫抖著雙手，似乎在高聲呐喊。\n「吸血鬼！怪物……怪物！！」\n然而，少女置若罔聞，只出神地撫摸著腹部的鮮血。\n大量溫熱的鮮血，像是滑膩的綢緞，歡快地溢出傷口，蔓延一地。\n原來，她還會痛、還會流血。\n少女無聲落淚。她伸出沾滿鮮血的細弱雙手，輕撫上「獵物」的面頰。\n「接下來，能請你再用力一些嗎？」"
  },
  AwakerStory_11348_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11349_Content = {
    Text = "被從萬千孩童中選出、被推上王座時、圖魯還不及那青金石御座高。\n但無人敢對他的漫不經心與久睡不醒置喙——所有人都知道、這是王正在聆聽神諭的證明。\n賢明幼王所做的決斷、必然會解決難題；所說出的預言、必然會應驗。\n圖魯也就接受了這樣的生活：進入「神明」的夢中、與那無法被理解的存在相見、以神諭治理國家、再度陷入沉睡……\n這個文明的運轉、是由神明意志所決定的。順勢而下、應運而為、自己只要當好這獨一無二的「傳話人」便足矣。\n然而、圖魯也有唯一未能說出口的預言：國家將因洪水而覆滅、文明終將葬身海底。\n正因通曉一切、才更知毀滅無可改變——但至少在最後的時間裡、不要讓他們生活在恐懼與徬徨中。\n這是他身為國王、而非「神明代行者」所作出的決斷。"
  },
  AwakerStory_11349_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11350_Content = {
    Text = "被喚醒後，誕妄·墨菲就經常做一個關於逃亡的夢，在那場夢的最後，她手握「母親」的匕首，在皎白的月光下貫穿了自己的胸膛。隨後夢戛然而止，睜開眼的瞬間，恰好對上了床前那尊象牙雕像。\n\n誕妄·墨菲在彌薩格內的行動仿若她的「養育者」的年輕版本，她終日身著縞素，不輕易與人談笑，只有話題偶然流轉到對甜食的喜好時，那無瑕的聖母面具會暴露出一條裂痕。\n（檔案員批註：希望下次她想要品鑑小蛋糕的時候，可以當場提出，而不是在所有人的下午茶時間結束後，留一張字條要求送到她的房間裡。）\n\n她習慣於與任何來自蹈海者的喚醒體保持距離。與另一個世界的自己不同的是，她從不刻意迴避與相關者的接觸，只是那凍結在臉上的冰冷表情與暗含敵意的諷刺，不知不覺中就驅離了那些不想碰硬釘子的傢伙們。"
  },
  AwakerStory_11350_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11351_Content = {
    Text = "二十五歲那年，萊克在偵破一起密室殺人案時，遇到了一個怪異的嫌疑人。\n在掌握絕對完整的證據鏈後，被銬在警局的嫌疑人離奇失蹤了，手銬卻完好無損。當然，這是當值警察的責任，萊克依然拿到了自己的酬金。\n萊克拿著這筆酬金遠渡重洋，出國度假，然後在一個地攤邊遇到了逃逸的嫌疑人。嫌疑人正在開盤，見到萊克卻依然不慌不忙，只是邀請他加入賭局，並承諾只要萊克贏了，自己就乖乖束手就擒。\n\n萊克一局都沒贏。\n\n他輸掉了自己的煙斗，輸掉了自己的領帶，輸掉了自己的帽子，輸掉了自己的風衣。\n在他渾身赤裸時，嫌疑人將所有衣裝還給了他，並表示這些賭注太小了。萊克毫不猶豫地詢問嫌疑人想要賭什麼，並在對方提出賭一條手臂後慨然應允。\n\n在數次追加賭注後，對方掏出了一把左輪手槍。面對生死輪盤賭，萊克毫不猶豫地拿起手槍，指向自己的太陽穴。\n一聲槍響後，萊克倒下了。嫌疑人喚回了他的死靈，想要嘲弄他的無知。然而，萊克開口的第一句話是：「接下來賭什麼？」\n\n他的狂妄終於引起了惡魔的興趣。真名為「N@2@3」的嫌疑人決定讓這個賭局延續下去。\n\n「N」拿出三頂禮帽，讓他在其中做出能夠讓他恢復軀體的，「最好的選擇」。\n萊克選定了帽子，「N」打開一頂空空如也的禮帽，問他是否需要更換自己的選擇。萊克搖頭。\n\n-你不懂概率？\n-我只是相信自己的運氣。\n\n「N」揭開了第三頂禮帽，裡面同樣空空如也。最後，他揭開了萊克的禮帽，裡面是一團詭異的黑霧。黑霧向萊克襲來，化作詭異的野獸肢體。「N」以化身的軀體取代了他早已押作賭注的身體。\n\n-有著野獸一般嗅覺的人啊，與這化身不是恰好合適嗎？所以，這就是「最好的選擇」！"
  },
  AwakerStory_11351_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11352_Content = {
    Text = "這裡是應許之地，這裡是藝術的理想鄉，這裡是無上的極樂之所——舞蹈理應成為舞者的歸宿，理應維持著永恆的純淨。\n只要我燃燒著，那不堪的便無法玷污我們的聖堂……這是我的使命，我的希望……請允我熊熊燃燒吧，我會為了大家，燒盡那污濁的一切。"
  },
  AwakerStory_11352_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11353_Content = {
    Text = "噓……不用驚慌，那只是潮濕地窖里老鼠腐爛的聲音。從最黑暗的深淵底部，滋生出猩紅的欲望。被囚禁的靈魂渴望鮮血，一如目盲者祈求光明，荒淫者沉迷愛欲。取悅她的方法也很簡單：盡情地責罵她、羞辱她吧。"
  },
  AwakerStory_11353_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11353_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11354_Content = {
    Text = "在此之前、我們所知的人類最古老的文明起源於雙河地、有大量扎實的考古學資料可以證明這一點。\n不過、人類總是無法滿足於已知之物、當面對浩瀚無垠的幽暗海洋時、人們不會停止向著未知的海洋揚帆遠航。\n也許我們不是第一次得到提醒與暗示。神智學家曾提出過這樣的假說：宇宙乃是一個令人敬畏的循環、而今我們的世界與人類本身、只是其中的短暫一環。\n有太多事物無聲湮滅在循環之中、沒留下一絲可供論證的憑據——這還是值得慶幸的、有些力量太過久遠極端、哪怕只是殘存的遺跡、都能夠對我們的時代產生不可估量的影響。\n——例如這一次、「警戒號」船員在南洋海底的意外發現、至少將人類對史前文明的認知拓展到了數萬年前。\n我們由此得知了一個存在國家、君主與特殊信仰的文明、毀滅於一場世界性大洪水中、長久地沉眠於海底。\n若沒有密斯底亞協定審查會在封鎖工作上的協助、人類歷史或許就將被改寫——而如今的世界、還沒有做好面對顛覆的準備。"
  },
  AwakerStory_11354_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11355_Content = {
    Text = "卡茜亞將手伸進帽子，那裡面空無一物。\n卡茜亞將手伸進門扉，那裡面空無一物。\n卡茜亞將手伸進胸膛，那裡面空無一物。\n收集來的喜怒哀樂，驚懼怨怒，人情冷暖，開場前的喧嘩，轉折時的歡呼，精彩時的哨聲，閉幕時的掌聲，散場時的冷落都從這空蕩蕩的胸膛中溜走了，不留一絲存在過的痕跡。\n卡茜亞對著鏡子模仿起觀眾的表情，眼角的褶皺，肌肉的走勢，唇角的弧度，分明與那些人一般無二，可其中感受不到任何真意。\n要是能感知到就好了，要是能超脫模仿就好了，要是能成為他們中的一員就好了……或者，要是有某人能夠留下就好了……\n那樣的話，一定就能填補這胸腔中的「空」吧。"
  },
  AwakerStory_11355_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11356_Content = {
    Text = "行程資訊：獵奇歷史探秘——坎布裡安城堡豪華七日遊\n行程日期：A.F.3@2年6月18日-6月25日\n導遊：湯瑪斯·@2@1\n行程簡述：\n來吧，一同揭開三百年前最令人聞風喪膽的鬧鬼城堡——坎布裡安城堡的神秘面紗吧！\n我們已經厭倦了在老舊書籍和無聲電影裡見到的魅惑女領主與她二十五個隨從的香豔傳說了，它們千篇一律，毫無新意！\n根據彌薩格某不願透露姓名的專家透露，該地區最近又有了新的發現！@2@1長滿了荊刺……\n儘快撥打電話@2@1@1這趟旅途必將令你永生難忘，冷汗直流！\n——節選自《伍斯特旅行團失蹤事件·案卷綜述：證物S-145》"
  },
  AwakerStory_11356_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11357_Content = {
    Text = "作為走在融蝕研究最前線的人，朵爾一直清醒地知道身後那湮滅的腳步正不斷追趕，更何況，在被融蝕這件事上她早已再熟悉不過。 \n在對真相不斷前進而不斷失敗的探尋下，朵爾慢慢意識到目前人類的肉體或許具有天然的盲目性，屬於現實的人無論如何努力也無法看見彼岸的景色。 \n那麼黑色的黏漿在消解身體的同時，是否同樣會將靈魂引向真實的彼岸？ \n她與那些遠古石板上的箴言靜默對坐，任由融蝕侵蝕了腦缸。無論那道路盡頭是什麼，她都已無法回頭。 \n幸運而又不幸，她用自身的存在做賭注，終於換來了進入世界內側的機會，於是一瞬間，真實、虛無和毀滅同時淹沒了她。 \n一次眨眼間，她見證了宇宙的一切，融蝕的本質、世界的真相，她渴求一生之物這裡應有盡有。 \n所有科學的信仰和理性的堅持化為泡影，一直堅定如鐵的精神壁壘陡然崩塌。 \n那個名為朵爾的天才已經消失，現在站在這裡的，僅僅是一具被虛無佔領的生骸。"
  },
  AwakerStory_11357_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11358_Content = {
    Text = "「A.F.3@2年，密大海洋生態小組在南部海域進行物種觀測時，發現一片形態怪異的珊瑚礁……」\n「該樣本性質奇特，不同於地球上任何已知元素。在水中質地偏軟，一到陸地便迅速風乾硬化。據生物系和天文系聯合研究，推測極有可能為某種未知地外物質……」\n\n「A.F.3@1年，喚醒代號Sanga。\n該喚醒體自甦醒後便保持雕刻行為。那些以詭譎的曲面和線條而聞名的藝術風格難以被歸到任何流派。除了給予觀看者精神衝擊外，對融蝕研究幾乎沒有幫助。」"
  },
  AwakerStory_11358_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11359_Content = {
    Text = "他獨自從死亡中倖存，蛻變；他收斂了巨刃的鋒芒，戴上了使徒的假面。\n當神跡降臨時，他本能地產生了敬畏，但他不曾畏懼任何神明，也不曾理解真正的信仰。\n巨人不應居於人下，戰士不會俯首稱臣。\n亙古已古，他的戰爭仍未終結，征服的欲望與恩賜的力量一同，深深地刻入他的血脈。也許有一天他將身死，也許有一天他將統治所有地方。"
  },
  AwakerStory_11359_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11360_Content = {
    Text = "您一定也做過這樣的夢吧？突然繼承了高額的遺產，突然獲得了無上的力量……足以將那些曾經鄙夷和傷害我們的人通通踩在腳下。\n然後，在夢醒來的瞬間，在永無止境的現實面前，陷入更深一層的絕望。\n可是，我的夢是真的，我的命運，降臨了。\n\n知道嗎，你們才是弱者。\n\n肉體的孱弱和靈魂的萎靡支撐不起高貴的血統？不，不會有那種事的，因為奧恩這個姓氏，就是我們@2的榮耀與象徵。獲賜了血脈和姓氏的我，不再是那個任人羞辱的怪胎，而是流淌著高貴血脈的@1者。\n\n所以……請你們……不要再用那樣令人窒息的眼神看著我了……"
  },
  AwakerStory_11360_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11361_Content = {
    Text = "漢娜：艾爾瓦女士，你加入彌薩格大學也快有好一段時間了。你在學生們中非常受歡迎，不少姑娘還往我這裡塞了一堆情書，要不要我念給你聽？\n艾爾瓦：這真的……咳，我是說，謝謝大家？但我不是來，呃，分享我的一天的嗎？\n漢娜：想不到訓練官還有這樣可愛的一面，看來等訪談刊登了之後我得去校外躲一下，免得被嫉妒的姑娘們圍堵啦！那麼回歸正題，你能否和本報讀者分享一下屬於魅力無窮的訓練官的一天呢？\n艾爾瓦：恐怕我得讓你們失望了，我的一天非常普通。每天早晨4點我會起來鍛鍊，讓這條腿適應運動的狀態。\n6點時我會去餐廳，雖然喚醒體之身不需要進食，但我還是……就當這是一種習慣吧。\n8到12點的午前，我會負責指導調查員們的戰鬥技巧，有時候會額外給守密人加訓。下午的訓練時間則會根據課程進行調整，有時候是1點開始，有時候是3點。\n每週我都會找時間去諾締拉那裡一趟，讓她幫忙調試我的義肢。雖然她容易忘記事兒，但活幹得很不錯，每次她檢修完，我的疼痛都會減輕不少。\n漢娜：那你平時會做什麼來娛樂呢？\n艾爾瓦：娛樂啊……這其實對我來說是個還算陌生的概念。但我最近有和奧瑞塔她們一起去海邊戲水，和這些比較單純的孩子待在一起，總能讓我感到非常放鬆。而且游泳對增強身體強度也很有幫助，想當年我還是新兵的時候，我的教官——\n漢娜：好了那麼我們今天的欄目就先到這裡啦！如果想要知道艾爾瓦女士的往事，還請繼續關注下一期《彌薩格日常分享》！\n——摘自《彌薩格日報》特別訪談欄目，《彌薩格日常分享》"
  },
  AwakerStory_11361_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11362_Content = {
    Text = "在一切的真相水落石出之前，沒有人曾懷疑過朵爾會是那一連串聳人聽聞的事件的真兇。\n畢竟她在彌薩格與融蝕戰線中的存在始終如中流砥柱、高塔明燈一般，是所有人心底堅如磐石的依靠。\n當無數人類夜空中的明星被融蝕擊潰消散，這位永不動搖的人類明燈終於也殘忍地熄滅，化作了陰影中與黑暗同源的推手。\n龍捲風、洪災、大地震……效率低下的兇殺顯然不符合天才的規劃，她用那未曾減少一分的智慧將她曾引以為傲的銀芯科技改造為了「推動世界」的致命武器，在彌薩格看不見的地方送去了一份又一份毀滅的大禮。\n最終她被抓捕時，人偶的軀體已經不能被腐蝕的大腦精密控制，那張曾經平靜如水的面孔上充斥著扭曲詭異的表情，彷彿只要與之對視就會墜入瘋狂的深淵。\n所有人不約而同地選擇忽略了她時而模糊的絮語，哪怕那可能真的透露了世界的真相。\n只因她的遭遇已經再一次證明，人類終究是需要意義才能生存下去的生物。"
  },
  AwakerStory_11362_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11363_Content = {
    Text = "達芙黛爾是以高昂的價格，將自己售賣給了彌薩格大學銀芯研究室。\n在那之前，研究室負責人朵爾已經多次對只能由達芙黛爾發起的單向通信表達過高度不滿。\n但只有達芙黛爾和某位已逝的彌薩格大學高層知道，這樣的「單向通信」是通過怎樣危險的交易才得以成立的。"
  },
  AwakerStory_11363_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11364_Content = {
    Text = "高傲、任性、自我中心……許多與她接觸過的人，都會對她的個性留下如此評價。她在以往生活的環境中，似乎一直受到眾星捧月般的照顧，也許正是這些曾經的無微不至養成了她驕縱的性格。\n「喂！你在看什麼東西？不是說過了嗎，叫你三聲之內就必須回應本小姐！」\n——閱讀檔案的時候也得十分注意。"
  },
  AwakerStory_11364_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11364_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11365_Content = {
    Text = "在海港之城的街角有一家很小的交換商店，店主是一個擅長應對神秘事件的「能人」。\n洪水過後不久，彼時還不叫達芙黛爾的達芙黛爾來到了聖佩德羅附近，這座海港城市中便開始出現「頭顱神秘失蹤」的受害者。\n店主經過調查，找到了那時的它，並在盡全力制服它之後，與它做了一個交換。店主許諾，可以在生命結束後取走自己的頭顱，但在此之前，必須作為店主的助手，不可再隨意狩獵。\n於是經歷千年流浪的它，開始與店主一起行動，一起生活。\n它曾在無數頭顱中重溫過那些主人生前的記憶，讀取過歡欣雀躍也體味過憎惡怨懟，但這荒唐的快樂無非是消磨過於長久的生命、掩蓋飄零而生的孤獨而已。\n在與店主的相伴中，它才第一次與人建立真正的友誼：它發現自己需要的並不是無限的頭顱那種虛假的安慰，只有通過真正與人的相處，才能解決長久的孤獨和空虛。\n然而，這段短暫的快樂只持續了不到十年時間，從未停止調查生涯的店主意外離世。\n於是，它斬下了她的頭，繼承了她的外貌和商店，還有她的名字，成為了「達芙黛爾」。\n從那以後，達芙黛爾踏上了帶著小小交換商店巡迴的旅程，她仍會向尋求幫助的人們收取頭顱作為交換，收集頭顱作為嗜好品。\n但她再也沒有隨意獵殺頭顱。\n再也沒有。"
  },
  AwakerStory_11365_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11366_Content = {
    Text = "回巢、返鄉、歸家，隨便用哪個人類詞彙形容她的願望都無所謂。就算以喚醒體的身姿現世，她也無法忘卻魂牽夢繞的國度。\n海底火山的呼吸不再低鳴耳畔，深海幻夢也已經是模糊的圖像，回歸永恆之國的執念卻日漸狂熱。\n小心她一時的溫馴，為了回到王的御座之下，她甘願付出一切。"
  },
  AwakerStory_11366_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11367_Content = {
    Text = "朵爾是彌薩格大學，乃至整個學界都不可或缺的人物。\n在為學校所管理的喚醒體中，朵爾不是諾斯指數最穩定的，也不是戰鬥能力最強的，但她一定是最冷靜、最理智的那一個。\n對一些曾為人類的喚醒體而言，「死而復生」初期通常伴隨著迷惘、恐慌和狂躁等情緒。然而，朵爾似乎並未受到如此「陣痛期」的影響。\n在被喚醒的第二天，她就再度投身實驗室，於一年內編纂出了集外域知識與人類智慧大成的技術手冊。\n目前的朵爾，一半的時間用於革新「銀芯科技」，一半的時間用於「給愚蠢的學生收拾殘局」。\n——順便一提，基於高維存在的影響，朵爾在書寫那本《技術手冊》時使用了某種未知語言，翻譯工作正在朵爾的閒暇時間中有序進行。"
  },
  AwakerStory_11367_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11368_Content = {
    Text = "「神的女兒，同時也是神的孕育者。」\n這是她確認權威的方式，唯有保持萬眾矚目的尊榮，她才能維持岌岌可危的平衡。是偽善又怎樣？是虛妄又如何？誰不是活在「當下」的時刻？\n墨菲懷抱著包裹醜惡聖胎的襁褓，代行神的旨意，吐露出一個接一個的謊言。\n「祂已降臨。」\n「神國必將上浮。」\n「請靜靜等候下一個星辰正位之刻。」\n與其任由偽善的他人虛構出幻象，不如將這座牢籠親手妝點成自己滿意的模樣。只要她所渴望的「母親」、「夥伴」、「僕人」都還陪伴在自己的身旁，無論是貌合神離的卑躬屈膝還是口是心非的故弄玄虛，她都欣然接受，且甘之如飴。\n「我叫墨菲，是誕下神明的王女。關於利莫里亞、關於蹈海者的夙願……你不必打探，我自有安排。」"
  },
  AwakerStory_11368_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11368_UnlockDesc_1 = {
    Text = "通關星辰篇普通第4章「樂園」"
  },
  AwakerStory_11369_Content = {
    Text = "A.F.3@2年4月2日，阿什杜德地區一處廟宇遺跡遭到了破壞。\n作為唯一讀過大學的人，我這個遊客被地區長官邀請參與了對遺跡的建築學評估。哈哈，千萬不能讓他們知道我的「大學」其實並不是那麼一回事。\n3日下午，我進入了廟宇的中心，古代閃族人將這座廟宇作為祭祀場所，這裡曾盛行著某種已失傳的異教信仰。\n然而出現在我面前的，是所有人都不會認錯的一座雕塑。我清楚地知道，那具雕塑上的褶皺，原本該是斜紋亞麻布的紋理。\n雕像雙手折斷、身首分離，下肢被摔碎在門檻上，渾身像被蛞蝓爬過似的沾滿黏液。我注意到了幾道奇特的抓痕，和一個巨型的、有蹼的足印。\n異教信仰也許仍在該地區流傳，但暫無需要展開正式調查的必要性，我會延長在阿什杜德地區的停留時間。\n——芬@1·@2森《非利士五城遺址巡禮》"
  },
  AwakerStory_11369_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11370_Content = {
    Text = "遠離圖書館地下、墓地和蕾婭，一直是學生們的共識。\n蒼白羸弱的少女熱衷激怒他人，隨後愉悅地品嚐對方的怒意，像伊甸園中的蛇妖一般，適時拋出隱秘的誘餌：來傷害我呀……來呀……\n大多數時候，她會收穫白眼、疑惑與咒罵。唯有一次，她終於得償所願——尤烏哈希毫不猶豫將她揍了一頓，甚至取走她一顆牙齒。這是個對旁人毫無探究慾的傢伙，一切在他看來都是理所應當。\n望著戰士瀟灑離去的身影，蕾婭欣慰地笑了，軟綿綿的晨光灑在她身上，又是晴朗的一天。\n她還有好多好多牙齒，都取走吧……誰都好，都取走吧……"
  },
  AwakerStory_11370_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11371_Content = {
    Text = "「……康斯坦聯邦南部的本多斯曾流傳著「賜福主教」的傳說。洪積前，「賜福主教」出身中央教廷，虔誠而且善良，一手建起了當地唯一的孤兒院，並在瘟疫肆虐時收留了大量無處可去的病人及逃難者。\n瘟疫兇狠，人人皆苦，代行者日夜禱告，終於獲得父神恩賜生命石板，以自身血肉為祭在人世間施展神蹟。他讓死的復活，讓重病的康復。然而這位仁慈的代行者被惡魔陷害，最終死於火刑。\n巧合的是，與傳說「賜福主教」活躍的相同時期，在原@2中部的@1（現康斯坦聯邦南部近本多斯地區）存在過一名特殊的「血之異端」。根據《大陸審判所異端審判實錄》記載，這名異端手握刻有惡魔印記的石板，以血肉為祭，會在月亮被遮蔽的夜晚舉辦邪惡儀式供養自身。該名異端於洪積前107年被審判所抓獲，異端幡然醒悟，向唯一的父神虔誠懺悔，並死於火刑。\n同一個年代，同一個區域，同樣使用石板和祭祀施展秘術——不可否認，「賜福主教」與「血之異端」間具有很多共同點。考慮到審判所具有很強的主觀性，極有可能對被其視作異端的人士進行污名化處理，筆者不得不懷疑，傳說中的「賜福主教」可能確有其人，甚至可能正是審判所記載中的「血之異端」……」\n——節選自《我們的神明：康斯坦聯邦南部宗教與民間信仰》\n"
  },
  AwakerStory_11371_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11372_Content = {
    Text = "渴盼著名為「母親」之物，服從「主人」命令的少女。\n世界遺忘了她的名字，於是那在巨型黑色淤泥眼球中，如百合花般綻放的脆弱白色纖影，被後來者倉促命名為「Lily」。"
  },
  AwakerStory_11372_Title = {
    Text = "基礎資料"
  },
  AwakerStory_11372_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_11373_Content = {
    Text = "莉茲是個令人省心的喚醒體，儘管態度遠不能被稱為「熱情」，但她對學校一切事務都表現出了相當的配合。\n唯一令人在意的是，雖然莉茲成日成夜待在舞蹈教室裡，卻沒有任何人見過她真正的舞姿。\n作為一名優秀的芭蕾演員，莉茲的名字曾出現在一些相關報刊上。可惜的是，因為融蝕現象的影響，喚醒體系情報科僅能確定莉茲曾在A.F.29@1年登上過第二劇場的舞臺。\n校報記者漢娜·皮斯利曾提議，在校內召集舞蹈愛好者，用他們對舞蹈的熱愛「敲開喚醒體莉茲的內心」。\n目前，這一提議暫未被喚醒體管理處通過。"
  },
  AwakerStory_11373_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11374_Content = {
    Text = "索蕾爾知道自己是美麗的，在心中，她將這份美麗稱為上天的寵愛。\n只要眼淚汪汪地祈求，人們就會對她降下垂憐；只要稍稍裝作可憐，暗生情愫的玩伴就會無條件偏袒她。\n但，美麗在真正的權力面前一文不值。\n面對想要將她獻給貴族換取前程的父母，索蕾爾的眼淚頭一次嘗到了失敗的滋味。\n有人能幫幫她嗎？有人能帶她逃離愚昧而落後的命運嗎？\n有什麼東西，有什麼地方……能讓這份美麗成為真正的武器嗎？\n在索蕾爾掩面痛哭時，攪動命運深潭的使者降臨在了她的面前。"
  },
  AwakerStory_11374_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_11375_Content = {
    Text = "——這怎能不是他的錯？他做的還遠遠不夠。\n懷著這樣極端自責的情緒，奧吉爾執行任務的頻率是其他喚醒體的兩倍，用人人稱讚的「美德」埋葬「死亡」。\n過量的工作與年輕調查員感激的話語，彷彿真的能洗去刻在靈魂中的悲痛。\n沉屙被推擠進了內心的陰影中，祂們散發著腐爛的惡臭，暗中牽引著騎士走向深黑泥沼。\n「抱歉？您好？」\n有人帶著一縷陽光，或是一陣微風，來到了奧吉爾面前。\n「前輩說，奧吉爾會加入我和拉蒙娜，一同執行我的初次調查任務，對嗎？」\n他無法保護公主第二次，但上天給了他再次守護「守密人」的機會。\n「我的名字是奧吉爾，很榮幸能與您締結契約。我將用靈魂護衛您的生命，今日誓言，永志不忘。」"
  },
  AwakerStory_11375_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_11376_Content = {
    Text = "「厭倦了平淡的公園嗎？厭倦了無趣的動物展覽了嗎？那麼到卡茜亞的魔法嘉年華來吧！喜歡動物的孩子們，這裡有唱男高音的獅子，跳芭蕾舞的火烈鳥，表演雜技的大象，以及世界唯一的毛驢馴獸師！希望增進感情的愛侶們，可以試試我們獨一無二的旋轉活馬，收穫難得的浪漫體驗！覺得生活中缺乏真刺激的勇士們，可以挑戰由嘉年華主人親自設計的鏡子迷宮，如果能將那41個進去了就沒出來的壞客人帶走，還能獲得豐厚的獎品哦！\n除了這些世界僅有的娛樂設施，魔法大師卡茜亞還將向你展示奇妙的狂歡世界，為你帶來人體截斷、大變活人、極限逃脫及更多魔法！幸運觀眾還能獲得上臺親身參與表演的機會，體驗卡茜亞大師精妙絕倫的切割技巧。保證顛覆你的認知，讓你的日常生活變得更加索然無味！更妙的是，這一切都是免費提供，免費！你的快樂就是卡茜亞大師最好的酬勞！\n彌薩格大學的各位，本週末在食堂後的空地上，卡茜亞大師與你不見不散！\n\n注：嘉年華一旦進入便必須完全體驗，不得中途離開。承受能力低及精神、心臟脆弱者慎入。\n嘉年華後出現食欲不振、肢體殘缺、眼睛丟失及腹部開裂等症狀的，本嘉年華概不負責。」\n——《魔法大師卡茜亞的魔法嘉年華盛大開幕！》"
  },
  AwakerStory_11376_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_11377_Content = {
    Text = "「沙龍」不知從何時起，悄然在倫蒂尼恩上流社會中興起。\n在神秘的沙龍中，有人得到了讓巨匠為其留下畫像的機會，有人得以與首相共進晚餐，更有甚者得到了來自女王的一個承諾。\n主理人、舉辦地點、舉辦時間都是謎團，人們只知道，每個人都能在沙龍中獲得自己最想要的東西。\n但無人知曉，怎樣的賓客才能得到主人青眼，獲得一紙邀請函。\n就連八面玲瓏的德克斯特勳爵，也在沙龍主人面前吃了閉門羹。\n「非常抱歉，主人現在更偏好邀請藝術名流。」\n「貴族？請靜候未來的邀請。」"
  },
  AwakerStory_11377_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_11378_Content = {
    Text = "高高在上的夫人拉著她的手，告訴她，自己將給予她世上所有的愛。\n她相信了夫人的溫柔和老爺的縱容，相信了每一個微笑，每一個擁抱，卻不知道自己在他們眼中不過是一個寵物，一旦威脅自身，就可以隨時拋棄。\n他們親手將她扔入牢籠，將她的信任砸得粉碎——但無論是獄卒的鞭打還是族人的折磨，都沒有至親之人的背叛來得那般疼痛。\n恨，好恨，恨他們用謊言換取她的真心，恨他們用她的人生造就了這場苦痛的鬧劇。如果這就是相信他人的結果，那她將永遠做自己的依靠。\n她的信賴只給予她自己。"
  },
  AwakerStory_11378_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_123300_Content = {
    Text = "總有一日，她會回到自己的世界。\n\n但在此之前，她想看到這個世界的結局——\n\n那個被稱為「守密人」的人，是會被這瘋狂恐怖的世界吞噬，還是綻放出光芒，為這搖搖欲墜的世界帶來真正的救贖與光明？\n\n這是個謎團，是個挑戰，是個賭注。\n\n而她，想知道答案。"
  },
  AwakerStory_123300_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_123301_Content = {
    Text = "A.F.3@2年@1月17日，在接到審查會通知@4地區有繁星黎明會正在舉行人牲獻祭後，我第一時間動身前往該地區進行調查。\n當我到達時，已經是傍晚，該地區因不明原因被濃霧包圍，幾乎無法視物。\n我並沒有攜帶驅散霧氣的裝置，但考慮到事情的嚴重性，我仍是衝進了霧中。如果時間能夠倒流，我一定不會再做出這樣瘋狂的舉動，因為、因為霧中有恐怖的@2……\n當那些無法描述形貌的扭曲之物，以非人的速度襲向我時，我根本無法做出任何反應。我的身體陷入僵硬，動彈不得。\n但我終究沒有死。那個女孩，那個謎一樣、來自霧中的女孩救了我。\n她喊的也許是「龍捲風」？我沒聽清，我只看到一個斧子從霧中飛來，劈開那恐怖之物的腦袋。然後那個女孩拿下斧頭，扛在肩上。\n「霧裡可是很危險的，不想死的話，就離開這裡。」\n說這話時，她的表情是微笑的，是那種年輕少女的甜美笑容，但我不知為何卻覺得這笑容比霧中的怪物更加令人毛骨悚然。\n一個人類，或者說擁有人類形態的東西，穿行在怪物橫行的濃霧中，卻還能毫髮無損，並保持這種「甜美」的笑容……\n恐懼之下，我終於爬了起來，驚叫著和她拉開距離。\n很快，濃霧佔據了我的視線，我再次陷入什麼也看不見的境地。但她的笑聲，她那天真的、青春少女的笑聲，一直在霧中迴響著。\n——《檔案：@4地區繁星黎明會調查》"
  },
  AwakerStory_123301_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_123302_Content = {
    Text = "在大多數學生看來，茉夏絕對是最適合成為朋友的人。她總是帶著微笑，興高采烈地附和著話題，且不會輕易拒絕對方提出的要求，因此總有人邀請她一起逛街、聊天、吃飯。\n但只有少數人才知道她的真實面目。在這些人面前，她再也不用偽裝友善，不用掩飾對規則和秩序的蔑視。\n「什麼朋友？只是無聊打發時間罷了。要是不這樣做，可是會被當做問題學生，被訶勒特院長帶去問話——真麻煩。」"
  },
  AwakerStory_123302_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_123303_Content = {
    Text = "她的人生似乎總是充滿了意外：先是遇到肆虐的未知迷霧，再是莫名其妙被召喚到異世界。\n當召喚儀式完成，初次踏上異世界的土地時，茉夏見到了熟悉的濃霧，而在濃霧中，是人們的慘叫。\n那是人牲在逃避邪教徒的抓捕。\n人牲？邪教徒？多麼……令人興奮的新鮮詞彙。\n這代表新的世界，運行著弱肉強食的叢林遊戲，而恰好，她從來都不是弱者。\n她平靜地在霧中狩獵著邪教徒，高興得甚至哼起了歌。\n「一個一個又一個……在無人知曉的濃霧裡，我盡情發洩♪」\n「敲開你的腦殼，深入你的大腦，讓我們在追逐中打發時間♪」\n在這隨意的哼唱中，茉夏察覺到內心空洞的飢渴——\n這個瘋狂的世界無法填滿她內心的空洞，但卻能緩解她靈魂上的、對於破壞與癲狂的飢餓。"
  },
  AwakerStory_123303_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_123304_Content = {
    Text = "嚴格來說，她並不屬於這個瀕臨崩潰的瘋狂世界，但她欣賞這裡。\n欣賞這個世界燃燒的壯麗景色，欣賞這些人類在絕望下的痛苦與崩潰。\n信仰已死，社會停轉，道德崩壞，自然也不需要再偽裝成無聊的「正常人」——\n她終於可以名正言順釋放內心的野獸，展露真實的自己，成為真實的自己。"
  },
  AwakerStory_123304_Title = {
    Text = "基礎資料"
  },
  AwakerStory_123304_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_126929_Content = {
    Text = "沒有幾個人真正知道徐是什麼時候出現在校園內的，就像她在遠東自然而然地漫步於宮廷、王帳以及各種結社。\n所有人都天然地對她有一種熟悉感，彷彿多年老友，甚至心頭摯愛，即使祂們從未一起經歷過什麼。\n只有極少數喚醒體會對徐表現出異乎尋常的戒備，或者說只有極少數實力強悍的喚醒體，能察覺到徐如同霧氣般繚繞綿延，滲入對方記憶的異常能力。\n彌薩格校務處曾認真研討過是否需要對此加以限制，甚至單獨為此研製反制設備，徐通過某些交易和一則承諾，消解了這種擔憂。\n「妾身的意圖，並不在這些小傢伙們身上。」"
  },
  AwakerStory_126929_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_126930_Content = {
    Text = "A.F.@16@1年，一艘其航行痕跡未出現在任何勘探手段獲取範圍內，亦未經過任何手續批准的貨輪，悄無聲息地停靠在倫蒂尼恩貨運港口。\n該貨輪後被證實，來自遠東區域磐龍古國@2港口。\n貨輪入港當夜，供職於該港口的工作人員及附近居民，均表示在夢中見到一名黑髮黑瞳、象牙色皮膚的東方女性。描述該女性的外貌時，目擊者不約而同地使用了「令人著迷」、「熟悉」等字眼，同時，多位男性目擊者在講述過程中出現木僵現象。\n彌薩格調查員迅速對貨輪進行搜索，奇怪的是，除了無處不在的竊笑聲，以及明確出現的靈性反應，沒有發現任何銀芯的痕跡。\n德克斯特勳爵次日進入貨輪貨艙，在一隻「被數次搜索過」的陶瓷制花瓶中，發現了一枚表面流淌著薄薄霧氣的銀芯。\n截至A.F.314年，該銀芯被證實無法以任何手段被喚醒。\n直到現任守密人@3進入彌薩格，該銀芯自行完成了喚醒儀式，覺醒為自稱「徐」的喚醒體，並主動要求與@3進行連結。\n——摘自《彌薩格大學銀芯儲存記錄》"
  },
  AwakerStory_126930_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_126931_Content = {
    Text = "你有沒有覺得世界太過安靜，以至於想摔碎什麼來聽到響動的時刻？\n愛欲是她擲出的一隻銀瓶，被這只銀瓶驚動的獵物……為所愛屠戮，被所愛屠戮，直到心神衰竭，只剩下軀殼。\n然後，這些被榨幹的軀殼，會再將更高更多的權柄獻予她，把目之所及全都染上腥羶可口的混亂。\n永不停止的混亂。"
  },
  AwakerStory_126931_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_126932_Content = {
    Text = "……非其所祭而祭，則謂之淫祀，惑民費財，屢禁不止。\n沿海諸民，均有祭祀雜神舊習，好修淫祠野廟。花費眾多，耕織荒置，然鄉里不覺其患。當政者數毀房廟，官兵即撤，不日復燃。\n更有外邦流民，定居於鄉里，將外邦教派教標倒懸，取@3字形相似者，謂之約「井」，挪為己用。\n廟中所祭主祀及陪祀，皆為生平可查者，多是枉死婦人，初時信眾亦多為農婦、戲子、野娼之流。\n妻帶夫入，母帶子入，娼帶客入。凡壯大，則植黨營私，屢有數村托舉一人之奇觀。或入仕途，或私豢民兵，相爭相鬥。\n@4@4@3@2\n以下字跡均已辨識不清，另有幾行十分工整的@3文字，經語言學系翻譯，譯文如下：\n「不要臉皮的老匹夫，立意偏頗，好生沒趣。妾身無聊，養些蛐蛐來鬥，也偏要嚼幾句口舌。」\n「干你屁事。」\n——摘自《野狐齋雜誌抄本節選》"
  },
  AwakerStory_126932_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_126933_Content = {
    Text = "優雅、嫵媚，擁有致命魅力的東方「神明」。傳說當她挪開扇面，你將在扇下看到自己最愛之人的面容。\n然而傳說只是傳說，祈禱她未將目光投向你吧，當她如無孔不入的夜霧般滲進你的記憶，除了狂亂的癡迷……你的顱內就不會剩下任何其他東西了。"
  },
  AwakerStory_126933_Title = {
    Text = "基礎資料"
  },
  AwakerStory_126933_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_129596_Content = {
    Text = "莫絲喚醒體的情況較為特殊，未拘束狀態下，能力發動並不以喚醒體自身意志為準。其周圍會不定期產生類似漩渦M的特殊能量場，攪碎處於能量場內部的物體。\n當莫絲接觸內部包含水（包括血液等體液）的人或物體時，會加速該位置的能量場產生。由於該現象不受莫絲本人的控制，加上其喚醒初期長期處於癲狂狀態，危險度極高。\n為此，喚醒體系與物理系、化學系等多系進行了跨院合作，在多次嘗試後終於研製出能抵禦其破壞力的合成金屬「莫絲鋼」，並將之製作成口籠和拘束器，予以莫絲佩戴。\n莫絲喚醒體的精神於考德威爾研究員進行的第十一次「O–1841喚醒體接觸實驗」後開始趨於穩定，該實驗中，莫絲將漩渦M–默斯克斯的影響轉移至了自身，從而極大降低了對周圍的危害。\n但還需注意，莫絲僅憑自身無法長時間維持該狀態，唯有藉助「莫絲鋼」拘束器，莫絲才可以長期穩定地將漩渦M的影響維繫在自身內部，同時引導其能力進行戰鬥。\n恢復神智後，莫絲展現出了她開朗的本質，且對諾締拉喚醒體表現出了原因不明的親近。這似乎與兩者精神本源的經歷有關。\n——節選自《莫絲喚醒體報告》"
  },
  AwakerStory_129596_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_129597_Content = {
    Text = "即使她知道如何正確地組織語句、她也無法告訴你她出生於何處。事實上、無論是哪個家、她現在也只能回憶起雪白的沙灘、茂密的叢林、和無邊無際的大海。\n但如果你問她家在何處、她會用生硬的詞語和熱烈的肢體語言告訴你：家在海上、隨著洋流四處遊蕩。\n長久無人陪伴的人無法判斷何為孤獨、但在那艘船上她嚐到了親情、也獲得了友誼：她與那以鸚鵡螺為名的夥伴分享好吃的烤魚、漂亮的貝殼、分享一個關於陸地、關於遠行、關於冒險的夢想、並在最後分享一個歸於黑色海浪和漩渦的死亡。"
  },
  AwakerStory_129597_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_129598_Content = {
    Text = "北大西洋漩渦M–默斯克斯首次出現於A.F. 1■■，在接下來的數百年間，其規模逐漸擴大。截至A.F. 29■，M–默斯克斯已經發展成直徑約260–300英尺（80–90公尺），水流約5英里（8千公尺）寬的大漩渦。\n除去水流帶來的強大吸力及其影響（附近水域的魚類及漁船都為其所害），M–默斯克斯之下還存在一個更大的威脅——融蝕裂隙。經過學院成員長時間的觀察和研究，確定M–默斯克斯的形成與其下融蝕裂隙有直接關係，並於A.F. 313正式對其進行清除。\n在裂隙中，學院發現了大量生物和船隻殘骸，並獲取編號為O–1841的銀芯。\n——節選自《M–默斯克斯事件記錄》"
  },
  AwakerStory_129598_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_129599_Content = {
    Text = "語言不通？不是問題、比手畫腳一樣能夠實現交流。無法控制的能力？在這所學校就如同家常便飯、幾天實驗就可以解決。\n憑藉開朗的笑容和率直到近乎野性的性格、莫絲很快獲得了其他喚醒體的歡迎。雖然她經常因為忘了自己的能力而造成巨大破壞（上天保佑那被重建了3次的噴水池）、但那又怎麼樣呢？她不是故意的。\n大概。"
  },
  AwakerStory_129599_Title = {
    Text = "基礎資料"
  },
  AwakerStory_129599_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_129600_Content = {
    Text = "在一切被急流吞沒之前，在無垠的大海和微鹹的海風中，在那艘船上，沒有血緣的家人和朋友讓她明白了孤獨的含義，並不願再落入其中。\n可為了她最好的朋友，她小小的家人，她甘願再次回歸那漆黑的死寂。\n在一切被黑暗覆蓋之後，她以另一種姿態獲得了新生。雖然這樣的生活多有不便——她時常忘記自己的力量會給周遭的事物帶來巨大破壞——但獲得更多朋友的可能性依舊讓她無比快樂。\n當然，如果她最好的朋友能夠想起她們曾經的故事，那就更好了。\n「比更好更好，更更更好！」"
  },
  AwakerStory_129600_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_134315_Content = {
    Text = "被網圍困的織網者，命運劇院的劇作家與永恆的觀眾。\n絲線從指間垂落，纏繞成幕布、劇本與牢籠——每一根都由阿拉克涅親手紡出，又將她層層裹縛。\n觀眾席永遠空無一人，唯有她自己在台下凝視台上自娛自樂的演出，循環往復，永無終場。\n她的存在，是劇院的幽靈，也是命運的具象。"
  },
  AwakerStory_134315_Title = {
    Text = "基礎資料"
  },
  AwakerStory_134315_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_134316_Content = {
    Text = "阿拉克涅起初並不清楚自己能看見命運。 \n世界對她而言和其他人一樣，模糊、喧鬧、充滿偶然。\n兩歲那年，她說出了人生中的第一句話。 \n不是「媽媽」，也不是「爸爸」，而是站在門廊下，對著照顧家族數代的老管家輕聲說：「晚安」。 \n那天晚上，管家因心臟病猝然離世。她攥著他留下的懷錶，在門房外哭到睡去。那時她還不懂死亡與命運，卻已嘗到了命運提前泄露的苦澀滋味。\n五歲，在晚宴賓客臉紅耳熱的歡呼聲中，她學著母親的樣子，踮起腳尖跳起笨拙的華爾茲。 \n腳上那雙紅舞鞋鮮豔得像血，也像某種預兆。她轉圈時跌倒了，沒人會發現她眼中一閃而過的畫面，好像注定要跌倒似的。\n七歲生日，父親送她一件名為「摩伊賴」的紡輪，那是命運三女神的名字。 \n她在林間奔跑，笑聲清脆，卻在絆倒時聽見咔的一聲，紡輪斷了。 \n她蹲在落葉裡，手指撫過裂痕，忽然發現彷彿有無數絲線從斷口湧出，纏繞她的指尖，直通向看不見的遠方。\n後來，她第一次走進歌劇院，第一次結識摯友，第一次親手埋葬愛犬…… \n每一個「第一次」，都伴隨著無聲的終幕在她眼前閃現。她開始明白：所謂開端，都早已定下了命運的終局。\n從此，視線再無法停留於表象。人臉成了薄紗，她一眼便能望穿其下奔湧的命途：誰將病逝於夏末，誰會在婚禮前夜自縊，誰的孩子將在十年後親手埋葬他……驚喜消亡，期待枯萎。所謂「未來」，不過是她提前拆封的訃告。\n她曾試圖提醒周圍人即將到來的厄運，卻總在言語出口的剎那，促成預言的實現。 \n面對他們驚懼退避的眼神，那一刻她終於明白： \n「看見，並不等於能改變」。\n命運之網早已織就，她的「預知」不過是網眼間偶然透出的一縷光——照見結局，卻無力扭轉經緯。\n於是她拿起那件名為「摩伊賴」的紡輪。 \n斷掉的紡輪早已被修復，但裂痕仍在。她日復一日地紡織著，關於命運的天賦奇異地與這紡輪融合為一。 \n從此，所有人的命運，皆在她指間流淌、交織，織成一張橫跨時空的巨網。無形之間，她也被這張永恆的網困在其中。她見證著無數歡笑與淚水，無盡的支點、無盡的可能性裹挾著命中注定的毀滅一次又一次上演……\n而阿拉克涅不會停下。不是為了編織，而是為了維繫——若她停止，整張命運之網或將崩解，連同千萬人生一同歸於虛無。 可是她也看到，當命運之網編織完成，祂的甦醒也將帶來無可避免的毀滅……\n她作為織者、也是被縛者，成為了觀眾、也成了囚徒，是劇作家、亦是劇中人。\n能看清他人的命運，究竟是好事還是壞事？ \n阿拉克涅早已不再追問。"
  },
  AwakerStory_134316_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_134317_Content = {
    Text = "幕布尚未完全升起，燈光已如潮水般傾瀉而下。\n彌薩格的觀眾們屏息凝神，等待命運的主角登場。\n舞台很小，小得幾乎容不下俄狄浦斯的腳步。可當那個穿校服的少年舉起手，聲音穿透簡陋的舞台時，他說出的第一句台詞竟如神諭降臨：「我就是那不幸的人，命中注定要弑父娶母。」\n……\n「我究竟犯了哪一條神律呢……我這不幸的人為什麼要仰賴神明？為什麼要求神保佑，既然我這虔敬的行為得到了不虔敬之名？」名為安提戈涅少女質問著神律的不公。\n……\n哈姆雷特在丹麥的城堡中踱步思考。「生存還是毀滅，這是一個值得考慮的問題；默然忍受命運的暴虐的毒箭，或是挺身反抗人世間的無涯的苦難，通過鬥爭把它們掃清，這兩種行為，哪一種更高貴？」\n……\n審判席上，約翰·普羅克托緩緩抬起頭，宣告了他的答案：「因為我在那些登上絞刑架視死如歸的人面前連糞土都不如，我怎麼能名譽掃地地活下去？」\n……\n那些關乎命運的詞句，演成了今天這一出戲劇。\n阿拉克涅站在側幕，手指無意識地掐進掌心。\n那些因劇中人物而共情的眼淚，謝幕之時如雷鳴般響亮的掌聲……\n台下觀眾的種種面孔盡收眼底，她忽然覺得，那顆長久以來無謂跳動的心，終於找到了節拍。\n此時此刻，她的聲音、她的存在，已悄然嵌入這浩蕩的命運之流——不再只是觀看命運的眼睛，而是正在書寫的嶄新劇本。觀眾的命運、表演者的命運以及劇作家的命運，因一出正在上演的戲劇得到了連接……\n心之勝利，原來如此安靜，又如此震耳欲聾。"
  },
  AwakerStory_134317_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_134318_Content = {
    Text = "作為命運之網的編織者，那個維繫千萬人生死經緯、掌中流淌著過去與未來的存在，阿拉克涅有著一個近乎淺薄的愛好。\n她熱愛戲劇。並非迷戀情節的跌宕或台詞的華美——那些早已爛熟於心，作為劇本的創作者，情節的每一處轉折、演員的每一句台詞她都了如指掌。\n可她仍一次次走進劇場。\n她真正渴求的，是踏入劇場那一刻身臨其境的「在場感」。\n當幕布升起，觀眾席沉入黑暗，舞台卻成為唯一真實的世界。那一刻，時間不再是單向奔流的河，而是在限定空間的演繹——過去、現在、未來在此重疊，一切不再是紙張之上的劇本，而是正在「此刻」發生的生命顫動。\n而她，終於不再是那個站在命運之外，只能凝視絲線卻無法觸碰的旁觀者。\n在劇場裡，她可以短暫地封存記憶、站上舞台，讓自己成為那個顫抖著說出遺言的少女，抑或是作為放任演員自由表演的觀眾，卸下先知的重負，因演員的一顰一笑而屏息、流淚、顫抖。不是作為預言者，而是作為一個活生生的人，以無知者的姿態，與角色同頻呼吸、為一句台詞心碎。哪怕明知結局無可更改，哪怕悲劇注定降臨。這份幻覺，卻讓她短暫地掙脫了永恆觀眾的宿命。\n不被隔絕於命運之外，而是被允許進入其中——哪怕只是一瞬，哪怕只是幻影。\n這微小的沉溺，已是命運給予阿拉克涅最奢侈的恩典。"
  },
  AwakerStory_134318_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_134319_Content = {
    Text = "我於3@2年秋末前往舊城區的「命運劇院」參加次女高音職位的面試。\n抵達時為下午四時十七分，天色陰沉，無雨。劇院正門未鎖，觀眾席空無一人，根本沒有面試官的身影。\n可是舞台中央正在上演一齣木偶戲——沒有提線人，沒有樂聲，只有幾具蒼白的人形傀儡在無聲地舞動。它們的動作精準無比，關節轉動時發出細微的咔噠聲，令人毛骨悚然。而那些絲線……那些從穹頂垂落的絲線，竟似有生命般微微震顫，時而繃緊，時而鬆弛，彷彿在應和某種不可見的節奏。\n就在我試圖轉身離開時，貴賓席第五號包廂傳來一道女聲。 \n「歡迎你，克莉絲汀。」\n那聲音既非年輕也非蒼老，像是從百年塵封的絲綢帷幕後滲出的迴響，詭異而恐怖。\n我渾身發冷。還未做自我介紹，她怎會知道我的名字？而且這些人偶……\n我拔腿奔向出口，可就在我即將觸到門把手的剎那，黑暗中湧出無數蜘蛛——眼中閃爍著幽光，牠們吐出銀白的蛛絲，試圖封堵我逃跑的路線。更驚悚的是，那群蜘蛛竟然口吐人言，一直重複那句「唱吧，我的天使，為我歌唱吧……」。\n我拼命撕扯、奔跑、尖叫，最終竟真的逃了出來。 \n……\n從此我害怕來自貴賓席第五號包廂的視線，於是要求歌劇院將這個包廂封存。\n然而……如今每當我站在聚光燈下高歌，總感覺頭頂有絲線輕輕牽動我的眉梢。\n難道我也變成了被絲線操縱的木偶？我不敢繼續細想。\n\n——節選自《歌唱家克莉絲汀回憶錄》"
  },
  AwakerStory_134319_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_139857_Content = {
    Text = "當一切被血肉侵蝕，當日常被錯亂顛倒，嘶鳴的雜音中，蒲公英飄落到了這片荒原。\n伸出手吧，牽住她吧。\n愛會突破表象，將你與你所愛之人，再次錨定。"
  },
  AwakerStory_139857_Title = {
    Text = "基礎資料"
  },
  AwakerStory_139857_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_139858_Content = {
    Text = "和將要發生、還未發生的一樣，和銘記在心裡、永遠不會遺忘的那些事一樣。\n無論外表變成什麼樣子，無論世界變成什麼樣子，極其不同，又極其相似的兩個人，會得出同一個回答。\n「我們有想要見到的人。」\n「我們會不顧一切找到他們，找到能夠與他們一同存在的世界。」\n「如果那條路途太過遙遠，我們就會一直在找到他們的路上，在尋覓裡度過漫長的一生。」\n或許是因為這樣，在血肉的嘶鳴聲中，那枚璀璨的銀芯被放進了守密人的掌心。"
  },
  AwakerStory_139858_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_139859_Content = {
    Text = "「沙耶」究竟是什麼？解開答案的鑰匙，存在於某個遙遠的彼方。\n「……被命名為沙耶的那個生物——她會出現在這個宇宙的理由，不是偶然，而是出自作為生物，被預設好的本能的結果。其所指向的，乃是一切生物的終極目的，繁殖。她與她的眷屬，是能夠跨越異次元之壁、播撒種子的生物。……」\n「……根據推測，沙耶這個個體，是否在她們的種族中，也是一個例外的存在？人類是一個因為智性而顛覆了本能的種族，這個物種的缺陷，是否也被沙耶繼承了？在學習人類的過程中，人類與本能矛盾的感情觀念，或許使沙耶的繁殖本能也被一併摧毀……」\n「——總有一天，以愛為名的祝福會降臨到她頭上。灼熱的戀愛在她心中燃燒，她將可堂而皇之地遊遍世界，再次恢復閃耀與光輝。」\n要用善惡來衡量她嗎？還是要用愛意的真摯與否來衡量她呢？\n可能這一切根本就沒有答案，帶著那個世界無解的答案，意外來到許久之前，什麼都還沒有發生的這個宇宙的沙耶，被記憶中的答案引領著，想著遺忘的彼方，繼續前行。\n她等待著蒲公英盛開的那一天。"
  },
  AwakerStory_139859_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_139860_Content = {
    Text = "沙耶很快就成為了一名受歡迎的學生，極強的學習能力、求知若渴的好學精神——在彌薩格，擁有這些品質的喚醒體，甚至遠比她特殊的體質更為稀有。\n出乎意料地，沙耶對拉蒙娜展現出了異乎尋常的興趣，或許是由於拉蒙娜跟守密人之間的羈絆，又或許是由於拉蒙娜跟德克斯特之間特殊的父女關係。\n介於沙耶與人類完全不同的善惡觀與道德觀，學院一度建議拉蒙娜採取特殊的安保措施，然而當事人拒絕了此項提議。\n她們談話的內容無人知曉，但極偶爾地，在某個彌薩格溫暖的午後，草坪上溫柔的風，會參與她們之間不為人知的長談。"
  },
  AwakerStory_139860_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_139861_Content = {
    Text = "離人類最遠的種族，在學習如何成為人類的過程中，變得連與本能違背的地方都與人類相像。\n如果沒有愛，那原本要創造的世界就是毫無意義的。\n如果有愛，那就只有創造有兩個人所在的世界才是有意義的。\n只是如此恐怖和殘忍而已，只是如此純真和光輝而已。"
  },
  AwakerStory_139861_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_142869_Content = {
    Text = "龐托斯花了很長時間去追查蕾莎的死因，她經歷過太多場艱難的戰鬥，取得過太多場卓絕的勝利，或許是藥物、或許是不為人知的魔術，總會有一個原因，一個令蕾莎死在一隻孱弱的海怪手上的原因。\n直到很久，很久之後，他的某位未曾加入厄波揚斯的人類同行者，長出了第一根白髮。\n逐漸跟不上的體力，逐漸遲鈍的反應，以及哪怕沒有訴諸於口，但溢於言表的對於安定平靜生活的渴望，一切都是如此熟悉。\n龐托斯突然明白了，那個始終不見蹤影的敵人的名字——「衰老」。\n蕾莎隱居的原因，蕾莎被打敗的原因，令他一生的可能性從此消失，只剩下仇恨的原因，就只是這麼隨處可見，又無法抵擋的東西。\n但這沒有任何關係，他的毀滅到來得太早，獲得的力量又太過讓他滿意。\n無論要向怎樣的存在效忠，無論要付出什麼樣的代價，它都不會再發生在厄波揚斯。"
  },
  AwakerStory_142869_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_142870_Content = {
    Text = "「你到底是不允許衰老發生，還是不允許任何你無法控制的事情發生？」\n他沒有回答，他也不需要回答。\n深淵比災難更早選中了他，因為他未宣於口的執念與深淵如此契合。\n聽從、陪伴、一成不變，如同深淵無法掙脫，如同深淵令一切窒息，又留存一切。"
  },
  AwakerStory_142870_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_142871_Content = {
    Text = "彌薩格大部分師生都非常樂意在外勤時尋求龐托斯的幫助，且龐托斯也從來不吝於伸出援手。\n慷慨、爽朗、穩重可靠，就算明顯與校內部分成員存在嚴重摩擦，這名喚醒體給人的第一印象依然好得驚人。\n然而，雖然龐托斯本人已與彌薩格達成協定，不再擴大厄波揚斯的居民規模，但經歷數次「結束路徑特殊」的外勤行動後，依然有大量移居申請遞交到校務處。\n在茜爾維婭對申請者們進行集體心理輔導的同時，校務處迅速增補了以下兩條外勤條例。\n1、如非極度緊急情況，嚴禁向龐托斯求援。\n2、如非極度特殊情況，嚴禁進入厄波揚斯。"
  },
  AwakerStory_142871_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_142872_Content = {
    Text = "原本應該翱翔於夜空的英雄史詩戛然而止，他選擇墜入深淵，把自己獻祭給更加偉大莫測的存在。\n從此他再也不用面對分離、平庸，和無可奈何的衰敗。\n他把自己的親人、友人、敵人，都永遠留在了與他融合為一的厄波揚斯。"
  },
  AwakerStory_142872_Title = {
    Text = "基礎資料"
  },
  AwakerStory_142872_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_142873_Content = {
    Text = "A.F.2@17年8月，以納拉@1灣為圓心，半徑@3英里內，出現多起異常靈性事件。\n@1封來電聲稱目擊到已被登記死亡的數名人類個體，在@3舊址附近出沒，這些個體後經查證，均亡故於@2港鎮在1@19年發生的爆炸事件，該爆炸原因迄今仍未查實，涉事人員均有不同程度的記憶缺失症狀。\n「我見到她了，我發誓……她仍然和我與她分別時一樣年輕，但這絕無可能。」\n「她和我告別已經是@2年前的事了，但她還是那麼美麗，她只是和他們一同站在懸崖邊，遠遠地向我微笑。」\n「……當我們被珍視，我們會始終擁有再次選擇的機會，EBWYN@2OS，Ebwy@1noss……」\n錄音材料結尾被近似海水湧動聲的不明雜音汙染，該目擊者於20小時後因器官衰竭在家中死亡，死亡時的年齡為76歲。\n該材料寄達彌薩格大學後次日，已退休的喚醒體系研究員，亦是該目擊者錢伯斯·考德威爾的遠方親屬，艾琳·考德威爾，收到了錢伯斯帶來的O-@1銀芯。\n據艾琳·考德威爾回憶，錢伯斯的身形樣貌，均與年輕時無異。\n他在消失前只留下了一句話。\n「請將祂帶去彌薩格，祂要在那裡等待最後一位厄波揚斯的歸人。」\n——摘自《彌薩格大學銀芯儲存記錄》"
  },
  AwakerStory_142873_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_146395_Content = {
    Text = "無論是哪個維度的蘿坦似乎都不喜歡言語，蝕滅·蘿坦更是如此。在她面前，語言是多餘的，力量本身就是最完美的修辭。\n在如君王般從容優雅的外殼下，她那雙如瀕死恆星般的異色瞳孔裡，燃燒著她最為真實的渴望——她是星海深處升起的遠古之力，是混沌在憤怒中鑄就的白骨利刃。萬物在她眼中只分兩種：值得一戰的，和不值得揮劍的。\n那對由星天之鯨的骨骼所鑄就的巨劍始終飢渴，正如她對力量之巔的渴望永無饜足。"
  },
  AwakerStory_146395_Title = {
    Text = "基礎資料"
  },
  AwakerStory_146395_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_146396_Content = {
    Text = "她最初的記憶只有憤怒。\n沒有面孔，也沒有形體的邊界，只有無窮無盡的、沸騰翻涌的暴力本能。她是星海深處凝聚的混沌，是億萬年間釀成的災厄。她撕裂，焚燒，吞噬，不為任何目的，只因為那是她唯一知道的事。\n直到那位白紗的「神明」到來。如同一顆恆星被從內核剖成兩半，她感到自己的力量如潮水般退去，血肉與骨骼從精神中被連根拔除，洶湧的怒焰被活生生地從靈魂上剝離。\n\n神明無法平息她的憤怒，於是選擇將她的靈與肉分離。\n混沌之獸不再存在，她的軀體化為利維坦，帶著她全部的力量沉入虛空。而她，一個僅剩精神的殘骸，在空蕩蕩的意識中醒來。\n怒火並未熄滅，而是轉變為了更為持久、更為令人畏懼的東西：渴望。對力量的無窮盡的渴望，驅使著她重新站起來。\n她開始行走，開始戰鬥。她在荒蕪的星海之間流浪，挑戰一切擋在面前的強者。每一場勝利都像是往空洞的軀殼裡填入一把沙礫，她漸漸從沙礫中磨出了形狀，磨出了意志，磨出了屬於「蝕滅·蘿坦」的輪廓。\n\n然後，她聽見了那頭鯨的歌聲。\n將身軀化為整個世界的星天之鯨，束縛奴役萬千生靈的龐然大物，她在祂身上看到的不是慾望與恐懼，而是親切。她的記憶開始恢復，她知道那是她的力量，她知道，從始至終，祂就是屬於她的。\n於是，她來到祂的面前。\n於是，她向祂拔出劍。\n\n巨鯨的權能如決堤的洪流湧入她的身體，幾乎將她撕碎，但從始至終她依然站立，星海之中，多出了一具巨鯨的屍骨。\n被奴役的星球重獲自由。死於慾望的魂靈們抬頭仰望，將她稱作救世者、守護神，將王冠送至她的身前。\n蝕滅·蘿坦沒有回應那些讚頌。她只是站在巨鯨的屍骸之上，感受著體內翻涌的新生力量，聽著靈魂深處那道從未消失的呼喚變得前所未有的清晰。\n那是星天之鯨的聲音，那是她自己的血肉在呼喚著她。\n\n她的手觸碰利維坦的顱骨，分離了無數紀元的精神與肉體重新交融。骨甲覆上她的軀體，力量充盈她的身體。\n混沌之獸重生了，但她已不再是當初那頭只知暴怒的災厄。漫長的流浪，無數的戰鬥，那些曾被她擊敗和擊敗她的對手們，已經將這純粹的混沌鍛打成了擁有意志的鋒刃。\n她閉上眼，享受著體內翻涌的、完整的力量，但她也清楚地知道，這並非終點。\n\n星天之鯨的權能，利維坦的力量，那些吞噬過的星辰……一切都是身後的階梯。她提起骨劍，轉身走向下一片未知的星海。\n她渴望著，下一場令她沸騰的戰鬥。"
  },
  AwakerStory_146396_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_146397_Content = {
    Text = "蝕滅·蘿坦從不回望身後的屍體。\n被擊敗的對手、被踏碎的荒原、被吞噬的星辰……她一一跨過它們，尋找著下一個目的地。\n\n有人問她，抵達力量的盡頭之後要做什麼。\n她沒有回答，因為這個問題毫無意義，就像詢問火焰燃盡之後要去何處。火焰沒有「之後」，燃燒本身就是它存在的全部。\n\n她行走，她戰鬥，她一次又一次地舉起劍，從來不是為了證明、守護、復仇、權慾，或是別的什麼無聊東西。\n只是因為，在劍與劍碰撞的那一瞬間，在力量與力量交鋒的那一剎那，她能最清晰地感受到自己活著。\n\n追尋力量的道路沒有盡頭。而她慶幸如此。"
  },
  AwakerStory_146397_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_146398_Content = {
    Text = "抵達彌薩格之後，蝕滅·蘿坦的安靜維持了兩天。第三天的黃昏，她帶著她的骨劍出現在公共訓練場。\n\n彌薩格的喚醒體們有著驕傲的資本，會出現在訓練場的尤其如此。但對於這位無禮的不速之客，他們始終保持著高度的警惕。在火山島的簡單接觸後，關於蝕滅·蘿坦的傳說已經在喚醒體之間流傳開，他們知道自己將要面臨的是一位怎樣的對手。\n然而事實證明，他們的警惕還不夠。\n\n當第一位上前挑戰的喚醒體被一劍拍飛出訓練場邊界、擊倒二十米外的石牆時，整個訓練場陷入前所未有的亢奮之中。第二位，第三位……在@3年這個普通的黃昏，先後有九名喚醒體對蝕滅·蘿坦發起了挑戰。\n\n據在場的校刊記者漢娜描述，蝕滅·蘿坦在整個過程中沒有說過任何一句話，如同一座沉默而堅不可摧的燈塔，屹立在喚醒體們如海潮般猛烈的進攻中。那兩柄骨劍如燈光般在晚霞中閃耀，優雅的弧線精準地終結著每一位對手的攻勢。\n\n那一天，蝕滅·蘿坦的鎧甲折損超過80%，肩膀與腹部有兩處極為嚴重的創傷，骨劍上留下了一道巨大的豁口，幾乎斷裂。而以這一切為代價，她成為了最後唯一還站在訓練場上的人。\n\n她看著牆壁上被劍劃出的深痕、地面上那些巨大衝擊力留下的深坑、還有那些神色複雜地盯著她的喚醒體們，露出了來到這個世界後的第一個笑容。\n\n「很高興和你們見面。你們可以叫我蝕滅·蘿坦。」"
  },
  AwakerStory_146398_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_146399_Content = {
    Text = "《彌薩格大學天文觀測站異常報告》\n\n洪積@3年起，北半球多座天文台陸續報告了銀河系邊緣區域的異常光譜衰減現象。初始數據顯示，至少三顆已編目恆星在極短時間內從可觀測範圍中消失，其光譜殘留與任何已知天體衰亡模型均不相符。沒有超新星爆發的輻射特徵與黑洞吸積的引力透鏡效應，恆星彷彿被某物一口吞噬，乾淨俐落，不留殘渣。\n\n洪積@3年3月，審查會天體異象小組在第四顆恆星消失坐標處捕捉到一組極低頻的靈知波動。同年8月，第五次消失事件發生後，天文觀測站終於藉助改良後的銀芯長程探測陣列捕捉到了短暫的視覺信號：一個由白骨構成、外形近似鯨魚的巨大生物，腹部密布尖刺狀突起，口腔內部呈現出與物質界不相容的高溫光譜。它張開巨口的瞬間，恆星的光芒如同溪水流入深淵，悄無聲息地消逝。\n影像僅持續0.7秒便因探測陣列過載而中斷。事後檢測發現，陣列中三分之一的銀芯材料出現了不可逆的結構崩塌。\n\n洪積@3年冬，天文台監測到靈知脈衝信號突然改變方向，其目的地正是筆者所在之處。\n審查會進入最高戒備狀態，然而預想中的災難並未降臨。信號在接近近地軌道時收束至無害狀態，最終定位於西北海域的一座無人火山島。當第一支勘探隊登島時，他們在火山口的玄武岩壁上發現了深深嵌入的、由某種未知骨質材料構成的巨劍，以及劍旁盤膝而坐、彷彿等候已久的人形個體。\n\n該個體為女性外表，通體覆有骨質甲片與異族鎧甲紋飾，雙瞳異色。在勘探隊接近時，她睜開眼，語氣中不含任何敵意，只有一種近乎傲慢的平靜。\n「你們之中，有誰值得讓我出手嗎？」\n勘探隊面面相覷，無人作答。沉默片刻後，她重新閉上雙眼。\n「那就去找一個來。我等著。」\n\n此後，審查會與彌薩格大學聯合將該島嶼列為特級監控區，並派遣多名喚醒體前往協助調查。經過長達數月的遠程觀測與謹慎接觸，該個體最終同意在「獲得足夠強大的對手」這一條件下配合審查會的管理，編入喚醒體名錄。\n恆星消失事件自該個體被收容後完全停止。但檢測數據顯示，那些被吞噬的恆星能量，似乎仍以某種形式存儲於個體體內——在長時間的觀測期間，她的諾斯指數依然在持續攀升，且未表現出任何衰減趨勢。"
  },
  AwakerStory_146399_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_147418_Content = {
    Text = "位於金波特城西部山嶺的農莊，如今已變成一片荒漠，再也無人居住。\n@2年6月15日，一塊隕石墜落於此。數周後，隕石墜落區的生態系統開始變異，植物瘋長、結出怪異果實；動物變異，一戶居民全家精神失常並離奇死亡。\n彌薩格調查員在當地展開地毯式搜索，最終在井底發現了散發奇異色彩的銀芯。據當時經手的調查員回憶，該銀芯的色彩是「純粹的、四處流動的色彩，且與已知光譜中的任何顏色都不盡相同。」\n\n——摘自《彌薩格大學銀芯儲存記錄》"
  },
  AwakerStory_147418_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_147419_Content = {
    Text = "1.不要和D03產生直接眼神接觸，否則她會以每秒20碼的速度衝上來請求你幫她找姐姐。\n2.身上會源源不斷地散發熱量，我曾親眼見到她手中的水仙花在短時間內迅速枯萎。哦，真是環保主義者的噩夢！\n3.晚上真的會發光！亮閃閃！救命我的狗眼@3有D03在的彌薩格真的不需要路燈了。\n4.在食堂與D03的手臂發生直接物理接觸，我發誓我不是故意的！很奇妙的觸感……非要形容的話，像是摸到了麥芽糖漿、羊乳酪、蘋果布丁……嗚，肚子餓了。\n5.聽說暗影合唱團的那幫傢伙曾邀請D03加入社團，然後以最快的速度踢掉了她。這很正常，人類的聲帶再糟糕也是有極限的，我能理解同學們受到的驚嚇。\n\n——摘自漢娜《喚醒體觀察筆記·D03》"
  },
  AwakerStory_147419_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_147420_Content = {
    Text = "她用歌聲打動了千千萬萬的荒星人。\n不眠的夜裡，孩子聽著歌聲沉入夢河。\n綿綿的細雨裡，遊子聽著歌聲不住歎息。\n失去愛人的風裡，戀人聽著歌聲流下最後一滴眼淚。\n而現在，她的聽眾皆已化作風離去，只留下一地未完的故事……"
  },
  AwakerStory_147420_Title = {
    Text = "基礎資料"
  },
  AwakerStory_147420_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_147421_Content = {
    Text = "「唱吧！歌聲是溫柔的風\n飛出雲層，劃過星穹\n世界從此與我無關」\n——摘自專輯《群星之彩》序曲\n\n曾是荒星著名的歌姬。\n在那場災厄來臨之際，她將手中的船票轉贈給經紀人，因為「不能和姐姐分開」。\n然後她目送滿載權貴的飛船悠然離去。那扇曾向她敞開的浮華之門，現在徹底關閉。留給她的，只有沙漠、姐姐和無數同胞。\n他們在靜默中聆聽死亡倒計時。\n\n十年，二十年，一百年……汀克特用歌聲撫慰大家。\n直到喉嚨溢出鮮血，她也無法改變姐姐和同胞一個個死去的現實。\n\n歌者汀克特獨自穿行在白色的荒漠裡，時常幻想姐姐還活著。\n她們像過去一樣擁抱彼此，看著頭頂的星穹一片片墜落，對岸戰艦的殘骸靜靜燃燒。\n她依然不曾放棄歌唱。即使聲音嘶啞如破碎的風箱，將附近一切生靈吞噬殆盡。\n歌者只是麻木地、日復一日地唱著歌。\n只要還有歌聲，「世界從此與我無關」。"
  },
  AwakerStory_147421_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_147422_Content = {
    Text = "「當一個人總是在回憶過去，說明他已經老了。」\n若是參照這句老話，汀克特應當衰老如宇宙中流轉萬年的恒星。\n她的意識裡沒有現在，也沒有未來，只有被無意義延長、不斷循環往復的過去。\n\n她曾見金色的煙火如海嘯般升起，在宇宙星河中舒展羽翼；\n她曾見數萬張不同的臉隱匿在黑暗中，跟隨她的旋律縱情起舞；\n她曾見諸天呼喚著她，環繞著她，向她展示它們永恆的輝煌。\n而她的雙眼只注視著這片苦難的大地。"
  },
  AwakerStory_147422_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_148397_Content = {
    Text = "該銀芯由彌薩格守密人%player%在@2峰崩毀事件後回收，由於其原所在維度已無法觀測，銀芯析出後的影響及實際喚醒方式暫時未知。 \n以下內容，記敘於守密人%player%隨身攜帶的紙質手記： \n銀芯質地經肉眼觀測，極度純淨，無任何可見雜質。當無外力介入時，整體結構趨向規則，似乎有某種意志努力使其看上去堅固穩定，並煥發出如同火彩的明亮光澤。 但該銀芯的諾斯指數近乎觸達底線極值，實際內部結構極其脆弱鬆散，當觀測距離小於1/@1英寸時，會觸發該銀芯的自我保護行為，觀測者將突然看見大量形似冰晶的流動粒子，推測它們此前正在以極其特殊的方式折射外界光線，保護銀芯的核心不被窺探。 換句話說，雖然這很不專業，但我認為這是一枚充滿了「欺騙」的銀芯。 \n在觸發銀芯的自我保護機制後，觀測者的身軀會陷入短暫木僵狀態，瞳孔漸漸褪色，最終完全呈蒼白色，銀芯將在此期間進行調整，直到重新回到被觀測前的穩固狀態。 經多次試驗，這種自我保護機制不會造成實際傷害，但隨之產生的失溫症狀依然存在一定危險。注：及時食用甜食，尤其是蘋果類甜品有明顯緩和作用，原因……暫不明確，吧？ 好消息，在發生這一切之後，這個自私的、內心充滿層層防備的小騙子，顯然對我們並沒有真正的惡意。 \n——摘自《彌薩格大學銀芯儲存記錄》"
  },
  AwakerStory_148397_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_148398_Content = {
    Text = "以下內容由卡拉布轉述、彌薩格喚醒體系背景調查組整理記錄成文：\n卡拉布幼年時正值十字軍東征的熱潮，孤苦無依的她決定向東前往安條克公國投奔姨父一家。聽說東方的新土地象徵著自由與夢想，一文不名的人也能在那裡找到自己的出路。羅莎姨媽甚至經營起一座種植園，過得還不錯。卡拉布幼年與羅莎姨媽關係極好，她下定決心要攢夠路費前往安條克。 \n卡拉布在城市的貧民窟流竄，毫無背景的她只能靠偷拐搶騙苟活，原本單純的一面被消磨殆盡。後來她遇到了巫師艾伐格，他許諾卡拉布，只要與自己合作，信徒們的供奉兩人三七分成，這樣她就可以攢夠前往東方的路費了，還能買很多最喜歡的糖果。兩人於是組成了招搖撞騙二人組，卡拉布被奉為小仙女教母居住在鄉下臨時搭建的神殿內，艾伐格則以她大祭司的身分招攬信眾。 \n隨著卡拉布在當地的名聲越來越大，她開始不滿足於現有的分成，以退出合作威脅艾伐格將供奉扭轉成了七三分成。總算佔得上風的卡拉布悠哉地作為假教母生活著，直到她發現艾伐格竟然挪用了她的供奉，偷偷娶了三個老婆還生了四個兒子。面對欺騙，卡拉布並不生氣，她深情地告訴艾伐格，自己深知前往東方只是個虛無縹緲的夢想，金錢於她無用，不如留給艾伐格，只希望能與艾伐格一家人共進晚餐，共同商討未來的欺詐事業。 \n意外發現卡拉布終於懂事了，艾伐格十分開心，邀請她前來赴宴。晚餐臨近尾聲，卡拉布忽然變臉，在她的一聲令下，附近的村民、她忠誠的信徒們忽然衝進來，手持農具和廚具將巫師一家八口打了個半死，家中值錢的東西被一掃而空。「想騙我還嫩了點」——卡拉布心滿意足離開，尚且未注意到自己額頭上小小的黑色三角......"
  },
  AwakerStory_148398_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_148399_Content = {
    Text = "眾所周知，學校的別稱是什麼？\n象牙塔！ \n聽上去就和仙女這個名號非常相配，畢竟，要到哪裡再去找一個有錢、有閒、還有很多內心充滿可貴信任的潛在信徒的，完美天堂呢？ \n卡拉布的教派以一種堪稱迅猛的速度，在短期內就發展出了為數可觀的信徒，中堅力量幾乎全部都是幼年喚醒體，他們近乎虔誠地相信著這位「仙女教母」，心甘情願地定時定額上繳糖果和點心。令人意外或意料之中的，卡拉布的確會時不時降下一些賜福，多數發生在雷歐王國的傳統節日，比如3@1年銀霜節那場本不可能的降雪，以及新年夜被津津樂道至今的糖果雨。 \n教務處似乎甚至從未討論過是否要阻止這種，原則上不應存在的「校內傳教行為」。\n「讓祂們玩吧，我們都知道這些孩子曾經經歷過什麼，總有一些事情是隻有同樣是孩子的人才能做到的。」 \n「當然，不能太過頭。」\n某位不便透露姓名的校內人員笑眯眯地發表了如上言論，據不可靠消息稱，和她共進紅茶之前的那次事件，是卡拉布迄今為止唯一一次，真正嘗試觸碰校規。"
  },
  AwakerStory_148399_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_148400_Content = {
    Text = "她像是最懂事的孩子，永遠懂得你最隱秘的心思，總是讓你忍不住信任與傾訴，然後在恰到好處的時機，為你提供最求之不得的「賜福」。但請謹記，千萬不要因為她嬌俏的身軀和楚楚可憐的眼神而心生憐憫，以免成為那純白身軀曾經吞噬的貪婪冤魂中的一員。"
  },
  AwakerStory_148400_Title = {
    Text = "基礎資料"
  },
  AwakerStory_148400_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_148401_Content = {
    Text = "你試過說謊嗎？第一句謊言出口的時候，總是伴隨著磕絆的唇舌、幾乎躍出喉嚨的心跳和掌心的汗水，連和暖的日光也化為令人頭暈目眩的炫光。 而當謊言重複一萬次，恐懼便會消失。說出口的話語會變得流暢，思路日益清明，微笑也固化為自然。 扮演仙女，扮演教母，扮演某位掌權者的親眷，她早已熟稔自己捏造的千萬重身分，習慣於將自我隱藏在謊言之後，直至自身也化為謊言的一部分。 而最初那隻野兔，依然藏身於回憶裡夕陽映照的小小的種植園中。 在冰消雪融的夜裡，悄悄地探出頭來。"
  },
  AwakerStory_148401_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_148994_Content = {
    Text = "縱然身形依舊，但人們一眼就看得出他和自己熟知的那名小小騎士之間的差異。\n原本澄澈的雙眼不再明亮，潔白的衣衫也染了污濁，更不必說他總是刻意地與所有人保持距離。\n但無需恐懼，在那可怖的黑色淤泥之下，仍是那顆你熟悉的、為忠貞正義而跳動的心。\n儘管曾一度遺忘，但他最終撿起了那些騎士的誓詞。\n他將繼續抗爭——與他體內的另一個聲音抗爭，與一切傷害他珍重之物的存在抗爭。"
  },
  AwakerStory_148994_Title = {
    Text = "基礎資料"
  },
  AwakerStory_148994_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_149051_Content = {
    Text = "彌薩格曾發生過一起驚動全校的靈異事件。以下為校園記者漢娜整理的採訪實錄：\n「夜深人靜的時候，圖書館裡有窸窸窣窣的響動……我不敢去看。直到第二天早上，我發現裡面的書全被擺得\n整整齊齊，比我自己整理得還好！」 ——校圖書館管理員\n「不覺得最近校園乾淨了不少嗎？難道晚上有會清理垃圾的幽靈？」\n——某實踐課老師\n「出任務的時候，總感覺後面有人跟著……有時會聽到激烈交鋒的聲音，等我回頭，只剩一地融蝕怪物的殘骸。」——某新手調查員\n幾個膽大的學生為此自發組成了調查小隊，用一晚的睡眠換來了答案。\n一切的始作俑者承認了自己的「罪行」，也誠摯地為引發恐慌一事道了歉。然而面對隨之而來的感謝，他卻顯得有些侷促。用他自己的話說，「只是閒不下來而已。」\n對此，校心理教師茜爾維婭給出了她的診斷：「作為一名本心善良的好孩子，他對過去的事抱有太強的愧疚，久而久之，便成了根深蒂固的不配得感——來自他人太過直白的好意，反而會讓他更難受呢。」\n這一事件輕巧地落了幕，「無形幽靈」的傳說卻由此流傳開來。師生們都心照不宣地不去點明他的身分，只是漸漸地，大家都知道了，這名「幽靈」不過是想幫大家的忙而已。\n大家似乎都明白，對於這位不願被看見的少年來說，最好的謝意，就是讓這個秘密繼續只屬於他一個人。"
  },
  AwakerStory_149051_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_149052_Content = {
    Text = "親愛的讀者們，這是一篇後記，更是我的懺悔書。\n為了完成這部舊式的古典騎士小說，我斥巨資拍得了那頂神秘的頭盔，據說它不屬於任何一個有歷史可查的國度。如您所見，托它的福，我的靈感不斷，彷彿真的看到了一片遼闊宏大的古戰場，身披鎧甲的騎士們正刀兵相向。我依靠這些奇妙的幻覺，完成了這部我心中最完美的作品。\n可我未曾想過，這件古董在賦予我靈感的同時，竟暗藏著一個恐怖的惡魔。\n讀者們，你們可以試著想像一下，有一個聲音，混沌，持續，日夜不息。再想像你的四肢開始不受控，意識也頻頻斷片——不，那不是斷片，更像是意志脫離了軀體，你清楚自己在做什麼，卻只能旁觀......可那明明是我的身體。\n就在昨夜，在我剛剛完成這本小說之際，我再次聽見了祂。\n隨後，該死，我真不願回想起那些畫面——\n我犯下了無法挽回的罪孽，報紙會比這本書更早地告訴你們......\n祂、又在，又開始——\n（字跡歪扭）\n不不不不不不不不，我不能再——\n......\n\n（字跡恢復清晰）\n令人驚訝，祂停了，像是什麼東西壓住了祂，我不知道那是什麼，但我要感謝它的抗爭。\n或許是神明在給予我最後的機會，讓我不至於徹底墮為魔鬼。\n\n我的槍裡已填滿了子彈。\n願上帝寬恕我。\n\n\n——節選自作家克拉克·齊羅斯絕筆作《無影的騎士》後記"
  },
  AwakerStory_149052_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_149064_Content = {
    Text = "象徵罪惡的深黑污泥仍在他的體內翻湧，妄圖再一次掌控這具軀體，他需要不斷緊抓那脆弱的絲線，才不會敗下陣來。\n而他為自己重新找到的——值得捍衛之物，便成為了維繫理智的唯一的錨。\n他再無法回到家鄉，但彌薩格成為了他新的城堡。\n他再無法護衛公主，但命運還會創造新的相遇。\n在無人見證之地，少年單膝跪地，一隻手覆在冰冷的胸口，向並不身處於此的主君宣告。\n「我會謹遵您的指令，永遠守護您與您的世界，哪怕燃盡生命，哪怕透支靈魂。」\n「......這便是，我重新背負起的誓言。」"
  },
  AwakerStory_149064_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_149065_Content = {
    Text = "他也曾像睡前童話裡所寫的那般，踏上過自己的旅途。\n可他並非歌頌正義的騎士，世上亦不再存在等候拯救的公主。\n他殺死的，也不是可怖的邪龍，而是許多哀嚎逃竄的、手無寸鐵的平民。\n「少年騎士斬殺了邪惡的巫師，擊潰了頑固的敵軍，燒毀了怪物的堡壘……\n他很英勇，很強大，戰無不勝。在這條不知盡頭的路上，只留下了一道綿長的血痕。」\n如果世上存在分不清幻夢與真實的吟遊詩人，一定會將這段經歷粉飾成這般模樣。\n可故事的主人公其實是清醒的，那雙眼中從未映出過虛假之物。\n他知道，他的槍尖穿透了老者的胸膛，黑泥吞噬了早已投降的敗兵，那棟精緻的、屬於某戶人家的小屋，也在他經過後化為了灰燼......只因這些皆與奪走他所守護之物的人有關。\n他知道，他從未身處在童話中，那些浪漫的幻想早已隨著故國徹底死去，或許他在那一刻得以長大，或許仍是不成熟的稚子。\n直到他最終幡然醒悟，為了素不相識的陌生人們奉獻生命時，他忽然在自己的淚水中，看見了絕不該存在的幻影。\n「奧吉爾，我對你很失望，你是空有虛銜的，最不稱職的騎士。」\n「公主」的面容彷彿被蒙上了紗，但她的聲音卻異常清晰，遠比世界上任何刀劍更鋒利，剜著他的心。\n這道殘忍的幻覺，時至今日仍是折磨他的夢魘，並未隨著身死而消弭。\n他將永世活在辜負誓言的悔恨之中。"
  },
  AwakerStory_149065_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_60980_Content = {
    Text = "初次見面時哈姆林總會讓你想到某種來自東方的瓷器，潔白、華麗、優雅的弧線，有某種水波一樣貌似溫和的光澤，但又觸之冰冷。\n在那副體面、精緻、一絲不苟的外表下，是極致純粹或者說極致空虛的靈魂。他的一生從頭到尾只有一種念頭，就像是隻輸入了一種指令的機器，喪失了其他所有的反應。\n一切對他來說，不過是如音符一樣的排列組合。\n只有演奏、演奏、永不停歇地演奏。"
  },
  AwakerStory_60980_Title = {
    Text = "基礎資料"
  },
  AwakerStory_60980_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_60981_Content = {
    Text = "哈姆林並不總在學生們面前出現，即使他願意出席彌薩格舉辦的音樂晚會，願意指導水平堪憂的學生們的音樂課，但大多數時間，他都只是一個人在隔音的教室中、或是偏僻的樹林裡獨自演奏，或者說練習。\n除開正式場合，他一直稱呼自己所有的演奏為練習，彷彿那些練習永無止境，完美的鳴奏永遠不會出現。\n「真是一位永葆學徒之心般勤奮又謙虛的大師啊。」早已陶醉於那些音樂的人們這樣誇讚。\n但，哈姆林從來不知謙虛為何物，他向來懶於琢磨那些應酬客套的說辭，不如說他的言辭總是過於直接，過於嚴苛。\n關於音樂他總是患有最嚴重的強迫症，以至於音樂課這種陶冶放鬆的課程已經在學生中登頂壓力最大榜單，哈姆林本人也榮獲魔鬼教師的「美名」。\n如果想要獲得這位冷淡的音樂家的關注，只需要在演奏時彈錯一個半音，那張臉立刻會皺起眉頭轉視而來。\n其實他對他「折磨」過的人沒有任何意見，只不過是把那種堪稱狂熱的追求與標準強加在了他人身上，即便那已經比他對自己寬容太多。\n他就像是在頭頂懸掛了胡蘿蔔的馬駒一樣，為自己懸掛了永遠無法抵達的準線。\n除開為那位優雅的舞者駐足過，他幾乎不會主動與其他喚醒體交流，但面對他人的求助和搭訕，他卻總是展示出出人意料的耐心。\n或許阻攔他的不是冷漠，而是過於單一的知識庫吧。"
  },
  AwakerStory_60981_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_60982_Content = {
    Text = "A.F. 31@1年@1月@2日，一位熱愛音樂收藏的著名富豪被管家發現半夜暴斃於家中的書房，身上沒有一絲傷口或中毒跡象，嘴角甚至還詭異地留有堪稱滿足的笑意。\n經警方勘察認定現場為密室條件，經歷了無數刑偵高手和法醫的檢驗，最終判定死者為意外猝死。\n然而這位正值壯年、身體康健甚至熱愛馬術運動的富豪為何在這樣一個平平無奇的安靜夜晚突然猝死，所有醫生也給不出合理的理由。在其家屬不滿的威脅下，最終警方聯繫了審查會接管調查。\n原本只想息事寧人的審查會，竟然真的誤打誤撞從富豪書桌上散落的樂譜中檢測出了靈知殘留的痕跡。這份詭異的樂譜被送往彌薩格，據研究，這份殘缺的樂譜來自著名的《A小調安魂彌撒曲》遺失的後半篇章，然而樂譜的最後一頁卻依然並不完全，現場發現了許多筆跡狂亂的全新樂譜草稿，似乎是富豪在試圖補全最後一頁。\n在研究中發現，任何沉迷於樂譜的行為都會不同程度地導致癲狂，這份樂譜也很快被封存保管起來。經彌薩格學者推測，或許就是這項補全行為導致了富豪的瘋狂與死亡，並以非常規的方式完成了喚醒儀式。\n之後很長一段時間校方都未搜索到任何這名未知喚醒體現身或傷人的線索，因而此事也逐漸被彌薩格的調查員們淡忘。\n只有音樂領域的學者們始終對那半份被封存的樂譜殘篇念念不忘，一直期待著那傳奇的安魂曲作者的出現。"
  },
  AwakerStory_60982_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_60983_Content = {
    Text = "天賦這種東西似乎只是命運過於稀少的偏愛，以至於他在漫長的青春期中都不曾在周圍的任何人身上得見，那已經成為了某種飄渺的意象，作為父親鞭笞自己前進的符號。\n於是他堅信著只有始終堅持的勤奮才是通往完美的階梯，一直到他站在世界舞台的頂峰，這對他依然是不變的真理。\n直到他遇到了忽然走上前並肩的那個人。\n那是多麼耀眼的一位天才，原來那所謂天賦的禮物早已被一人獨攬。\n從心底叢生的羨慕和一絲嫉妒中，他突然生出一股無言的迷茫和無助。\n那麼我沒有那樣的東西，還能夠到達完美的終點嗎？\n走過的階梯好像忽然化為飛灰，而頭頂的大門依然那樣遙遠。\n他常常徘徊在簇擁著那個人的人群之外，彷彿故作清高地獨處。\n但他每每注視著那個方向，心中總是不停排演開口的問好。\n那些平庸的蚊蠅始終圍繞在那個人身邊，散發惡意的低語。\n他實在是太笨拙的一個人，以至於長久緘默，無從辯解。\n那就用音樂吧，只有音樂是最完美的語言，而那個人一定會聽懂。\n直到命運忽然連本帶利收走了它所賜予的一切。\n天才早逝，庸人長命。\n從前那些人在背後的挑撥離間、蠅營狗苟他都未曾動搖分毫。\n此刻看著滿桌未曾贈出的尚不滿意的樂譜，卻因痛恨自己而流下淚來。\n他忽然明白，在到達完美的天國前，必須用盡人間的手段。\n好在相比那些庸人，他已擁有足夠的頭腦。\n畢竟在他眼中，一切不過是如音符一般的排列計算。"
  },
  AwakerStory_60983_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_60984_Content = {
    Text = "他的生活慣於單調枯燥，孤獨對他而言是生命的常態。\n不甘、迷茫、怨恨早就在漫長的時光裡消化殆盡，現在他早已和音樂融為一體，那是超越了所謂熱愛的本能，無從違抗，不得逃脫。\n他所擁有的全部，也只剩下音樂。\n繼續向上走吧，不要回望那九百九十九層階梯。\n畢竟他已觸碰到那終極的樂聲、那支命中註定的長笛。\n請接納這潮水般不絕的音樂，讓它浸潤你的靈魂、你的夢境。\n正如他也早將靈魂作為樂器，隻為與你嗡然共鳴。"
  },
  AwakerStory_60984_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_66033_Content = {
    Text = "塔薇在彌薩格的現身有且僅有三次。\n第一次，她啟迪「智慧」的火種。她開闢了夢境的通道，將稀世的智慧教授給矇昧中探尋的彌薩格創始人。她提供了彌薩格最初的「智庫」，和關於融蝕的知識與線索。\n第二次，她帶來「變數」的預言。黑池沸騰翻湧，迎接「轉變」世界之人的到來。\n第三次，她傳遞「終末」的訊號。她的痛呼與悲鳴響徹大地，卻無力阻止那避無可避的混沌與毀滅的降臨。"
  },
  AwakerStory_66033_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_66034_Content = {
    Text = "卡達斯並非她嘗試守護的唯一的夢境。\n她親眼見證了許多星球、許多星系的誕生與覆滅，過去與未來的歷史沉澱為知識，收納入她身後的終極之門中。她飽含悲憫的目光俯瞰著那些圖景，化為夢境中的匆匆一瞥，消亡於無垠深淵的黑暗之中。\n她踏上過一片土地，但在她一回眸的瞬間內，她所珍視的一切存在就悉數潰敗於「無上意志」的呼吸。\n一而再再而三的重複後，她終於意識到一個嚴酷的事實，她的存在本身即是噩夢的伏筆，她太過龐大的存在本身足以吸引「無上意志」的目光。她的干涉，只會為她所在意的世界招致更深的厄運。\n所以她退縮，她沉寂。\n直到她在無限空間的浮遊意識碎片中，目睹到一片來自「祂」的，變數的可能性……"
  },
  AwakerStory_66034_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_66035_Content = {
    Text = "在一場神秘的夢境中，我第一次見到她的身影。\n在籠罩著濃霧的、無盡與無窮的空間裡，她看守著連接萬千浩瀚宇宙的巍峨宏偉而不朽大門。在那座深深的大門裂隙後，奇異的幻光閃爍跳動著，彷彿傳遞著某種尚未經過解讀的資訊訊號。在捕捉到某個訊號的瞬間，我彷彿失去了自己的軀體，我茫然無措地漂浮在群星之間，周身都被不可思議的黑暗籠罩。我惶恐，驚懼，夢境洶湧震盪，沉重的門扉緩慢而不可抗拒地開啟，無數類球體如萬千星辰在門扉的背後閃耀，那深不可測的浩渺與不可窺視的圖景令我感到一陣眩暈……而門的守衛者——塔薇只是永恆而無聲地凝視著我。\n——華德·菲力浦斯《銀鑰手記》"
  },
  AwakerStory_66035_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_66036_Content = {
    Text = "身為智之質體的代行者、守門人，塔薇並非未曾探尋過自己本質的欲望。\n她渴望如她守望的人一般行走於大地，見證文明的變遷與歷史的滄桑，將那些目之所及納入名為「全知」的寶庫。但她的存在不容許她擅離職守，所以她內心深處，或許最羡慕的是那名承載了自己一縷意志的少女……"
  },
  AwakerStory_66036_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_66037_Content = {
    Text = "塔薇不存在於當前的世界。\n她的存在將招致「無上意志」的注視，所以她不能存在，不可存在。智慧和沉默，是她所能給予這些孜孜不倦求索者的全部。\n在日復一日的守候中，她平靜地為人類的命運獻上自己的智慧、勇氣和無聲的祝福。"
  },
  AwakerStory_66037_Title = {
    Text = "基礎資料"
  },
  AwakerStory_66037_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_76412_Content = {
    Text = "我不相信羅伯特會吞槍自殺。是的，我不相信。\n\n他獲得過見義勇為獎章，破獲了多起高難度兇殺案，是個心志堅定的資深探員。最重要的是，他很快就要結婚了，女孩和他兩情相悅，所以這裡一定有陰謀！有人謀殺了他並偽裝成了自殺現場！\n\n無論兇手是誰，我都會將他找出來，讓他付出代價。這是我身為弟弟、身為探員必須要做的事情。\n\n……\n\n現場毫無線索，所以我不得不回到了家鄉，這是羅伯特自殺前去過的最後一個地方。經過多方打探，我知道他進入了深山。\n\n至於他進入那裡的原因，我猜測和當地的傳統有關：每家的第一個孩子，在成人禮時都會被父母帶入山脈。\n\n因為父母在我們小時候就搬離了這裡，所以羅伯特並沒有實踐過這個傳統。我想，是即將成家的責任感喚醒了他對傳統的依從。\n\n不管怎麼說，我都要去深山一趟。寫完這些字後，馬上出發。\n\n……\n\n山脈裡鑿出了一個宏偉的建築，我不知道它屬於什麼年代，我看不出來。我只知道這裡一直在不間斷地進行著殘忍的儀式，那些殘肢還有蟲蛹……噦，我無法再寫下去了。\n\n……\n\n這些蟲蛹……不，不，那不是我的祖父母，不是我曾經的長輩……我不可能流著怪物的血脈。啊——\n\n……\n\n……我被那些舉行儀式的怪物發現了，它們要將我也變成怪物！\n\n……\n\n如果看到這篇日記，殺了我，立刻……@2\n\n……\n\n讚美偉大的@2，嘶@2……讚美盲目癡愚@4……嘶嘶嘶……@1嘶……\n\n——節選自已故涉事探員@3的日記，有刪減"
  },
  AwakerStory_76412_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_76413_Content = {
    Text = "「謝謝你，克萊門汀，我感覺好多了。你真是這個世界上最了解我的人。」\n\n出入克萊門汀的心理諮詢室時，守密人經常聽到這樣的聲音。無論那些患者和喚醒體進門前如何，出來時都腳步輕快，笑容滿面。\n\n甚至有一次經過時，守密人看到克萊門汀在給誤入諮詢室的流浪貓做心理諮詢。\n\n結果也顯而易見，所有做過心理諮詢的人都對克萊門汀讚不絕口，這使得克萊門汀的影響力急速擴散，同時，也帶來了麻煩——\n\n「守密人，中午好。」\n\n克萊門汀微笑著出現在你的必經之路上，而你並不吃驚，她不斷響起的通訊器，已經說明了一切。那些對她信賴有加的患者，潛移默化間成為了她的耳目，或直接或間接地幫助她達成一個個目的。\n\n「我想，就算你想要當這座城市的市長，那些接受過諮詢的患者也會無條件幫你達成。」\n\n面對守密人的玩笑，克萊門汀不在意地微笑。\n\n「我對這些不感興趣。」\n\n是的，克萊門汀對這些不感興趣。也幸好她不感興趣。\n\n不然那些在心理諮詢中傾訴出去的幽暗秘密，足以讓這座城市雞犬不寧。\n\n「現在，我只想探究你內心深處的秘密，守密人。」\n"
  },
  AwakerStory_76413_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_76414_Content = {
    Text = "起初，一些微不足道的痛苦，就能讓她滿足。\n\n然後，對於甘美的渴求，讓她在心理引導中加入了越來越多的惡意。\n\n這惡意猶如河流積蓄奔湧，氾濫成災，沒過一個又一個心靈的島嶼。\n\n然而還不夠。遠遠不夠。\n\n唯有那亙古的長夢復甦，整個世界才會化為痛苦的汪洋，帶來終極的喜悅。\n\n所以，她興奮，她祈求，她等待。\n\n當一切化為混沌時，她將伏低頭顱，欣然品味這世間最極致的哀慟。\n\n哪怕這痛苦的汪洋，會將她也溺斃。\n"
  },
  AwakerStory_76414_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_76415_Content = {
    Text = "每個人都有不同的人格面具，而她選擇了最能麻痺人心靈的那一種——\n\n她溫柔地笑著，微笑地說著，每一個表情每一句話都那麼熨帖，讓前來接受心理諮詢的患者，發自內心地認為自己遇到了此生的知己和引路者。\n這樣就足夠了。\n\n註定滅亡的飛蛾不需要知道結局，只需要按照她的引導走下去。\n\n在那看似溫暖的救贖裡，烈火焚身，再無法回頭。\n"
  },
  AwakerStory_76415_Title = {
    Text = "基礎資料"
  },
  AwakerStory_76415_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_76416_Content = {
    Text = "事實上，真正的克萊門汀早在被逝去的偉大意志寄生瞬間就已經死亡。\n\n從那滿是血肉殘骸的祭壇上破繭而出的，是擁有偉大本質、遠超人類生命的新生者。\n\n新的生命，舊的記憶。孕育自此星球的軀體，誕生於宇宙深處的靈魂。\n\n這樣充滿矛盾的存在，令克萊門汀困惑，但很快，來自靈魂的饑餓讓她無法思考。\n\n人類的食物是如此乏味，只有痛苦的記憶稍能入口。而那記憶越是充滿折磨與絕望，品味起來就越是甜蜜和美味。\n\n那一刻，她終於明白了自己的生存方式。\n\n「向我傾訴吧，痛苦也好，絕望也好，通通展示給我。」\n\n她坐在辦公桌後，滿懷惡意地望著前來諮詢的患者，臉上的表情卻滿是溫柔，足以讓任何人卸下心防。\n\n那是昆蟲狩獵時的偽裝與假面。\n"
  },
  AwakerStory_76416_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_81334_Content = {
    Text = "與卡斯托爾相處的感受通常呈現兩種詭異的極端。\n表面上看，那過於正經而穩重的性格十分像是在倫蒂尼恩銀行坐班了二十年的中年職員：一板一眼、不解風情，被枯燥的工作吸乾了所有活力。當他板起臉時，也的確有一種不怒自威的聖子氣質。\n而只要稍微深入接觸，就會發現他那些看似古板的行為通通來自他那過於稀少的常識，和無與倫比的粗神經與耿直，乃至於會把任何人對他說的玩笑都完全當真。\n他時常會拿著一本厚厚的筆記，抓著守密人不停地刨根問底，活像一個仍在牙牙學語的嬰兒，在面對那道過於真摯而誠懇的目光時，大多數人也很難對這些無知的問題說出什麼鄙薄之語。\n除了與各類信仰有關的經文之外，卡斯托爾對任何新鮮的知識都求知若渴，尤其是關於現代社會與現代科學的種種，他甚至對實驗研究產生了濃厚的興趣，在被熔燬·朵爾無情忽視後，轉而又將可憐的溫柯爾糾纏得每日聞風而逃。\n如果坐在學校課堂中，他會是那類深受老師喜愛的勤奮學生，他並不認為學習是一件苦累的事，而是將能夠自由地汲取感興趣的知識當作一種由衷的幸福。\n不過比起教師的欣慰來說，某些喜愛吹噓的喚醒體在面對這樣富有邏輯的無窮追問時，反而會因為答不出後續而惱羞成怒起來，只留下一頭霧水的卡斯托爾感慨學習的深奧艱辛、前路漫漫。"
  },
  AwakerStory_81334_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_81335_Content = {
    Text = "如果誕生於一個普通的家庭，卡斯托爾或許會成長為一個不善言辭，但如樹木般親切又踏實的青年。而現在，他是雙子之中唯一保持了完整的身軀與靈魂之人，他像一塊石頭一樣沉默著，等候著，將那顆少年時兩人共同的火種埋藏在心中，不曾放棄，不曾轉圜。\n那雙已然成熟的、能刮起颶風的雙翼收斂蟄伏，一隻鳥兒靜靜等待著那籠門開啟，再次翱翔於天空的時刻。"
  },
  AwakerStory_81335_Title = {
    Text = "基礎資料"
  },
  AwakerStory_81335_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_81336_Content = {
    Text = "我在距離倫蒂尼恩十分遙遠的、那片因貧瘠而鮮為人知的高原上執行任務時，正巧在一處僅剩下為數不多居民的山村中，發現了這樣一則驚人的事蹟。\n在那個怪物出現的夜晚，天空似乎都被某種怪異的暗影所遮蔽，霧氣滾動在地面，而雲層深處泛起一種黯淡的綠色，那絕不是單純的自然現象，而是一種活著的、呼吸著的生命的投影。\n聳立著高樹的荒蕪山脈深處，突然傳來一陣怒吼、咆哮般的聲波，那不屬於任何生物的嘯叫聲能勾起人們本能最深處的恐懼。\n一道龐大的陰影迅疾地飛過，整座山都隨著那遮天蔽日的陰影一起震顫，所有樹木的枝葉也隨之一起震顫，發出整齊的呢喃般的簌簌聲響。\n「我看見了！那些長長的、密密麻麻的觸手，那雙冒著綠光的眼睛，那絕對就是天上那恐怖影子的源頭。它發現了我，甚至牢牢盯住了我！我真以為我的生命就要終結在那一刻，但或許是它剛剛已經飽餐一頓，在我因窒息而暈過去之前，它便大發慈悲地轉身離開了。」\n這是對正式目擊者僅有的採訪，至今仍深陷噩夢之中的村民拒絕回憶更多的細節。但從已有的跡象觀察，這個龐大的暗綠色怪物除了如颶風過境一般摧毀了部分山林、留下幾具僅餘血絲的野獸骸骨外，並沒有表現出更大的攻擊性，就像一頭正常進食的猛獸一般。或許它靠近村落的行為，僅僅是來自於某種好奇的窺視。\n但面對任何未知的恐怖，我們顯然需要予以最壞的設想，我將繼續在@3高原進行為期半個月的調查，如果有其他值得注意的危險跡象，我會隨時補充於任務匯報之中。\n\n——節選自《彌薩格境外調查筆記A.F.3@2年總錄》"
  },
  AwakerStory_81336_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_81337_Content = {
    Text = "追尋自由、逃離教會的代價是什麼？雙子預想過恐怖的刑罰、甚至預想過會失去自己的生命，但他們沒想到的是，最令人痛苦的從來不是肉體上的折磨，而是針對靈魂的剮刑。\n卡斯托爾目眥欲裂地看著波呂克斯那對他倍加珍惜的、靈動而華美的翅膀被生生扯下時，嘴唇已被自己的牙齒生生咬爛，他發狂而愧疚地等待著，甚至渴望著同樣的痛苦降臨在自己身上。\n然而於麗埃特只是揮了揮手，如殘破布袋一樣重傷的卡斯托爾就這樣完整地被帶了下去，扔進了充滿融蝕漿的水池中施行「罪孽療法」。\n黑色的黏漿浸泡著受傷的軀體，滲入每一處傷口，覆蓋每一片羽毛，令卡斯托爾愈加難以呼吸。\n於傷口反復地腐蝕又痊癒中，卡斯托爾恍惚的腦海里盤旋著那雙被拔掉的翅膀，他在狹小的囚籠中焦躁地枯坐，恨不得替弟弟承受所有的折磨。他多麼想當日被拔掉翅膀的人是自己，後來他又堅定地想，自己一定要靠這雙翅膀帶弟弟再次飛向自由。\n卡斯托爾在這地獄般的潭水中支撐了一日又一日，痛苦之中時間已無法被準確感知。像是等待了數十年那樣久，等到卡斯托爾幾乎死上一次，從那漆黑的地獄中再次爬出時，與他急切的雙眼相對的，是一道冰冷而不屑的目光。\n「收起你那噁心的眼神，另外奉勸你一句，卡斯托爾閣下，你我不過是共同侍奉持燈者的聖子，人後無事之時，就不必太過親昵了，令人徒增厭煩。」\n卡斯托爾不知道為什麼弟弟將自己完全忘記了，但他終於明白了離開罪潭時，於麗埃特那樣意味深長的眼神究竟是什麼含義——只因她已將最能夠控制自己的項圈牢牢牽在了手中，有恃無恐。"
  },
  AwakerStory_81337_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_81338_Content = {
    Text = "雙子生來便除了彼此一無所有，而卡斯托爾仍然一直在品嘗著失去的滋味。\n被傷害、被遺忘、被背叛，那顆沉默的心並非鐵石，但他仍然不斷地爬起。\n「但沒關係，我會將你的那一份一起堅持下去。」卡斯托爾看著面目全非的弟弟，盲目地相信著。\n他的心中緊緊攥著那朵微弱的火苗，不停逆著刀割般的風雪跋涉。\n總有一天，他要攀登上那自由的山頂，要用翅膀去觸碰天空低垂的帷幕。\n他相信那條荊棘之路的盡頭，一定是兒時弟弟許諾過的，明亮的天光。"
  },
  AwakerStory_81338_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_81615_Content = {
    Text = "她是船隻航行時高高飄揚，指引方向的旗幟，也是船隻沉沒時，堅守職責到最後一刻的挽歌。\n\n她的責任、她的義務、她的生命都與船隻綁定，除此之外，別無他物。\n\n因為，指引航向，就是她存在的意義。\n"
  },
  AwakerStory_81615_Title = {
    Text = "基礎資料"
  },
  AwakerStory_81615_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_81616_Content = {
    Text = "在學會說話前，在遊輪上長大的克珀珊特就已經能夠模擬海浪拍擊船隻的音節。\n\n有時候那音節是「嘩啦」，有時候那音節是「轟隆」，猶如大自然為她唱響的安眠曲，令她覺得安心，令她覺得親切，令她覺得嚮往。\n\n她總是能比其他人更快領悟大海的「脾氣」，總是能比其他人更快讀懂雲層的「語言」，所有人都說她是天生的「領航員」。\n\n實際上，在第一次聽到這詞彙時，年幼的克珀珊特還無法理解，她只是本能地想要幫助收留自己的船長和水手們，想讓他們安全回家，而非折損於風暴或是其他船上的災難。\n\n了解她心願的領航員於是說道：「成為領航員吧，克珀珊特，成為領航員，履行你的職責，那麼你的心願就會實現。」\n\n懵懂的克珀珊特點了點頭，就此，那位領航員成為了她的導師。他教導她如何觀測星空、如何校準六分儀，並告訴她領航員們代代相傳的歌謠，那不祥的歌謠。\n\n「我不想被鹹水擁入懷裡，那太冷了，也不想化為什麼磷火。」年幼的克珀珊特提出異議。\n\n她的導師並沒有教導她什麼，只是摸著她的頭，笑了笑。\n\n因為時間，會教導她明白「領航員」職責的意義——\n\n她是幽邃大海上，唯一的指引，唯一的希望。\n"
  },
  AwakerStory_81616_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_81617_Content = {
    Text = "沒有人知道那艘幽靈船在哪，也沒有人能確定「它」是否真的存在。目前我所掌握的唯一線索，就是那個似乎有著某種詭異魔力的象牙頭雕。\n\n自從得到它後，我每天都在做同一個夢，是的，就是那艘不知道在哪的幽靈船。「它」的船身燃著如活物般蠕動的輝光，似乎通往凡人不可知維度的門扉，醒來後，我依然記得那些褻瀆病態的低喃。\n\n我多麼希望自己瘋了，或是忘掉這些古怪的、人類根本無法發出的音節，但不行。\n\n那該死的夢境、那該死的知性輝光折磨著我，因此我必須去找「它」，在象牙頭雕的指引下。幸運的是，密斯卡託尼克的教授們會與我同行，共同探索幽靈船及聖艾爾摩之火——他們是這麼稱呼那蠕動輝光的。\n\n祝我幸運。願主保佑我們。\n\n——節選自《密斯卡託尼克超自然現象調查檔案》"
  },
  AwakerStory_81617_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_81618_Content = {
    Text = "克珀珊特的每日行程十分固定，你只需要在特定的時間，去到特定的地點，就能找到她。\n\n一般而言，克珀珊特6：00就會起床，進行冷水浴與體操。7：00是早餐時間，除燕麥粥、醃魚外還需提供大量咖啡因補劑。\n\n9：00-12：00，是克珀珊特的進修時間，她會在此期間修訂海圖或校準儀器。當下課鈴響起時，克珀珊特會來到戶外，揮舞旗幟充當交通員，這極大緩解了午飯時學院道路擁堵的問題。\n\n克珀珊特的午餐時間取決於「路況」，但最晚不會遲於12：30。短暫休息後，14：00時，克珀珊特會準時出現在海邊，觀察風向與氣候。此時需要注意克珀珊特、法洛思、希萊斯特三人的動向，避免她們「徵用」博物館模型船隻，或引誘路人出海。\n\n19：00為晚餐時間，為了麻痺徹底被長期航行摧毀的睡眠週期，克珀珊特需要攝入大量酒精及助眠酊劑，唯有如此，她才能在22：00成功入睡，否則克珀珊特會強制讓自己保持清醒，以應對航行中可能出現的「意外」。\n\n因此導致的情況包括且不限於聖艾爾摩之火現象失控，導致整個區域亮如白晝，或區域電壓異常、失控，機器運轉異常、失火等。\n\n<Red:注意，在此期間絕對不要讓艾瑞卡與克珀珊特進行接觸！>\n\n最後通知批評一則：\n\n克珀珊特到來後，溫柯爾嘗試多次提取、研究克珀珊特胸口的@2，作為光源。已進行口頭批評，如有人發現異常，請務必及時告知守密人。\n\n——守密人%player%"
  },
  AwakerStory_81618_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_81619_Content = {
    Text = "直到最後一刻，克珀珊特都在努力履行自己的職責，但她領航的船隻，仍舊沉沒了。\n\n每到夜深人靜時，她就會夢到那些逝去的乘客：海水灌入船艙，海怪觸腕橫行，有人淹死，有人跳海，有人跪下來祈求最後的指引，卻仍是希望破滅。\n\n這殘酷的現實在責備著她，折磨著她——她褻瀆了自己的職業。\n\n為此，她必須受到懲罰，那終生纏繞她、摧殘她的雷電，就是懲戒。但還不夠，她必須為自己的瀆職贖罪。\n\n幸運的是，那偉大的存在給予了答案：只要神國降臨，世間一切都將變為樂土。\n\n「那麼，為了平息大海永恆無盡的咆哮，為了那些葬於大海的無辜者，為了指引眾生的方向，我請求神國的降臨。」\n\n這是她最後的，最終的領航。\n"
  },
  AwakerStory_81619_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_95006_Content = {
    Text = "■檔案編號：DIOL-A3-27\n■喚醒體代號：■■■■\n\n根據該喚醒體（下文稱為凱蒂古拉）的行為習慣、處事風格及對不同任務的態度，調查人員進行了相關推測，並在之後詳細展開了調查，現在同步以下內容：\n凱蒂古拉是一名@2地區的孤兒，其父母於其幼年時期便將其拋棄。\n凱蒂古拉依靠未知的手段在該地區存活了下來，同時收留了許多境遇悲慘的孩童。需要注意的是，該過程中充斥著大量血腥、暴力的手段。在明確記錄中，調查對象曾殘忍地殺害了某位收留對象的所有家庭成員。\n在後續的很長時間內，凱蒂古拉及其手下的主要經濟來源是承接不可告人的委託，如黑幫仇殺、幫派火拼、劫掠髒物等黑吃黑行為。\n據當地人的口述，同時結合該地區的一些數據，初步推斷出存在某個時間點，以凱蒂古拉和其收留的孩童為核心的團體，成功整合了該區域絕大部分黑色組織。\n目前暫時無法得知凱蒂古拉是如何成為喚醒體的，但該地區提燈教會據點遭受摧毀的時間，與其成為喚醒體的推測時間相符。根據其對提燈教會的厭惡感，合理推斷其成為喚醒體與提燈教會有所關聯。\n據不完全統計，截至目前，已有43個提燈教會的據點遭到其摧毀，其中包括7個大型據點，12個降神祭壇以及17個實驗場所。\n\n參考上述調查報告及該喚醒體的日常活動行為，委員會在榮譽主席K·特拉克的提議下，對凱蒂古拉的危害評級進行重新評估，現記錄評估結果：\n經全體委員判斷，該喚醒體對彌薩格不存在直接或間接的威脅，在現有合作條約不變的情況下，無需對其存在及行為進行干涉。\n因此，現決定將凱蒂古拉移出DIOL，同時凍結與其相關的一切調查行動，所有檔案內容進行完全封存，禁止任何Ω級別以下的人員進行查看。\n\n記錄員 K·特拉克\n（寫在檔案底部的小字）\n可喜可賀！終於讓那幫草木皆兵的小子把這該死的項目取消了，不枉我浪費這麼長時間推動這些事。\n這就是有關凱蒂古拉女士的最後記錄了，後續不出意外，不會有新的檔案填充進這個編號下了。所以無論是誰，現在可以合上這該死的文件夾，出門呼吸一下新鮮的空氣，將精力放在更值得關注的對象上了！\n——卡拉波利斯·特拉克，你那變成社會閒散人員的好朋友。"
  },
  AwakerStory_95006_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_95007_Content = {
    Text = "■檔案編號：DIOL-A3-1\n■喚醒體代號：■■■■\nA.F.3@2年，該喚醒體主動與彌薩格進行接觸。\n\n「太陽！太陽！我看到了太陽！不！不！！摧毀它！不然我們都要死！」\n\n據目擊者描述，當事人員在發現該喚醒體後，大喊著說出了上述發言，之後命令相關部隊對其進行攻擊。\n\n由於當事人員的錯誤判斷，該喚醒體展示出了極強的攻擊性，直接導致31組反喚醒體器材，76組常規裝備，2棟教學樓遭到摧毀，合計財產損失@2@4，當前已移交至相關部門進行對應追責。\n\n經事後調查發現，該人員已被提燈教會洗腦，後續情況請移至相關文件查看，不在本檔案進行敘述。\n\n在一段時間的交流後，談判人員成功令該喚醒體解除了攻擊姿態，隨後該喚醒體將一封署名為德克斯特勳爵的信件交予校方，聲稱是某位失蹤調查員的遺物，後續經德克斯特勳爵確認，該信件確實為其所寫。\n\n目前已知經朵爾教授的協商，該喚醒體與校方達成了某種協議，校方以某種尚不明確的報酬為代價，換取該喚醒體承接某些校方不好或不便處理的委託。\n\n出於對該喚醒體所展現的破壞力的考量，儘管該喚醒體在之後的談話中具有最高等級的穩定性及可交流性，委員會依舊決定將其列入DIOL中，並將以最高規格持續進行檔案更新。\n\n願銀鑰指引我們。\n\n記錄員 L·納迪亞"
  },
  AwakerStory_95007_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_95008_Content = {
    Text = "（寫在檔案開頭的小字）\n該死，你是怎麼找到這份檔案的，我明明已經禁止了任何人查閱這東西……算了，既然您能看到這份檔案，說明您的權限遠在我之上，這代表您是那幾位之一，我自然無權阻止您知曉這些事情。\n\n但是請您牢記，這份檔案理應不該存在於任何地方，下述內容也並非任何正式調查，而是個人基於某些現實情況，進行二次推論構成的非官方產物。\n\n我必須鄭重地提醒您，這份檔案的記錄過程中包含大量無法詳細描述的調查方法、個人思維的主觀臆斷以及收受調查對象賄賂的行為。如果您不在意我的上述行為，請繼續往下閱讀，我以我的人格擔保，下述內容具有明確的真實性。\n\n■檔案編號：■■■■-A■■-SSS\n■喚醒體代號：爆燃之主\n「我其實並不喜歡爭鬥。」\n我很意外會得到這樣一個答案，畢竟所有報告中，調查人員都會在描述她戰鬥時，加入諸如「瘋狂」「歡悅」「興奮」等字眼。\n我本以為她對於戰鬥的看法是「不主動，不厭惡，不拒絕」，萬萬沒想到她會對這種事情本身感到厭惡。\n隨著談話的繼續深入，我漸漸明白了一些事情，當我詢問是否能記下這些內容時，凱蒂古拉大方地肯許了我的行為。\n\n「你要知道，對於世界上的大部分人來說，活著就是一種奢侈。」\n我對這個說法表示認同，雖然我以及接觸到的大部分人都過著優越的生活，我甚至可以隨時前往倫蒂尼恩最大的歌劇院欣賞表演，但我清楚地知曉這個世界的真實樣貌，以及我優越的生活背後有多少人在負重前行。\n\n「因此，在許多時候，強烈的鬥爭欲是你為了活下去所支付的報酬。」\n「我們沒有辦法選擇生活的方式，你一旦踏入過泥濘，再想抽身就幾乎不可能了。」\n我本想反駁這個觀點，但當我仔細回想了幾個案例後，發現他們都可謂不是一般人，而那些無名小卒，大多數只會存在於他們的回憶錄裡。\n「或許有些天真的人會說既然這樣，那一開始就不要去做不就好了麼？這種想法很好，我曾經把它刻在了某個墳墓上，來紀念一位貫徹落實了這條準則的人。」\n「為了在這個殘忍的世界中保護大家，我必須展現得足夠強大，瘋狂，這樣才能讓那些無處不在的惡意有所忌憚。」\n「當然，我在戰鬥中表現得那些情緒並非虛假，我確實在享受戰鬥帶給我的感覺。」\n「可能有些難以理解，但這就像你可能會喜歡你的工作內容，卻不會喜歡工作本身一樣。」\n聽到這個解釋之後，我立刻理解了她話中之意。確實，我很喜歡在工作中窺探別人的隱私來滿足我那罪惡的好奇心，但這不代表我喜歡每天早上八點必須從床上爬起來，聽從命令前往某個地方待上一整天。\n\n「在我剛被遺棄的時候，我跟很多女孩一樣，迷茫，躊躇，不知所措。」\n「我希望得到他人的幫助，但世界給予我的，只有數之不盡的背叛和傷痛。」\n「漸漸地，我開始用殘忍和瘋狂構造抵禦惡意的盔甲，飲鴆止渴般適應著世界的一切。」\n「直到最後，它們在永不停息的火焰中融化，與我的血肉合為一體。」\n像是為了印證剛才的發言一樣，凱蒂古拉瞬間露出一個極度殘忍、邪惡、瘋狂的笑容，嚇得我將杯中淡黃色的液體撒在了身上。\n哦，或許這是好事，因為這樣可以避免萬一我真的控制不住肌肉導致漏出了某些液體，可以很自然地解釋成是剛才灑在身上的飲料。\n在離開的最後，凱蒂古拉都沒有正面回答我的問題，但我想，我之前的判斷是正確的，她確實不該存在於DIOL中。\n——記錄員 卡拉波利斯·特拉克\n\n「我最初的願望，只是想擁有一個家。」\n「一個沒有背叛，沒有痛苦，充滿歡聲笑語的家。」\n「可惜，直到那一天我才明白。」\n「這是這個殘酷的世界中，最奢侈的妄想。」\n——凱蒂古拉"
  },
  AwakerStory_95008_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_95009_Content = {
    Text = "凱蒂古拉擅長用她標誌性的笑容，令所有注視者從意識的最深處，滲出那股透著殘忍、瘋狂的寒意。\n那兩杆形影不離的雙槍，則用繚繞在槍管的火藥塵粉，警示所有妄念癡心的宵小之徒，無名者的犧牲是一切偉大的基石。\n不過但凡跟她打過交道，你就會明白，狩獵這些平凡的不被陽光照耀的人，不過是她日常無聊時的消遣。\n畢竟當她真正開火的時候，槍口是沒有火藥的。"
  },
  AwakerStory_95009_Title = {
    Text = "基礎資料"
  },
  AwakerStory_95009_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_95010_Content = {
    Text = "■檔案編號：DIOL-A3-9\n■喚醒體代號：■■■■\n\n根據持續的觀察發現，該喚醒體並未對彌薩格表現出異常關注，甚至可以說興趣缺缺，她只有在接受委託時會來到校內，然後快速地離去。\n雖然回傳的調查報告顯示，該喚醒體確實存在數次長時間於校園內逗留的記錄。 \n\n但根據後續調查，其主要逗留原因是幫助學生解決一些問題，經判斷不存在安全隱患，無需進行干涉。\n\n需要注意的一點是，該喚醒體似乎對守密人擁有遠超他人的興趣，曾多次給守密人帶來被列為違禁品的@3物件，並邀請守密人參加各種與會人員不明的晚宴。考慮到守密人對彌薩格的重要程度，如果該喚醒體企圖對守密人採取某種具有危險性的行動，需安排至少4名γ級武裝人員，來確保守密人可以安全撤離。\n\n記錄人 K·特拉克\n\n（寫在檔案背面的小字）\n嘿，兄弟，當然也可能是姐妹，這不重要。\n上一個倒霉蛋已經撂擔子不幹了，現在是我來負責這個該死的項目。\n如果你看到這個，說明你不是那種只會混吃等死的傢伙，而是一個善於觀察的人，你應該為你自己鼓個掌。\n聽著，雖然我們一直說我們在「暗中監控」，但我感覺她早就發現我們了，只是不願意搭理罷了。\n我不明白為什麼我們要監控這樣一個人，雖然跟她的第一次接觸存在些許誤會，但那本就是邪教徒所致，跟她本人不存在任何關係。\n況且她跟那些學生，尤其是守密人之間，用比喻形容的話，就是祖母給孩子買糖果的關係！總不能有人天天覺得自己祖母要把他獻祭給邪教徒吧……不，等等，或許在某個地方還真的是這樣，不過這不重要！\n重要的是，如果她真的有所圖謀，我保證，事情已經在不知不覺中發生了，而不是等到委員會慢慢悠悠地研究出來那個******對策。\n呼，罵的好爽，總之，我已經計劃將她從這個名單中移出去，在委員會真的做出什麼對她而言不可原諒的事之前。\n一旦那幫**真的把她惹毛了，我保證，就不會是2棟樓那麼簡單了，希望到時候我已經死了，不然我應該會死得非常痛苦。\n如果你是即將監視她的人，記住，不要做什麼過激的舉動，如果你不喜歡她，就將她當做給學校處理髒活的傭兵就行了，除非對方明確表現出了不穩定狀態，否則絕對不要跟她起正面衝突！\n當然如果你想要點小禮品……她應該也不會在意你曾經監視過她，大膽去要就行了，說實話，她口袋裡的小零食真的蠻好吃的。\n——卡拉波利斯·特拉克，你一起辱罵委員會的好朋友。"
  },
  AwakerStory_95010_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_95094_Content = {
    Text = "他的一生都活在被操縱的絲線下，那早早寫好的劇本是一場可笑的謊言，令他不停失去、遺忘、錯過。\n在年少時他最渴望的是能夠自由地揮舞翅膀，飛到那片湖水之外的世界去看看。\n直到他為這個願望失去了一切後，他已無法將那樣輕盈的、無憂無慮的生活當做全部的夢想。\n無盡的怒火將那顆漆黑的心臟點燃，他鬱結成血的痛苦與仇恨，要用那些偽信者的死亡才能洗刷償還。"
  },
  AwakerStory_95094_UnlockDesc = {
    Text = "同調率等級達到9"
  },
  AwakerStory_95095_Content = {
    Text = "基於對波呂克斯那顆「聖心」與提燈教會的降神儀式之間可能存在的關係的考量，彌薩格曾組建了研究小組對「聖心」進行了一系列檢查與實驗。\n令波呂克斯遺憾的是，這顆「聖心」已經完全替代了他原本心臟的機能，融入了他的身體之中，無法直接摘除或替換。\n在觀察實驗中，研究人員發現這顆外形酷似眼瞳的「聖心」時常會產生非波呂克斯意志下的輕微抖動與轉動，如同一隻真正的眼睛。\n但經過光源測試後，證明「聖心」不存在類似視力的功能，這種活動更像是源於對其他生物或物品的感應。\n在不同放置物品的對照中，與融蝕、銀芯相關物品的靠近更容易引起「聖心」的活動，在被融蝕生物與喚醒體面前，「聖心」的活動則尤為明顯。\n在波呂克斯主動使用「聖心」的力量後，普通物品的物理及化學性質不會有任何改變，而在融蝕物品、生物面前，則出現了速度驚人的融蝕擴大現象。原本位於融蝕階段早期的動植物肉眼可見地加速度過了發展階段，快速轉向融蝕末期的狀態。當動植物原本受到的融蝕越嚴重，這樣的擴散則越迅速。\n在建立了嚴格保護措施的喚醒體實驗中，當面對「聖心」的力量時，喚醒體表示感受到有某種黑暗逼近的危險氣息，實驗因而被迅速叫停。波呂克斯也在校方的嚴正說明下，保證不會將聖心的力量對喚醒體使用。\n由於波呂克斯極其配合的態度和良好的自控力，彌薩格並未給波呂克斯佩戴強制管制道具，只是定期給波呂克斯安排了體檢與力量使用訓練。\n據說在聽聞了實驗結果後，喚醒體溫柯爾曾尖叫著險些暈倒，並在自己的實驗室和宿舍門上張貼了禁止波呂克斯靠近的告示，校方屢次勸說無果，波呂克斯本人對此則大度地表示會尊重溫柯爾的要求。"
  },
  AwakerStory_95095_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_95096_Content = {
    Text = "在命運之神最初的設想裡，他大概不應誕生於世。\n一開始從人造雙子實驗中誕生的只有卡斯托爾一人，就在這團無知無覺的胚胎要被處理丟棄時，波呂克斯掙扎著，從哥哥的血肉中扭曲撕裂而生。他吸食了他的生命，也拯救了他的生命，他們的血肉、靈魂與命運就此交纏。\n於枯燥的教會修行之中，兩人的生活與命運原本別無二致，直到「神聖改造」儀式的開始，痛苦且無情的折磨讓波呂克斯從聖子的宿命中驚醒。兩個孩子做出了一生中最大膽的壯舉，他們拿著一本過時的書籍描摹出了一幅世界的地圖，然後從一個虛假的世界中逃向了另一個幻想中的世界。\n脆弱而短暫的美夢破碎後，殘酷的懲罰未曾擊垮他們的靈魂，但那宿命的殘酷分叉已經將他們就此分隔了。\n於麗埃特下令將兩人分開供養，罪潭中的卡斯托爾不知道的是，兩人想像中的酷刑並沒有實施在波呂克斯身上，於麗埃特幾近仁慈地結束了剩餘的懲罰，甚至很快將波呂克斯從禁閉的暗室中放出，轉而投入了密集嚴苛的神學教導。\n波呂克斯滿腹的不屈與疑惑在面對於麗埃特絕對從容的目光時，變成了某種不安與恐懼，她一定是掌握了某種他無力反抗的辦法，才會如此好整以暇。\n他掙扎、偽裝、從未放棄。他好像做了許多事……但他做了什麼呢？鏡子中只剩下一個陌生的靈魂，忠誠地戴上了那頂聖子的冠冕。\n他與他們的記憶，已經被徹底遺忘了。"
  },
  AwakerStory_95096_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_95097_Content = {
    Text = "他是畸生而出的血肉，由剖開又縫補的肌膚、空洞的胸腔、污濁的心臟與無形的鎖鏈構成。\n他被捧上高臺，人們膜拜在他的腳下，聲稱他擁有無垢的靈魂。\n他究竟是什麼？他在無數夢中茫然發問，那暗綠的湖水與空無一物的濃霧中，只有他的聲音孤獨迴響。"
  },
  AwakerStory_95097_Title = {
    Text = "基礎資料"
  },
  AwakerStory_95097_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_95098_Content = {
    Text = "比起卡斯托爾那樣積極好學的態度，波呂克斯接觸外界的風格則更加謹慎。\n觀察、思考、懷疑，足夠的思慮與小心讓曾經的他能夠在教會的重重控制下，帶著卡斯托爾成功出逃。\n從兒時起，他便學會了揣度他人的想法，學會了撒謊，學會了用笑容遮掩真實的想法。哪怕是在親密無間的哥哥面前，他仍會下意識地用輕鬆的笑容去安撫對方。\n「沒關係的。」\n「一定可以的。」\n在那樣龐然大物的手掌之下，弱小者需要拼盡全力才能尋到一絲可能的希望。\n經歷了漫長的遺忘與欺騙後，如今的他更加不允許任何危險與失誤的存在。哪怕聽從泰旖絲的建議來到彌薩格後，在很長的一段時間裡，他都保持了相當的警惕。\n在其他喚醒體看來，波呂克斯是一個話不多，卻很有耐心，常常會對人露出微笑的友善傢伙。但那些久經世故的年長者看到他後，則都紛紛感歎兩兄弟之間的不同。\n據泰旖絲說，哪怕是在她的面前，波呂克斯也會有意無意地將卡斯托爾擋在身後——從他找回記憶以來，他已經不再願意讓卡斯托爾總是保護著他。\n詹金也曾煞有介事地向守密人告狀波呂克斯的表裡不一，聲稱自己不小心撿到卡斯托爾的東西時，曾看到波呂克斯驟然陰沉的面孔。「那個傢伙平時的好脾氣肯定都是裝的！他私下裡就是那種會吃小孩的變態！」\n然而在直面了守密人的力量後，波呂克斯對待守密人的態度就發生了一百八十度的轉變，在「聖心」的劇烈反應下，他聲稱已從那偉大的靈魂中獲悉了世界的真相，並畢恭畢敬地將守密人奉為了新的信仰。"
  },
  AwakerStory_95098_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_96418_Content = {
    Text = "葬骸城的奠基者，食屍鬼永恆的王。\n他的宴會值得最深切的期待——華麗的餐廳，優雅的舞步，還有那些他親手用屍骸製成的雅緻餐品，一定會令你永生難忘。"
  },
  AwakerStory_96418_Title = {
    Text = "基礎資料"
  },
  AwakerStory_96418_UnlockDesc = {
    Text = "喚醒體等級達到1級"
  },
  AwakerStory_96419_Content = {
    Text = "離開葬骸城之後，杜勒賽因在人類社會中表現出了極強的適應性。這是一種必然，人類社會對他來說不是新的開始，而是一種回歸。\n談吐，舉止，氣度，禮儀……杜勒賽因的一切都無可挑剔，既保留著一名君主應有的氣場，又絲毫沒有長期身居高位的傲慢。\n杜勒賽因並不排斥社交，但他對政治、經濟、學術之類的話題興致缺缺，吸引他去到這些場合的理由只有一個——美食。\n除了品鑑之外，杜勒賽因也熱衷於參與廚房相關的工作。從食材的選擇到處理手法，從香料的使用到火候控制，杜勒賽因在美食方面的淵博知識與優秀品味征服了每一個與之交談的人，他們發現，在這之前自己數十年的用餐都只是在囫圇求生，與一個為生存而進食的動物沒有任何區別。即便是天生沒有味覺的可憐蟲，也能在他的描述裡體驗到美食的藝術，獲得味覺上的新生。\n這當然和杜勒賽因的禮節有關，他清楚地知道人類與食屍鬼在食物品味上的差別。杜勒賽因尊重不同物種之間的差別，無意將自己的品味強加於所有人。\n「總有人喜歡將不同視為異端，在我的城邦裡，這是非常不優雅的行為。我尊重人與人之間的差異。在這種差異中，我們才能看到更多關於食物之美的可能性。」\n「但你不同，守密人。作為這個世上如此特殊的存在……我想，你一定能像我一樣，在這樣的進食裡，體驗到無與倫比的美……」\n說這句話的時候，杜勒賽因的微笑在紫色的霧氣中閃爍，像是一條優雅的毒蛇在你耳邊嘶語，等待著將你帶出、或者誘入伊甸園的那一天。"
  },
  AwakerStory_96419_UnlockDesc = {
    Text = "同調率等級達到5"
  },
  AwakerStory_96420_Content = {
    Text = "從葬骸城黑暗的祭祀神殿中醒來時，劇烈的疼痛正席捲杜勒賽因全身。\n劇毒的效果尚未消退，刀絞般的疼痛如同一株帶刺的藤蔓，從他的腹部開始生長，佔滿身體的每一個角落。他曾想過父親會毒害自己，但他依然接過了父親遞來的那杯酒。\n聰慧，正直，英勇……在很早以前，杜勒賽因就具備了作為一位賢王的所有美德。從那個蒼老的、閃爍的眼神裡，他輕易便洞穿了父親與他身後勢力的想法，但他依然微笑著接過了父親遞來的毒酒，一飲而盡。\n在一個人類的城邦裡，食屍是一樁不可饒恕的惡行。杜勒賽因曾經無數次嘗試過向他們解釋，解釋屍體的味道，解釋死靈的美。人與人之間永遠無法相互理解，即便是至親也一樣，這是杜勒賽因學到的最後一件事。\n他沒有想過自己會重新醒來。在劇毒之外，他感到另一種疼痛。黑色的霧氣覆蓋在他的身上，如同無數個食肉的爬蟲，正啃噬他的軀體。一顆顆利齒刺破他的肌膚，一把把利刃剜去他的血肉。黑霧正在撕咬他。黑霧正在重塑他。他的軀體不斷重生，又不斷被啃噬。杜勒賽因張開嘴，在這空無一人的神殿中無聲哀嚎。\n在那漫長的、極致的痛苦中，黑霧竄入杜勒賽因體內，與他的精神交融。當黑霧與他的精神世界連通的那一刻，杜勒賽因的味蕾中出現了一絲他從未品嚐過的味道。劇毒，凌遲……所有的痛苦在那一刻消失，他的世界只剩下那一絲無上的美味。他興奮地追尋著它，找到了它的來源——那是葬骸城的神明正在品嚐的味道。那是他自己屍體的味道。\n在這可怖的折磨中，葬骸城的神明正與他融為一體。他們的肉體與精神相連，他們在彼此的痛苦與歡愉裡哀嚎、歡笑。\n這場進食持續了一整個星期。在這場漫長的進食結束後，杜勒賽因重新從祭壇上升起。沒有仇恨，更沒有懊悔。他理解並感激那些殺害他的人們，在這場謀殺裡，他品嚐到了此生最極致的美味，獲得了此生最極致的歡愉。\n滿月升起，葬骸城在那一天安靜垂首，迎接它愉悅的新王。"
  },
  AwakerStory_96420_UnlockDesc = {
    Text = "同調率等級達到7"
  },
  AwakerStory_96421_Content = {
    Text = "倫敦郡西北部的艾瑟靈頓廢棄墓園自A.F.3@2年起便被本地居民列為絕對禁區。根據《泰晤士報》存檔報導及蘇格蘭場失蹤人口卷宗顯示，近年來已有37人在墓園夜間的濃霧中失蹤，其中包括：盜掘貴族墳墓的慣犯西里爾、避寒的流浪漢庫克、巡邏時誤入的警員格雷森、研究中世紀喪葬文化的牛津學者懷特等等。目擊者證詞均指出，所有失蹤者都在霧濃度達3級時進入墓園，最終在霧中失去蹤跡，搜救隊從未發現任何遺留物。\n密斯底亞協定審查會在A.F.3@2年前始終將該區域列為低優先級觀察對象，但隨著德文郡公爵塞繆爾·寇松（以資助超自然研究聞名）的失蹤，審查會收到來自王室的直接質詢，最終針對墓園啟動專項行動。\nA.F.3@2年7月，由審查會第七行動組組長伊萊亞斯·索恩帶隊，配備12名武裝探員及3名靈媒，攜帶抗失溫藥劑與方向定位儀等銀芯設備進入墓園。團隊在濃霧中維持隊形行進1.2公里後，於墓園西北角的殘破食屍鬼雕像下發現隱蔽的六邊形入口。\n索恩團隊沿階梯下行，經超過五千級階梯，抵達地底神殿正廳時，現場情況與預設的「屍骸堆積」的形象完全不符。\n神殿實測面積約800平方米，地面平整度誤差不超過3毫米，空氣中未檢測到任何塵埃顆粒。空間內無任何裝飾性結構，僅中央矗立一座高2.3米的花崗岩祭壇，祭壇表面雕刻著連續的荊棘花紋。祭壇周圍縈繞著穩定濃度的黑霧，黑霧核心處可見人形輪廓。\n祭壇頂部的塞繆爾·寇松公爵呈跪姿，衣物完整但已失去生命體徵，屍檢顯示無外傷。在索恩團隊突破黑霧外圍屏障時，公爵屍體在黑霧中分解為分子級微粒，質譜儀未捕捉到任何殘留信號。\n在分解完公爵的身體後，黑霧突然擴張並覆蓋整個調查團隊。根據成員事後陳述，全員在失去意識前，均曾清晰地聽到一句來自男性的、優雅、溫和、如同耳語般的話，內容為：\n「請不要探尋葬骸城。請不要打擾食屍鬼之王的用餐。」\n「這是最後一次敬告。」\n當團隊恢復意識時，已位於墓園正門的鏽鐵柵欄外，所有設備均正常運作，但記錄神殿內部的影像資料全部損壞。\n後續記錄顯示，審查會主席與密斯卡托尼克大學神秘學系主任曾造訪墓園。此後，官方再未組織任何形式的勘探行動，而根據後續的監測數據，墓園濃霧僅在闖入者意圖明確時才會觸發攻擊性反應，對無意誤入者僅造成短暫方向混淆。\n至此，墓園與這座城市相安而存，只剩那些野心暗流湧動，只剩那些傳說口口相傳。\n\n——《艾瑟靈頓廢棄墓園事件調查報告》"
  },
  AwakerStory_96421_UnlockDesc = {
    Text = "同調率等級達到3"
  },
  AwakerStory_96422_Content = {
    Text = "他曾以為，自己的一生是為追求至高的美味而存在。\n王儲的職責，至親的隔閡，道德的規訓……他將這一切痛苦拋諸腦後，尋求著味覺藝術的極致。從王儲到君主，從人類到神明，一刻不曾停息。他精通了所有烹飪的方法，感知著每一具屍體最細微的差別。他得償所願，而在歡愉之後，他總覺得自己似乎遺漏了些什麼。\n直到吃下賽琳涅的屍體、見到她的魂靈的那一刻，他才幡然醒悟。那些屍體生前的故事，那些魂靈遺憾的夙願，才是他一直在追尋、一直在品味之物。\n進食是為了銘記，每一場筵席，都是亡者與生靈的重逢——杜勒賽因將這句話刻入葬骸城的王座。那些尋求他庇護之人，他將賜予他們銘記與安息。"
  },
  AwakerStory_96422_UnlockDesc = {
    Text = "同調率等級達到9"
  }
})
